window.HB_TR["job"]["ur"]=["1۔ سرزمین عز میں ایک آدمی تھا، جس کا نام {تھا} ایوب؛ اور وہ انسان کامل اور راست باز تھا، اور خدا سے ڈرتا تھا اور برائی سے بچتا تھا۔\n2۔ اور اس کے ہاں سات بیٹے اور تین بیٹیاں پیدا ہوئیں۔\n3۔ اس کی دولت بھی سات ہزار بھیڑیں، تین ہزار اونٹ، پانچ سو بیل کا جو، پانچ سو گدھا، اور ایک بہت بڑا گھرانہ تھا؛ تاکہ یہ شخص مشرق کے تمام مردوں میں سب سے بڑا تھا۔ {مادہ: یا، مویشی} {گھر: یا، دیکھ بھال} {مرد: عبرانی۔ بیٹے}\n4۔ اور اس کے بیٹے اپنے گھروں میں جا کر ہر دن ضیافت کرتے؛ اور اپنی تین بہنوں کو بھیجا اور بلایا کہ وہ ان کے ساتھ کھانا اور پیئیں۔\n5۔ اور جب [ان} کی دعوت کے دن گزر گئے، تو ایوب نے انہیں بھیجا اور مقدس بنایا، صبح سویرے اٹھا اور سب کی تعداد کے مطابق سلائی نذرانے پیش کیے: کیونکہ ایوب نے کہا، ممکن ہے میرے بیٹوں نے گناہ کیا ہو، اور اپنے دلوں میں خدا کو لعنت دی ہو۔ ایوب بھی ایسا ہی کرتا رہا۔ {مسلسل: عبرانی۔ تمام دن}\n6۔ ایک دن آیا جب خدا کے بیٹے خداوند کے سامنے آئے، اور شیطان بھی ان کے درمیان آیا۔ {شیطان: عبرانی۔ مخالف} {عبرانی کے درمیان۔ درمیان}\n7۔ اور خداوند نے شیطان سے کہا، تم کہاں سے آئے ہو؟ پھر شیطان نے خداوند کو جواب دیا اور کہا، زمین میں ادھر ادھر گھومنے سے اور اس میں اوپر نیچے چلنے سے۔\n8۔ اور خداوند نے شیطان سے کہا، کیا تم نے میرے خادم ایوب کو دیکھا ہے کہ زمین پر اس جیسا کوئی نہیں، جو خدا سے ڈرتا ہے اور برائی سے بچتا ہے؟ {غور کیا گیا: عبرانی۔ اپنا دل آن کرو}\n9۔ پھر شیطان نے خداوند کو جواب دیا اور کہا، کیا ایوب خدا سے بے وجہ ڈرتا ہے؟\n10۔ کیا تم نے اس کے بارے میں، اس کے گھر، اور اس کے ہر طرف موجود سب کچھ کے بارے میں کوئی پردہ نہیں بنایا؟ تم نے اس کے ہاتھوں کے کام کو برکت دی ہے، اور اس کی دولت زمین میں بڑھ گئی ہے۔ {مادہ: یا، مویشی}\n11۔ لیکن اب اپنا ہاتھ بڑھاؤ، اور جو کچھ اس کے پاس ہے اسے چھوؤ، تو وہ تمہیں تمہارے چہرے پر لعنت دے گا۔ {اور وہ...: عبرانی۔ اگر وہ تمہیں تمہارے سامنے لعنت نہ دے}\n12۔ اور خداوند نے شیطان سے کہا، دیکھو، جو کچھ اس کے پاس ہے وہ سب تمہارے اختیار میں ہے؛ صرف اپنے اوپر ہاتھ نہیں بڑھایا۔ تو شیطان خداوند کی موجودگی سے باہر نکل گیا۔ {پاور: عبرانی ہاتھ}\n13۔ اور ایک دن تھا جب اس کے بیٹے اور بیٹیاں اپنے بڑے بھائی کے گھر میں شراب پی رہے تھے:\n14۔ اور ایک پیغام رساں ایوب کے پاس آیا اور کہا، بیل ہل چلا رہے تھے اور گدھے ان کے ساتھ کھا رہے تھے:\n15۔ اور صابیوں نے ان پر حملہ کیا اور انہیں لے گئے؛ ہاں، انہوں نے نوکروں کو تلوار کی نوک سے مار ڈالا ہے؛ اور میں صرف اکیلا بچ سکتا ہوں کہ تمہیں بتا سکوں۔\n16۔ جب وہ ابھی بول رہا تھا، ایک اور بھی آیا اور کہا، خدا کی آگ آسمان سے گری ہے، اور اس نے بھیڑوں اور خادموں کو جلا دیا اور انہیں جلا دیا؛ اور میں صرف اکیلا بچ سکتا ہوں کہ تمہیں بتا سکوں۔ {آگ...: یا، ایک عظیم آگ}\n17۔ جب وہ ابھی بول رہا تھا، ایک اور بھی آیا اور کہا، کلدانیوں نے تین گروہ بنائے، اونٹوں پر گر گئے، اور انہیں لے گئے، ہاں، اور نوکروں کو تلوار کی نوک سے مار ڈالا؛ اور میں صرف اکیلا بچ سکتا ہوں کہ تمہیں بتا سکوں۔ {گرنا: عبرانی۔ جلدی میں}\n18۔ جب وہ ابھی بول رہا تھا، ایک اور بھی آیا اور کہا، تیرے بیٹے اور تمہاری بیٹیاں اپنے بڑے بھائی کے گھر میں شراب پی رہے تھے:\n19۔ اور دیکھو، صحرا سے ایک زبردست ہوا آئی، جس نے گھر کے چاروں کونوں پر حملہ کیا، اور نوجوانوں پر گرے، اور وہ مر گئے؛ اور میں صرف اکیلا بچ سکتا ہوں کہ تمہیں بتا سکوں۔ {سے...: عبرانی ایک طرف سے، وغیرہ}\n20۔ پھر ایوب اٹھا، اپنی چادر پھاڑی، اپنا سر منڈوا کر زمین پر گر گیا، {چادر: یا لباس}\n21۔ اور کہا، میں اپنی ماں کے پیٹ سے ننگا آیا، اور ننگا واپس آؤں گا: خداوند نے دیا، اور خداوند نے لے لیا؛ خداوند کا نام مبارک ہو۔\n22۔ اس سب میں ایوب نے نہ تو گناہ کیا اور نہ ہی خدا پر بے وقوفی کی۔ {چارج شدہ...: یا، خدا کو حماقت منسوب کیا}","1۔ ایک دن بھی آیا جب خدا کے بیٹے خداوند کے سامنے آئے، اور شیطان بھی ان کے درمیان آیا تاکہ خداوند کے سامنے خود کو پیش کرے۔\n2۔ اور خداوند نے شیطان سے کہا، تم کہاں سے آئے ہو؟ اور شیطان نے خداوند کا جواب دیا، اور کہا، زمین میں ادھر ادھر گھومنے سے اور اس میں اوپر نیچے چلنے سے۔\n3۔ اور خداوند نے شیطان سے کہا، کیا تم نے میرے خادم ایوب کو دیکھا ہے کہ زمین پر اس جیسا کوئی نہیں، جو خدا سے ڈرتا ہے اور برائی سے بچتا ہے؟ اور پھر بھی وہ اپنی دیانت داری کو مضبوطی سے تھامے ہوئے ہے، حالانکہ تم نے مجھے اس کے خلاف آمادہ کیا، تاکہ اسے بغیر وجہ کے تباہ کر دوں۔ {تباہ کرنے کے لیے...: عبرانی۔ اسے نگلنے کے لیے}\n4۔ اور شیطان نے خداوند کو جواب دیا اور کہا، \"جلد کے بدلے جلد، ہاں، وہ سب کچھ جو انسان کے پاس ہے وہ اپنی جان کے بدلے دے گا۔\n5۔ اب اپنا ہاتھ بڑھاؤ، اس کی ہڈی اور گوشت کو چھو، تو وہ تمہیں تمہارے چہرے پر لعنت دے گا۔\n6۔ اور خداوند نے شیطان سے کہا، دیکھو، وہ تمہارے ہاتھ میں ہے؛ لیکن اس کی جان بچاؤ۔ {لیکن: یا، صرف}\n7. یوں شیطان خداوند کی موجودگی سے باہر نکلا، اور ایوب کو اس کے پاؤں کی تلوے سے تاج تک زخم دار پھوڑوں سے مارا۔\n8۔ اور اس نے اسے اپنے لیے ایک مٹی کا ٹکڑا دیا؛ اور وہ راکھ کے درمیان بیٹھ گیا۔\n9۔ پھر اس کی بیوی نے اس سے کہا، کیا تم اب بھی اپنی دیانت داری رکھتے ہو؟ خدا کو لعنت دو، اور مر جاؤ۔\n10۔ لیکن اس نے اس سے کہا، تو ویسے ہی بولتی ہو جیسے ایک بے وقوف عورت بولتی ہے۔ کیا؟ کیا ہمیں خدا کے ہاتھوں بھلائی ملے گی، اور کیا ہمیں برائی نہیں ملے گی؟ ان سب میں ایوب نے اپنے ہونٹوں سے کوئی گناہ نہیں کیا۔\n11۔ جب ایوب کے تین دوستوں نے اس تمام برائی کے بارے میں سنا جو اس پر آئی تھی، تو وہ سب اس کے اپنے علاقے سے آئے؛ الیفاز تیمانی، بلداد شوحیت، اور زوفار نعمتائی: کیونکہ انہوں نے اس کے ساتھ سوگ منانے اور تسلی دینے کے لیے ایک ملاقات طے کی تھی۔\n12۔ اور جب انہوں نے دور سے نظریں اٹھائیں اور اسے نہ جانتے تھے، تو انہوں نے اپنی آواز بلند کی اور رونے لگے؛ اور انہوں نے ہر ایک کو اس کی چادر پھاڑ دی، اور ان کے سروں پر مٹی آسمان کی طرف چھڑک دی۔\n13۔ تو وہ اس کے ساتھ سات دن سات راتیں زمین پر بیٹھے، اور کسی نے اس سے ایک لفظ بھی نہ کہا، کیونکہ انہوں نے دیکھا کہ اس کا غم بہت زیادہ تھا۔","1۔ اس کے بعد ایوب نے منہ کھولا اور اس کے دن کو کوسا۔\n2۔ اور ایوب نے بولا، اور کہا، {کہا: عبرانی۔ جواب دیا گیا}\n3۔ وہ دن مر جائے جس میں میں پیدا ہوا، اور وہ رات جس میں کہا گیا، ایک مرد بچہ حاملہ ہوا۔\n4۔ وہ دن اندھیرا ہو؛ خدا اسے اوپر سے نہ دیکھے، نہ ہی روشنی اس پر چمکے۔\n5. اندھیرا اور موت کا سایہ اسے داغدار کر دے؛ ایک بادل اس پر رہے؛ دن کی تاریکی اسے خوفزدہ کر دے۔ {داغ: یا، چیلنج} {یا پھر وہ اسے خوفزدہ کر دیں، جیسے وہ لوگ جو سخت دن گزارتے ہیں}\n6۔ اس رات کے لیے، تاریکی اس پر چھا جائے؛ اسے سال کے دنوں سے نہ جوڑا جائے، نہ ہی مہینوں کی تعداد میں آ جائے۔ {ایسا نہ ہو...: یا، یہ دنوں میں خوش نہ ہو}\n7. دیکھو، وہ رات تنہا ہو، کوئی خوشی کی آواز اس میں نہ آئے۔\n8. جو دن کو لعنت دیتے ہیں، جو اپنا سوگ اٹھانے کے لیے تیار ہیں، انہیں لعنت بھیجنے دو۔ {ان کے...: یا، لیویاتھن}\n9۔ اس کے شام کے ستارے تاریک ہوں؛ اسے روشنی تلاش کرنے دو، لیکن {نہیں}؛ نہ ہی اسے دن کا طلوع آفتاب دیکھنے دے: {طلوع آفتاب...: عبرانی۔ صبح کی پلکیں}\n10۔ کیونکہ اس نے نہ تو میری ماں کے رحم کے دروازے بند کیے، نہ ہی غم کو میری آنکھوں سے چھپایا۔\n11۔ میں رحم سے کیوں نہیں مرا؟ {کیوں} جب میں پیٹ سے باہر آیا تو میں نے بھوت کو چھوڑ دیا؟\n12. گھٹنے مجھے کیوں روک رہے تھے؟ یا وہ چھاتی کیوں جو مجھے چوسنے چاہئیں؟\n13. فی الحال اگر میں خاموش لیٹ کر خاموش رہتا، تو سو جاتا: تب اگر میں آرام میں ہوتا،\n14۔ بادشاہوں اور زمین کے مشیروں کے ساتھ، جنہوں نے اپنے لیے ویران جگہیں بنائیں؛\n15۔ یا ان شہزادوں کے ساتھ جن کے پاس سونا تھا، جو اپنے گھروں کو چاندی سے بھر دیتے تھے:\n16۔ یا ایک چھپی ہوئی غیر متوقع پیدائش کے طور پر میں نہیں تھی؛ بچپن میں {جو} نے کبھی روشنی نہیں دیکھی۔\n17۔ وہاں برے لوگ پریشان کن ہونے سے رک جاتے ہیں؛ اور وہاں تھکے ہوئے آرام کرتے ہیں۔ {تھکا ہوا: عبرانی۔ طاقت میں تھکا ہوا}\n18۔ {وہاں} قیدی ایک ساتھ آرام کرتے ہیں؛ وہ ظالم کی آواز نہیں سنتے۔\n19۔ چھوٹے اور بڑے وہاں ہیں؛ اور خادم اپنے مالک سے آزاد ہو جاتا ہے۔\n20. اسی لیے جو مصیبت میں ہے اسے روشنی دی جاتی ہے، اور تلخ روح کو زندگی؛\n21۔ جو موت کی خواہش کرتے ہیں، لیکن وہ {آتی} نہیں؛ اور چھپے ہوئے خزانے سے زیادہ اس کی تلاش میں ہوں؛ {لمبا: عبرانی رکو}\n22. جو بہت خوش ہوتے ہیں، {اور} خوش ہوتے ہیں جب وہ قبر تلاش کر سکتے ہیں؟\n23. {روشنی کیوں دی جاتی ہے} اس شخص کو جس کا راستہ چھپا ہوا ہے، اور جسے خدا نے محصور کیا ہے؟\n24۔ کیونکہ میری آہیں کھانے سے پہلے آتی ہیں، اور میری دہاڑیں پانی کی طرح بہہ جاتی ہیں۔ {میں کھاتا ہوں: عبرانی۔ میرا گوشت}\n25۔ کیونکہ جس چیز سے میں بہت ڈرتا تھا وہ مجھ پر آ گئی ہے، اور جس سے میں ڈرتا تھا وہ میرے پاس آ گئی ہے۔ {وہ چیز...: عبرانی مجھے ایک خوف کا خوف تھا، اور وہ مجھ پر آ گیا}\n26. میں محفوظ نہیں تھا، نہ آرام کیا تھا، نہ خاموش تھا؛ پھر بھی مسئلہ آیا۔","1۔ پھر الیفاز تیمانی نے جواب دیا اور کہا،\n2. {اگر} ہم آپ سے رابطہ کرنے کی کوشش کریں، کیا آپ غمگین ہوں گے؟ لیکن کون خود کو بولنے سے روک سکتا ہے؟ {تو...: عبرانی ایک لفظ} {روک کر...: عبرانی الفاظ سے گریز کریں؟}\n3۔ دیکھو، تم نے بہت سے لوگوں کو تعلیم دی ہے، اور کمزور ہاتھوں کو مضبوط کیا ہے۔\n4۔ تمہارے الفاظ نے گرنے والے کو سہارا دیا، اور تم نے کمزور گھٹنوں کو مضبوط کیا۔\n5۔ لیکن اب یہ تم پر آ چکا ہے، اور تم بے ہوش ہو گئے ہو؛ یہ تمہیں چھوتا ہے، اور تم پریشان ہو جاتے ہو۔\n6. کیا یہ تمہارا خوف، تمہارا اعتماد، تمہاری امید، اور تمہارے راستوں کی درستگی نہیں ہے؟\n7. یاد رکھو، میں دعا کرتا ہوں، جو {کبھی} بے گناہ ہو کر مر گیا؟ یا راستباز کہاں کٹ گئے؟\n8۔ جیسا کہ میں نے دیکھا ہے، جو لوگ بدکاری کرتے ہیں اور بدی بوتے ہیں، وہ بھی یہی کاٹتے ہیں۔\n9۔ خدا کے جھٹکے سے وہ ہلاک ہو جاتے ہیں، اور اس کی ناک کی سانس سے وہ کھا جاتے ہیں۔ {سانس سے...: یعنی، اس کے غصے سے}\n10۔ شیر کی دھاڑ، خوفناک شیر کی آواز، اور نوجوان شیروں کے دانت ٹوٹ جاتے ہیں۔\n11۔ بوڑھا شیر شکار کی کمی کی وجہ سے مر جاتا ہے، اور موٹے شیر کے بچے باہر بکھر جاتے ہیں۔\n12۔ اب ایک چیز خفیہ طور پر میرے پاس لائی گئی، اور میرے کان نے اس کا تھوڑا سا حصہ وصول کیا۔ {خفیہ طور پر: ہیب۔ بذریعہ اسٹیلتھ}\n13۔ رات کے خوابوں کے خیالات میں، جب انسانوں پر گہری نیند آتی ہے،\n14۔ خوف نے مجھے گھیر لیا، اور کانپنے لگا، جس نے میری تمام ہڈیاں ہلا دیں۔ {آیا...: عبوری۔ met} {سب: عبرانی۔ کثرت سے}\n15۔ پھر ایک روح میرے چہرے کے سامنے گزری؛ میرے گوشت کے بال کھڑے ہو گئے:\n16۔ وہ ساکت رہی، لیکن میں اس کی شکل نہیں پہچان سکا: ایک تصویر {تھی} میری آنکھوں کے سامنے، {خاموشی} تھی، اور میں نے ایک آواز سنی، {وہاں}، {وہاں...: یا، میں نے ایک ساکت آواز سنی}\n17. کیا انسان خدا سے زیادہ منصف ہوگا؟ کیا انسان اپنے خالق سے زیادہ پاک ہوگا؟\n18۔ دیکھو، اس نے اپنے خادموں پر بھروسہ نہیں کیا؛ اور اس کے فرشتوں پر اس نے بے وقوفی کا الزام لگایا: {اور اس کے...: یا نہ ہی اپنے فرشتوں میں، جن میں اس نے روشنی ڈالی}\n19. اور ان لوگوں میں جو مٹی کے گھروں میں رہتے ہیں، جن کی بنیاد مٹی میں ہے، جو پتنگوں کے سامنے کچلے جاتے ہیں؟\n20۔ وہ صبح سے شام تک تباہ ہو جاتے ہیں: ہمیشہ کے لیے فنا ہو جاتے ہیں بغیر کسی خیال کے۔ {تباہ شدہ: عبرانی۔ ٹکڑوں میں مارا گیا}\n21. کیا ان کی عظمت {جو ان میں ہے} ختم نہیں ہوتی؟ وہ بغیر دانائی کے بھی مر جاتے ہیں۔","1۔ اگر کوئی جواب دے تو ابھی پکارو؛ اور تم کس مقدسین کی طرف رجوع کرو گے؟ {مڑنا: یا دیکھو؟}\n2۔ کیونکہ غضب بے وقوف کو مار دیتا ہے، اور حسد بے وقوف کو مار دیتا ہے۔ {حسد: یا، غصہ}\n3. میں نے بے وقوفوں کو جڑ پکڑتے دیکھا ہے: لیکن اچانک میں نے اس کے گھر پر لعنت بھیجی۔\n4۔ اس کے بچے محفوظ نہیں ہیں، اور وہ دروازے میں کچلے جاتے ہیں، نہ کوئی ہے جو انہیں پہنچا سکے۔\n5۔ جس کی فصل بھوکے کھا جاتے ہیں، کانٹوں سے بھی نکال دیتے ہیں، اور ڈاکو ان کا مال نگل لیتا ہے۔\n6۔ اگرچہ مصیبت مٹی سے نہیں آتی، زمین سے مصیبت بھی نہیں نکلتی؛ {عذاب: یا، بدکاری}\n7۔ پھر بھی انسان مصیبت کے لیے پیدا ہوتا ہے، جیسے چنگاریاں اوپر کی طرف اڑتی ہیں۔ {مسئلہ: یا، مزدور} {چنگاریاں...: عبرانی۔ جلتے ہوئے کوئلے کے بیٹے اڑنے کے لیے اٹھتے ہیں}\n8. میں خدا کی طرف تلاش کروں گا، اور خدا کے لیے اپنا مقصد وقف کروں گا:\n9۔ جو عظیم کام کرتا ہے اور تلاش سے باہر ہے؛ شمار کے بغیر شاندار چیزیں: {ناقابل تلاش: عبرانی۔ کوئی تلاش نہیں ہے} {بغیر...: عبرانی۔ جب تک کوئی تعداد نہ رہے}\n10۔ جو زمین پر بارش برساتا ہے اور کھیتوں پر پانی برساتا ہے: {کھیت: عبرانی۔ آؤٹ پلیس}\n11. اونچی سطح پر نیچے والے افراد کو مقرر کرنا؛ تاکہ جو لوگ سوگ منا رہے ہیں انہیں محفوظ مقام پر پہنچا دیا جائے۔\n12۔ وہ چالاکوں کی چالوں کو مایوس کرتا ہے، تاکہ ان کے ہاتھ اپنا کام نہ کر سکیں۔ {ان کی انٹرپرائز: یا، کوئی بھی چیز ہے}\n13۔ وہ عقلمندوں کو ان کی چالاکی میں لیتا ہے: اور شرارتی کی نصیحت پوری طرح لے جایا جاتا ہے۔\n14۔ وہ دن کے وقت اندھیرے میں ملتے ہیں، اور دوپہر میں رات کی طرح چھوتے ہیں۔ {ملنے...: یا، ٹکرا جانا}\n15۔ لیکن وہ غریبوں کو تلوار، ان کے منہ اور طاقتور کے ہاتھ سے بچاتا ہے۔\n16۔ یوں غریب کو امید ملتی ہے، اور بدکاری اس کے منہ کو روک دیتی ہے۔\n17۔ دیکھو، خوش نصیب ہے وہ شخص جسے خدا درست کرتا ہے: اس لیے قادر مطلق کی سزا کو حقیر نہ سمجھو:\n18۔ کیونکہ وہ تکلیف دیتا ہے، اور باندھتا ہے: وہ زخمی کرتا ہے، اور اس کے ہاتھ صحت یاب ہوتے ہیں۔\nانیس۔ وہ تمہیں چھ مصیبتوں میں نجات دے گا: ہاں، سات میں تمہیں کوئی برائی نہیں پہنچے گی۔\n20۔ قحط میں وہ تمہیں موت سے اور جنگ میں تلوار کی طاقت سے نجات دے گا۔ {پاور: عبرانی ہاتھ}\n21۔ تم زبان کے عذاب سے چھپ جاؤ گے: نہ ہی تباہی سے ڈرو گے جب وہ آئے گی۔ {سے...: یا، جب زبان اذیت کرتی ہے}\n22۔ تباہی اور قحط پر تم ہنسو گے: نہ ہی زمین کے جانوروں سے ڈرو گے۔\n23۔ کیونکہ تم میدان کے پتھروں کے ساتھ اتحاد کرو گے: اور میدان کے جانور تمہارے ساتھ امن میں ہوں گے۔\n24۔ اور تم جان لو گے کہ تمہارا خیمہ امن میں ہوگا؛ اور تم اپنے گھر جاؤ گے، اور گناہ نہیں کرو گے۔ {تمہارا خیم...: یا، امن تمہارا خیمہ ہے} {گناہ: یا، ارے}\n25۔ تم یہ بھی جانو گے کہ تمہاری نسل عظیم ہوگی، اور تمہاری اولاد زمین کی گھاس کی طرح ہوگی۔ {زبردست: یا، بہت زیادہ}\n26۔ تم پوری عمر میں قبر پر آؤ گے، جیسے اس کے موسم میں مکئی کا جھٹکا آتا ہے۔ {آتا ہے: عبوری۔ عروج\n27۔ دیکھیں، ہم نے اسے تلاش کیا ہے، تو یہ {ہے}؛ اسے سنو، اور جانو کہ یہ تمہاری بھلائی کے لیے ہے۔ {for...: عبرانی۔ اپنے لیے}","1۔ لیکن ایوب نے جواب دیا اور کہا،\n2. کاش میرے غم کو اچھی طرح تول دیا جاتا، اور میری آفت ایک ساتھ توازن میں ہوتی! {لیڈ: عببرانی۔ اٹھا ہوا}\n3. فی الحال یہ سمندر کی ریت سے بھی بھاری ہوگا: اس لیے میرے الفاظ نگل لیے گئے ہیں۔ {میرے الفاظ...: یعنی، میں اپنے غم کو بیان کرنے کے لیے الفاظ چاہتا ہوں}\n4۔ کیونکہ قادر مطلق کے تیر میرے اندر ہیں، وہ زہر جس سے میری روح پیتا ہے: خدا کے خوف میرے خلاف کھڑے ہو جاتے ہیں۔\n5. کیا جنگلی پچھواڑے کی آواز اس وقت ہوتی ہے جب اس کے پاس گھاس ہو؟ یا بیل کو اس کے چارے پر نیچا دے؟ {جب وہ...: عبرانی۔ گھاس پر؟}\n6. کیا ناپسندیدہ چیز کو نمک کے بغیر کھایا جا سکتا ہے؟ یا انڈے کی سفیدی میں کوئی ذائقہ ہے؟\n7۔ وہ چیزیں جنہیں میری روح نے چھونے سے انکار کیا {وہ ہیں} میرا غمگین گوشت ہیں۔\n8۔ کاش میری درخواست مل جائے؛ اور خدا مجھے وہ چیز دے گا جس کی میں آرزو کرتا ہوں! {وہ چیز...: عبرانی میری توقع}\n9۔ یہاں تک کہ خدا کو یہ پسند آئے گا کہ وہ مجھے تباہ کرے؛ کہ وہ اپنا ہاتھ چھوڑ دے گا، اور مجھے روک دے گا!\n10۔ تو کیا مجھے ابھی بھی تسلی ملنی چاہیے؛ ہاں، میں غم میں خود کو سخت کروں گا: اسے معاف نہ کرنے دو؛ کیونکہ میں نے مقدس کے الفاظ چھپائے نہیں۔\n11. میری طاقت کیا ہے، جس کی مجھے امید کرنی چاہیے؟ اور میرا انجام کیا ہے کہ میں اپنی زندگی کو لمبا کروں؟\n12. کیا میری طاقت پتھروں کی طاقت ہے؟ یا {کیا} میرا پیتل کا گوشت ہے؟ {براس کا: عبرانی۔ براسن؟}\n13۔ {کیا} میری مدد نہیں ہے؟ اور کیا حکمت مجھ سے کافی دور رہتی ہے؟\n14۔ جس شخص کو اس کے دوست کی طرف سے رحم دکھایا جائے {ظاہر کیا جائے}؛ لیکن وہ قادر مطلق کے خوف کو ترک کر دیتا ہے۔ {متاثرہ ہے: عبرانی۔ melteth}\n15۔ میرے بھائیوں نے دھوکہ دہی سے ایک ندی کی طرح پیش کیا ہے، {اور} ندیوں کی ندی کی طرح وہ گزر جاتے ہیں؛\n16۔ جو برف کی وجہ سے سیاہ مائل ہیں، {اور} جس میں برف چھپی ہوئی ہے:\n17۔ جب وہ گرم ہوتے ہیں، تو غائب ہو جاتے ہیں: جب گرم ہوتے ہیں تو وہ اپنی جگہ سے باہر ہو جاتے ہیں۔ {غائب ہو گئے: عبرانی۔ کٹ آف ہوتے ہیں} {جب...: عبرانی۔ اس کی گرمی میں} {استعمال شدہ: عبرانی۔ بجھ گئی}\n18۔ ان کے راستے موڑ دیے جاتے ہیں؛ وہ کچھ نہیں کھو جاتے اور فنا ہو جاتے ہیں۔\n19۔ تیما کی فوجیں دیکھ رہی تھیں، سبا کی کمپنیاں ان کا انتظار کر رہی تھیں۔\n20۔ وہ الجھن میں تھے کیونکہ انہوں نے امید کی تھی؛ وہ وہاں آئے، اور شرمندہ ہوئے۔\n21. فی الحال تم کچھ نہیں ہو؛ تم دیکھو {میرا} نیچے پھینک رہا ہے، اور ڈر جاتے ہو۔ {تم ہو...: یا، تم ان کے لیے ہو: عبرانی۔ اس کے لیے} {کچھ نہیں: عبرانی۔ نہیں}\n22۔ کیا میں نے کہا، میرے پاس لے آؤ؟ یا، میرے لیے اپنی اصل چیز کا انعام دو؟\n23۔ یا، مجھے دشمن کے ہاتھوں سے بچانا؟ یا، مجھے طاقتور کے ہاتھ سے نجات دے؟\n24۔ مجھے سکھاؤ، اور میں اپنی زبان روک لوں گا: اور مجھے سمجھاؤ کہ میں کہاں غلطی کر چکا ہوں۔\n25. صحیح الفاظ کتنے زبردستی ہیں! لیکن آپ کی دلیل کس چیز کو ملاتی ہے؟\n26۔ کیا تم تصور کرتے ہو کہ کسی مایوس شخص کی باتوں اور الفاظ کو سرزنش کرو، جو ہوا کی طرح ہیں؟\n27. ہاں، تم یتیم کو مغلوب کرتے ہو، اور اپنے دوست کے لیے گڑھا کھودتے ہو۔ {ye overwhelmed: عبرانی۔ تم گرنے کی وجہ ہو}\n28۔ اب مطمئن ہو جاؤ، میری طرف دیکھو؛ کیونکہ اگر میں جھوٹ بولوں تو یہ آپ پر واضح ہے۔ {واضح...: عبرانی۔ تمہارے چہرے کے سامنے}\n29۔ واپس آؤ، میں تم سے دعا کرتا ہوں، یہ بدکاری نہ ہو؛ ہاں، دوبارہ لوٹ آؤ، میری راستبازی {ہے} اس میں۔ {اس میں: یعنی، اس معاملے میں}\n30. کیا میری زبان میں بدکاری ہے؟ کیا میرا ذوق بگڑی ہوئی چیزوں کو پہچان نہیں سکتا؟ {میرا ذوق: عبرانی۔ میرا ذائقہ}","1. {کیا} انسان کے لیے زمین پر کوئی مقررہ وقت نہیں ہے؟ کیا اس کے دن بھی کرائے کے دن جیسے نہیں ہیں؟ {ایک مقررہ...: یا، ایک جنگ}\n2. جیسے خادم سائے کی شدت سے خواہش کرتا ہے، اور جیسے کوئی مزدور اپنے کام کے بدلے کی تلاش میں ہوتا ہے: {مخلص...: عبرانی۔ گیپتھ آفٹر}\n3. اسی طرح مجھے مہینوں کی غرور کا مالک بنایا گیا ہے، اور تھکا دینے والی راتیں میرے لیے مقرر کی گئی ہیں۔\n4۔ جب میں لیٹتا ہوں، میں کہتا ہوں، میں کب اٹھوں گا، اور رات کب ختم ہو جائے گی؟ اور میں دن کی صبح تک ادھر گھومتا ہوں۔ {رات...: عبرانی۔ شام کو ناپا جا سکتا ہے؟}\n5. میرا جسم کیڑے اور گرد کے ڈھیر سے ڈھکا ہوا ہے؛ میری جلد ٹوٹ چکی ہے، اور نفرت انگیز ہو جاتی ہے۔\n6. میرے دن بننے والے کے شٹل سے تیز ہوتے ہیں، اور بے امید گزرتے ہیں۔\n7. اے یاد رکھو کہ میری زندگی ہوا ہے: میری آنکھ اب اچھائی نہیں دیکھ سکتی۔ {ہوگا...: عبرانی واپس نہیں آئے گا} {دیکھیں: دیکھنا، یعنی، لطف اندوز ہونا}\n8۔ جس نے مجھے دیکھا ہے اس کی آنکھ مجھے مزید نہیں دیکھے گی: تمہاری آنکھیں مجھ پر ہیں، اور میں نہیں۔ میں ہوں...: یعنی، میں مزید زندہ نہیں رہ سکتا}\n9. {جیسا کہ} بادل نگل جاتا ہے اور غائب ہو جاتا ہے: تو جو قبر تک جائے گا وہ دوبارہ اوپر نہیں آئے گا۔\n10۔ وہ اب اپنے گھر واپس نہیں جائے گا، نہ ہی اس کی جگہ اسے جانتی رہے گی۔\n11. اس لیے میں اپنی زبان روک نہیں سکوں گا؛ میں اپنی روح کے درد میں بات کروں گا؛ میں اپنی تلخی میں شکایت کروں گا۔\n12. {کیا }میں سمندر ہوں، یا وہیل، جسے تم میری نگرانی کرتے ہو؟\n13۔ جب میں کہوں، میرا بستر مجھے سکون دے گا، میرا صوفہ میری شکایت کو کم کرے گا؛\n14۔ تو تو مجھے خوابوں سے ڈرا دیتے ہو، اور خوابوں سے ڈرا دیتے ہو:\n15۔ تاکہ میری روح گلا گھونٹنے اور موت کو اپنی زندگی کے بجائے چنے دے۔ {زندگی: عبرانی۔ ہڈیا}\n16. میں اس سے نفرت کرتا ہوں؛ میں ہمیشہ زندہ نہیں رہوں گا: مجھے اکیلا چھوڑ دو؛ میرے دن {ہیں} خود پسندی۔\n17. انسان کیا ہے کہ تم اسے جلال بخشو؟ اور کہ تم اپنا دل اس پر رکھو؟\n18۔ اور یہ کہ تمہیں ہر صبح اس سے ملنے جانا چاہیے، اور ہر لمحہ اسے آزمانا چاہیے؟\n19۔ کب تک تم مجھ سے دور نہیں رہو گے، اور مجھے اکیلا چھوڑو گے جب تک میں اپنا تھوک نگل نہ لوں؟\n20۔ میں نے گناہ کیا ہے؛ میں تمہارے ساتھ کیا کروں، اے انسانوں کے محافظ؟ تم نے مجھے اپنے خلاف نشانہ کیوں بنایا، تاکہ میں اپنے لیے بوجھ بن جاؤں؟\n21. اور تم میری گناہ کو معاف کیوں نہیں کرتے، اور میری گناہ کیوں نہیں چھین لیتے؟ اب میں مٹی میں سوؤں گا؛ اور تم صبح مجھے تلاش کرو گے، لیکن میں نہیں ہوں گا۔","1۔ پھر بلداد الشحیت نے جواب دیا اور کہا،\n2. تم یہ {باتیں} کب تک بولو گے؟ اور {کتنی دیر تک} تمہارے منہ کے الفاظ {تیز ہوا کی طرح رہیں گے؟'\n3۔ کیا خدا فیصلے کو بگاڑتا ہے؟ یا قادر مطلق انصاف کو بگاڑتا ہے؟\n4۔ اگر تمہارے بچوں نے اس کے خلاف گناہ کیا ہے، اور اس نے انہیں ان کی زیادتی کی وجہ سے پھینک دیا ہے؛ {for...: عبرانی۔ ان کی گناہ کے ہاتھوں میں}\n5. اگر تم کبھی کبھار خدا سے دعا کرنا چاہتے ہو، اور قادر مطلق سے دعا کرو؛\n6۔ اگر تم صاف اور سیدھا ہو؛ یقینا اب وہ تمہارے لیے جاگے گا، اور تمہاری راستبازی کے گھر کو خوشحال بنائے گا۔\n7۔ اگرچہ تمہاری شروعات چھوٹی تھی، پھر بھی تمہارا آخری انجام بہت بڑھ جائے گا۔\n8۔ پوچھنے کے لیے، میں تم سے درخواست کرتا ہوں، جو پرانے زمانے کے ہیں، اور اپنے آپ کو ان کے آباؤ اجداد کی تلاش کے لیے تیار کرو:\n9۔ (کیونکہ ہم {کل کے ہیں} اور کچھ نہیں جانتے، کیونکہ ہمارے زمین پر دن {سایہ} ہیں:) {کچھ نہیں: عبرانی۔ نہیں}\n10. کیا وہ تمہیں نہیں سکھائیں گے، {اور} تمہیں بتائیں گے، اور دل سے الفاظ نہیں بولیں گے؟\n11. کیا رش بغیر کیچڑ کے بڑھ سکتا ہے؟ کیا جھنڈا بغیر پانی کے بڑھ سکتا ہے؟\n12. جب تک یہ {ہے} اپنی سبزی میں، {اور} کاٹا نہیں، یہ کسی بھی {اور} جڑی بوٹی کے سامنے مرجھا جاتا ہے۔\n13. خدا کو بھولنے والوں کے راستے بھی اسی طرح ہیں؛ اور منافق کی امید ختم ہو جائے گی:\n14. جس کی امید ختم ہو جائے گی، اور جس کا اعتماد مکڑی کے جال پر ہوگا۔ {ویب: عبرانی۔ گھر}\n15۔ وہ اپنے گھر پر جھکے گا، لیکن وہ کھڑا نہیں ہوگا: وہ اسے مضبوطی سے پکڑے گا، لیکن یہ قائم نہیں رہے گا۔\n16۔ وہ سورج کے سامنے سبز ہے، اور اس کی شاخ اس کے باغ میں نکلتی ہے۔\n17۔ اس کی جڑیں ڈھیر کے گرد لپٹی ہوئی ہیں، {اور} پتھروں کی جگہ ابلتی ہے۔\n18۔ اگر وہ اسے اس کی جگہ سے تباہ کر دے، تو وہ اسے انکار کرے گا، اور کہے گا، میں نے تمہیں نہیں دیکھا۔\n19۔ دیکھو، یہ اس کے راستے کی خوشی ہے، اور زمین سے دوسرے بھی اگیں گے۔\n20۔ دیکھو، خدا کامل {انسان} کو نہیں چھوڑے گا، نہ ہی وہ برے لوگوں کی مدد کرے گا: {مدد...: عبرانی۔ بے دین کو ہاتھ پکڑو} {آؤ: عبرانی۔ نہیں ہو سکتا}\n21. جب تک وہ تمہارے منہ کو ہنسی سے بھر دے، اور تمہارے ہونٹ خوشی سے بھر دے۔ {خوشی سے: عبرانی۔ خوشی سے چیخنا}\n22۔ جو تم سے نفرت کریں گے وہ شرم کے لباس میں ملبوس ہوں گے؛ اور بدکاروں کا مسکن ختم ہو جائے گا۔ {آئے گا...: عبرانی۔ نہیں ہو سکتا}","1۔ پھر ایوب نے جواب دیا اور کہا،\n2. میں جانتا ہوں کہ یہ سچ ہے: لیکن انسان کو خدا کے ساتھ انصاف کیسے کرنا چاہیے؟ {خدا کے ساتھ: یا، خدا کے سامنے؟}\n3۔ اگر وہ اس سے مقابلہ کرے تو ہزار میں سے ایک جواب نہیں دے سکتا۔\n4۔ {وہ} دل میں دانا اور طاقت میں طاقتور ہے: جس نے [خود کو] اس کے خلاف سخت کیا اور خوشحال ہوا؟\n5۔ جو پہاڑوں کو ہٹا دیتا ہے، اور وہ نہیں جانتے: جو انہیں اپنے غصے میں الٹ دیتا ہے۔\n6۔ جو زمین کو اس کی جگہ سے ہلا دیتا ہے، اور اس کے ستون کانپنے لگتے ہیں۔\n7۔ جو سورج کو حکم دیتا ہے، اور وہ طلوع نہیں ہوتا؛ اور ستاروں کو سیل کر دیتا ہے۔\n8۔ جو صرف آسمانوں کو پھیلاتا ہے، اور سمندر کی لہروں پر چلتا ہے۔ {لہریں: عبرانی۔ ہائٹس}\n9۔ جو آرکٹورس، اوریون، اور پلیئڈیز اور جنوب کے کمروں کو بناتا ہے۔ {آرکٹورس...: عبرانی۔ ایش، سیسل، اور سیماہ}\n10۔ جو جاننے سے آگے بھی عظیم کام کرتا ہے؛ ہاں، اور بے شمار عجائبات بھی۔\n11۔ دیکھو، وہ میرے پاس سے گزرتا ہے، اور میں اسے نہیں دیکھتا: وہ بھی گزرتا ہے، لیکن میں اسے نہیں دیکھتا۔\n12. دیکھو، وہ لے جاتا ہے، کون اسے روک سکتا ہے؟ کون اس سے کہے گا، تم کیا کرتے ہو؟ {رکاوٹ...: عببرانی۔ اسے واپس بھیج دوں؟}\n13. {اگر} خدا اپنا غصہ واپس نہیں لے گا، تو مغرور مددگار اس کے نیچے جھک جاتے ہیں۔ {فخر...: عبرانی غرور یا طاقت کے مددگار}\n14. میں اسے جواب دینے کے لیے کتنا کم کروں، {اور} اپنے الفاظ چن کر اس سے بات کروں؟\n15۔ کس کو، اگرچہ میں راستباز ہوں، {پھر بھی} جواب نہیں دوں گا، {لیکن} میں اپنے جج سے دعا کروں گا۔\n16۔ اگر میں نے پکارا ہوتا، اور اس نے جواب دیا ہوتا؛ {پھر بھی} میں یقین نہیں کروں گا کہ اس نے میری آواز سنی ہو۔\n17۔ کیونکہ وہ مجھے طوفان سے توڑتا ہے، اور میرے زخموں کو بے وجہ بڑھاتا ہے۔\n18۔ وہ مجھے سانس لینے نہیں دے گا، بلکہ مجھے تلخی سے بھر دیتا ہے۔\n19۔ اگر {میں طاقت کی بات کرتا ہوں}، دیکھو، {وہ} مضبوط ہے: اور اگر فیصلے کا ہے، تو کون مجھے وقت {درخواست کرنے کی} دے گا؟\n20۔ اگر میں خود کو درست ثابت کروں، تو میرا اپنا منہ مجھے ملامت کرے گا: {اگر میں کہوں} تو میں {کامل} ہوں، تو یہ بھی مجھے بگاڑ ثابت کرے گا۔\n21۔ {اگرچہ} میں {تھا} کامل تھا، {پھر بھی} میں اپنی روح کو نہ جانتا: میں اپنی زندگی سے نفرت کرتا۔\n22. یہ {ہے} ایک {چیز}، اس لیے میں نے کہا {وہ}، وہ کامل اور بدکاروں کو تباہ کرتا ہے۔\n23۔ اگر اسکورج اچانک قتل کر دے تو وہ معصوموں کے مقدمے پر ہنسے گا۔\n24۔ زمین بدکاروں کے ہاتھ میں دی جاتی ہے: وہ اس کے ججوں کے چہروں کو ڈھانپتا ہے؛ اگر نہیں، تو کہاں، {اور} وہ کون ہے؟\n25۔ اب میرے دن ایک پوسٹ سے بھی تیز ہیں: وہ بھاگ جاتے ہیں، وہ کچھ اچھا نہیں دیکھتے۔\n26۔ وہ تیز رفتار جہازوں کی طرح مر جاتے ہیں: جیسے عقاب {جو} شکار کی طرف دوڑتا ہے۔ {تیز رفتار...: یا، ایبے: عبرانی کے جہاز۔ خواہش کے جہاز}\n27. اگر میں کہوں، میں اپنی شکایت بھول جاؤں گا، تو میں اپنی بھاری پن کو چھوڑ دوں گا، اور خود کو تسلی دوں گا:\n28۔ میں اپنے تمام غموں سے ڈرتا ہوں، میں جانتا ہوں کہ تم مجھے بے قصور نہیں سمجھو گے۔\n29۔ {اگر} میں بدکار ہوں، تو پھر میں بے سود محنت کیوں کرتا ہوں؟\n30۔ اگر میں برف کے پانی سے خود کو دھوؤں، اور اپنے ہاتھوں کو کبھی صاف نہ کروں؛\n31. پھر بھی تم مجھے کھائی میں ڈال دو گے، اور میرے اپنے کپڑے مجھے ناپسند کریں گے۔ {نفرت...: یا، مجھے نفرت انگیز بنا دو}\n32. کیونکہ {وہ} انسان نہیں ہے، جیسا کہ میں ہوں} کہ میں اسے جواب دوں، {اور} ہمیں مل کر فیصلہ کرنا چاہیے۔\n33۔ نہ ہی ہمارے درمیان کوئی دن کا آدمی ہے جو ہم دونوں پر ہاتھ اٹھا سکے۔ {کبھی...: ہیب۔ ایک ایسا جو دلیل دے} {daysman: or, umpire}\n34۔ وہ اپنی چھڑی مجھ سے لے لے، اور اس کا خوف مجھے خوفزدہ نہ کرے:\n35۔ {پھر} میں بولوں گا، اور اس سے نہ ڈروں؛ لیکن میرے ساتھ ایسا نہیں ہے۔ {یہ ہے...: عبرانی۔ میں اپنے آپ کے ساتھ ایسا نہیں ہوں}","1. میری روح اپنی زندگی سے تھک چکی ہے؛ میں اپنی شکایت خود پر چھوڑ دیتا ہوں؛ میں اپنی تلخی میں بات کروں گا۔ {تھکا ہوا...: یا، جب تک میں زندہ ہوں، کٹ جاؤ}\n2. میں خدا سے کہوں گا، مجھے ملامت نہ کر؛ مجھے دکھاؤ کہ تم مجھ سے کہاں لڑتے ہو۔\n3. کیا یہ تمہارے لیے اچھا ہے کہ تم ظلم کرو، اپنے ہاتھوں کے کام کو حقیر سمجھو، اور بدکاروں کی نصیحت پر روشنی ڈالو؟ {کام: عبرانی۔ لیبر}\n4. کیا تمہاری آنکھیں گوشت جیسی ہیں؟ یا تم دیکھتے ہو جیسے انسان بھڑکتا ہے؟\n5. کیا آپ کے دن انسان کے دن ہیں؟ {ہیں} تمہارے سال انسانوں کے دنوں کی طرح ہیں،\n6۔ کہ تم میری گناہوں کی تلاش کرو، اور میرے گناہ کی تلاش کرو؟\n7۔ تم جانتے ہو کہ میں بدکار نہیں ہوں؛ اور {کوئی نہیں} جو تمہارے ہاتھ سے نجات دے سکے۔ {تم...: عبرانی۔ یہ تمہارے علم پر ہے}\n8۔ تمہارے ہاتھوں نے مجھے بنایا اور میرے گرد جوڑا ہے؛ پھر بھی تم مجھے تباہ کر دیتے ہو۔ {have...: عبرانی میرے بارے میں بہت خیال رکھا}\n9۔ یاد رکھو، میں تم سے التجا کرتا ہوں، کہ تم نے مجھے مٹی کی طرح بنایا ہے؛ اور کیا تم مجھے دوبارہ خاک میں لے آؤ گے؟\n10۔ کیا تم نے مجھے دودھ کی طرح نہیں ڈالا اور پنیر کی طرح نہیں رکھا؟\n11۔ تو نے مجھے کھال اور گوشت سے کپڑے پہنائے ہیں، اور ہڈیوں اور ریشوں سے باڑ لگا دی ہے۔ {فینسڈ: عبوری۔ ہیجڈ}\n12۔ تو نے مجھے زندگی اور عنایت دی، اور تمہاری آمد نے میری روح کو محفوظ رکھا۔\n13۔ اور یہ {چیزیں} تو نے اپنے دل میں چھپائی ہیں: میں جانتا ہوں کہ یہ {تمہارے} کے ساتھ ہے۔\n14۔ اگر میں گناہ کروں، تو تم مجھے نشان زد کرتے ہو، اور تم مجھے میری گناہوں سے بری نہیں کرو گے۔\n15۔ اگر میں بدکار ہوں، تو مجھ پر افسوس؛ اور {اگر} میں نیک ہوں، {پھر بھی} میں اپنا سر نہیں اٹھاؤں گا۔ {میں} الجھن سے بھرا ہوا ہوں؛ لہٰذا میری مصیبت دیکھو؛\n16۔ کیونکہ یہ بڑھتا ہے۔ تم مجھے ایک خوفناک شیر کی طرح شکار کرتے ہو: اور پھر تم مجھ پر حیرت انگیز نظر آتے ہو۔\n17۔ تو میرے خلاف اپنے گواہ تازہ کرتے ہو، اور مجھ پر اپنا غصہ بڑھاتے ہو؛ تبدیلیاں اور جنگ میرے خلاف ہیں۔ {گواہ: یعنی، وباء}\n18۔ تو پھر تم نے مجھے رحم سے کیوں نکالا؟ کاش میں نے بھوت کو چھوڑ دیا ہوتا، اور کوئی آنکھ مجھے نہ دیکھتی!\n19۔ مجھے ایسا ہونا چاہیے تھا جیسے میں نہیں تھا؛ مجھے رحم سے قبر تک لے جانا چاہیے تھا۔\n20۔ {کیا} میرے دن کم نہیں ہیں؟ پھر رک جاؤ {اور} مجھے اکیلا چھوڑ دو، تاکہ میں تھوڑا سا سکون پا سکوں،\n21. جانے سے پہلے {جہاں سے} میں واپس نہیں جاؤں گا، {حتیٰ کہ} تاریکی کی سرزمین اور موت کے سائے میں بھی؛\n22۔ تاریکی کی سرزمین، جیسے خود اندھیرا؛ اور موت کے سائے کی، بغیر کسی ترتیب کے، اور جہاں روشنی {ہے} جیسے تاریکی۔","1۔ پھر زوفار نامتی نے جواب دیا اور کہا،\n2. کیا الفاظ کی کثرت کا جواب نہیں دینا چاہیے؟ اور کیا باتونی آدمی کو جائز قرار دیا جانا چاہیے؟ {مکمل...: عببرانی۔ ہونٹوں سے}\n3۔ کیا تمہارے جھوٹ لوگوں کو خاموش رکھ سکتے ہیں؟ اور جب تم مذاق اڑاتے ہو، تو کیا کوئی تمہیں شرمندہ نہیں کرے گا؟ {جھوٹ: یا، آلات}\n4۔ کیونکہ تو نے کہا ہے، میری تعلیم {پاک} ہے، اور میں تیری نظر میں پاک ہوں۔\n5۔ لیکن کاش خدا بولے، اور تمہارے خلاف اپنے ہونٹ کھولے؛\n6۔ اور کہ وہ تمہیں حکمت کے راز دکھائے گا، کہ وہ حقیقت سے دوگنا ہیں! لہٰذا جان لو کہ خدا تم سے {کم} تمہاری گناہ {مستحق} سے کم کرتا ہے۔\n7۔ کیا آپ تلاش کر کے خدا کو تلاش کر سکتے ہیں؟ کیا تم قادر مطلق کو مکمل طور پر جان سکتے ہو؟\n8. {یہ} آسمان جتنا بلند ہے؛ تم کیا کر سکتے ہو؟ جہنم سے بھی گہرا؛ تم کیا جان سکتے ہو؟ {جتنا اونچا...: عبرانی۔ جنت کی بلندی}\n9۔ اس کی پیمائش زمین سے لمبی اور سمندر سے چوڑی ہے۔\n10۔ اگر وہ بات کاٹ دے، خاموش ہو جائیں، یا اکٹھے ہو جائیں، تو پھر کون اسے روک سکتا ہے؟ {کٹ...: یا، تبدیلی کریں} {رکاوٹ...: عببرانی۔ اسے واپس بھیج دوں؟}\n11۔ کیونکہ وہ فضول لوگوں کو جانتا ہے: وہ برائی بھی دیکھتا ہے؛ کیا وہ پھر اس پر غور نہیں کرے گا؟\n12. کیونکہ فضول انسان عقلمند ہوگا، چاہے انسان جنگلی گدھے کے گھوڑے کی طرح پیدا ہو۔ {vanin: Hebrew. خالی}\n13۔ اگر تم اپنا دل تیار کرو، اور اپنے ہاتھ اس کی طرف بڑھاؤ؛\n14۔ اگر بدکاری تمہارے ہاتھ میں ہے، تو اسے دور رکھ دو، اور برائی کو تمہارے خیموں میں نہ رہنے دو۔\n15۔ تب تم اپنا چہرہ بغیر داغ اٹھاؤ گے؛ ہاں، تم مضبوطی سے قائم رہو گے، اور ڈرو مت:\n16. کیونکہ تم اپنی مصیبت کو بھول جاؤ گے، {اور} اسے یاد رکھو گے جیسے پانی {جو گزر جائے}:\n17۔ اور آپ کی عمر دوپہر سے زیادہ واضح ہوگی؛ تم چمکو گے، تم صبح کی طرح رہو گے۔ {واضح کریں...: عبوری۔ اوپر اٹھو}\n18۔ اور تم محفوظ رہو گے، کیونکہ امید ہے؛ ہاں، تم اپنے ارد گرد کھدائی کرو گے، اور} تم محفوظ آرام کرو گے۔\n19۔ اور تم لیٹ جاؤ گے، اور کوئی تمہیں خوفزدہ نہیں کرے گا؛ ہاں، بہت سے لوگ تمہارے حق میں آئیں گے۔ {سوٹ بنائیں...: ہیب۔ اپنے چہرے کی التجا کرو}\n20۔ لیکن بدکاروں کی آنکھیں ختم ہو جائیں گی، اور وہ بچ نہیں سکیں گی، اور ان کی امید {بھوت کی ہار ماننے کی طرح} ہوگی۔ {وہ آئیں گے...: عبرانی۔ ان سے فرار ختم ہو جائے گا} {دینے والا...: یا، ایک سانس کا جھونکا}","1۔ اور ایوب نے جواب دیا اور کہا،\n2. یقینا آپ لوگ ہیں، اور حکمت آپ کے ساتھ مر جائے گی۔\n3۔ لیکن میں بھی آپ کی طرح سمجھتا ہوں؛ میں آپ سے کمتر نہیں ہوں: ہاں، کون نہیں جانتا کہ ایسی چیزیں کیا ہیں؟ {سمجھ: عبرانی۔ ایک دل} {میں ہوں...: عبرانی میں تم سے نیچے نہیں آتا} {کون...: عبرانی۔ ایسے کس کے ساتھ نہیں ہیں؟}\n4. میں وہ ہوں جو اپنے پڑوسی کا مذاق اڑاتا ہے، جو خدا کو پکارتا ہے، اور وہ اس کا جواب دیتا ہے: نیک انسان کو حقارت سے ہنسایا جاتا ہے۔\n5. جو اپنے پیروں سے پھسلنے کو تیار ہے، وہ ایک چراغ کی طرح ہے جسے اس کے خیال میں حقیر سمجھا جاتا ہے جو آرام دہ ہے۔\n6۔ ڈاکوؤں کے خیمے خوشحال ہوتے ہیں، اور جو خدا کو اکساتے ہیں وہ محفوظ ہیں؛ جس کے ہاتھ میں خدا {کثرت سے} لاتا ہے۔\n7. لیکن اب جانوروں سے پوچھو، وہ تمہیں سکھائیں گے؛ اور ہوا کے پرندے، اور وہ تمہیں بتائیں گے:\n8۔ یا زمین سے بات کرو، تو وہ تمہیں سکھائے گی: اور سمندر کی مچھلیاں تمہیں بتائیں گی۔\n9۔ کون نہیں جانتا کہ ان سب میں خداوند کے ہاتھ نے یہ کیا ہے؟\n10۔ جس کے ہاتھ میں ہر جاندار کی روح اور تمام انسانیت کی سانس ہے۔ {روح: یا، زندگی} {سب...: عبرانی۔ تمام انسان کا گوشت}\n11۔ کیا کان الفاظ آزماتا نہیں؟ اور منہ اس کے گوشت کا ذائقہ چکھتا ہے؟ {منہ: عبرانی۔ ذائقہ}\n12۔ قدیم {is} حکمت کے ساتھ؛ اور دنوں کی لمبائی میں سمجھ بوجھ سے۔\n13۔ اس کے ساتھ حکمت اور طاقت ہے، اس کے پاس مشورہ اور سمجھ ہے۔ {ساتھ...: یعنی، خدا کے ساتھ}\n14۔ دیکھو، وہ ٹوٹ جاتا ہے، اور اسے دوبارہ تعمیر نہیں کیا جا سکتا: وہ ایک آدمی کو بند کر دیتا ہے، اور کوئی راستہ نہیں ہو سکتا۔ {اوپر: عبوری۔ upon}\n15۔ دیکھو، وہ پانی روک لیتا ہے، اور وہ خشک ہو جاتے ہیں: اور وہ انہیں باہر بھیجتا ہے، اور وہ زمین کو الٹ دیتے ہیں۔\n16. اس کے ساتھ طاقت اور حکمت ہے: دھوکہ باز اور دھوکہ باز اس کے ہیں۔\n17۔ وہ مشیروں کو بگاڑ کر لے جاتا ہے، اور ججوں کو بے وقوف بناتا ہے۔\n18۔ وہ بادشاہوں کی بندھن کو کھولتا ہے، اور ان کی کمر کو بیلٹ سے باندھتا ہے۔\n19۔ وہ شہزادوں کو بگڑا ہوا لے جاتا ہے، اور طاقتوروں کو گرا دیتا ہے۔\n20۔ وہ امانت داروں کی تقریر کو دور کر دیتا ہے، اور بزرگوں کی سمجھ چھین لیتا ہے۔ {گفتگو...: عبرانی۔ وفاداروں کا ہونٹ}\n21۔ وہ شہزادوں پر حقارت کرتا ہے، اور طاقتوروں کی طاقت کو کمزور کرتا ہے۔ {کمزور ہو جاتا ہے...: یا، طاقتور کی بیلٹ ڈھیلی کر دیتی ہے}\n22۔ وہ اندھیرے سے گہری چیزیں دریافت کرتا ہے، اور موت کے سایہ کو روشن کرنے کے لیے لاتا ہے۔\n23۔ وہ قوموں کو بڑھاتا ہے، انہیں تباہ کرتا ہے: قوموں کو بڑھاتا ہے، اور انہیں دوبارہ محدود کرتا ہے۔ {straiteneth: عبرانی۔ لیڈیتھ ان}\n24۔ وہ زمین کے لوگوں کے سردار کے دل کو لے جاتا ہے، اور انہیں ویرانے میں چھوڑ دیتا ہے {جہاں کوئی راستہ نہیں}۔\n25۔ وہ روشنی کے بغیر اندھیرے میں چھوتے ہیں، اور وہ انہیں نشے میں دھت {آدمی} کی طرح لڑکھڑاتا ہے۔ {ہچکچاہٹ: عبرانی۔ وانڈر}","1۔ دیکھو، میری آنکھ نے یہ سب دیکھ لیا ہے، میرے کان نے سنا اور سمجھا ہے۔\n2۔ جو تم جانتے ہو، {وہی} میں بھی جانتا ہوں: میں تم سے کمتر نہیں ہوں۔\n3. یقینا میں قادر مطلق سے بات کرنا چاہتا ہوں، اور خدا سے دلیل کرنا چاہتا ہوں۔\n4. لیکن تم جھوٹ بولنے والے ہو، تم سب بے وقعت طبیب ہو۔\n5. کاش تم مکمل طور پر خاموش رہو! اور یہ آپ کی حکمت ہونی چاہیے۔\n6۔ اب میری دلیل سنو، اور میرے ہونٹوں کی التجا سنو۔\n7۔ کیا آپ خدا کے لیے برے الفاظ میں بات کریں گے؟ اور اس کے لیے دھوکہ دہی سے بات کروں؟\n8. کیا آپ اس کی شخصیت کو قبول کریں گے؟ کیا تم خدا کے لیے لڑو گے؟\n9. کیا یہ اچھا ہے کہ وہ تمہیں تلاش کرے؟ یا جیسے ایک آدمی دوسرے کا مذاق اڑاتا ہے، کیا آپ اس کا مذاق اڑاتے ہیں؟\n10۔ اگر تم خفیہ طور پر لوگوں کو قبول کرو تو وہ تمہیں ضرور ملامت کرے گا۔\n11۔ کیا ان کی عظمت آپ کو خوفزدہ نہیں کرے گی؟ اور اس کا خوف تم پر چھا گیا؟\n12. آپ کی یادیں راکھ کی مانند ہیں، آپ کے جسم مٹی کے جسموں کی مانند ہیں۔\n13۔ خاموش رہو، مجھے اکیلا چھوڑ دو، تاکہ میں بول سکوں، اور جو چاہے میرے اوپر آ جائے۔ {ہولڈ...: عبوری۔ مجھ سے خاموش رہو}\n14. میں اپنا گوشت دانتوں میں کیوں لیتا ہوں، اور اپنی جان اپنے ہاتھ میں کیوں دیتا ہوں؟\n15۔ اگرچہ وہ مجھے مار دے، میں اس پر بھروسہ کروں گا: لیکن میں اس کے سامنے اپنے راستے قائم رکھوں گا۔ {برقرار رکھنا: عبرانی۔ ثابت کریں، یا، دلیل دیں}\n16۔ وہ میری نجات بھی ہوگا: کیونکہ منافق اس کے سامنے نہیں آئے گا۔\n17۔ میری تقریر اور میرے بیان کو اپنے کانوں سے غور سے سنو۔\n18۔ دیکھو اب، میں نے {اپنی} مقصد کا حکم دیا ہے؛ مجھے معلوم ہے کہ مجھے حق بجانب کیا جائے گا۔\n19. وہ کون ہے جو مجھ سے درخواست کرے گا؟ ابھی کے لیے، اگر میں خاموش رہوں تو بھوت کو چھوڑ دوں گا۔\n20. صرف دو باتیں مجھ سے نہ کرو، تب میں تم سے خود کو نہیں چھپاؤں گا۔\n21. اپنا ہاتھ مجھ سے دور ہٹا لو: اور اپنی دہشت مجھے خوفزدہ نہ کرے۔\n22. پھر پکارو، اور میں جواب دوں گا: یا مجھے بولنے دو، اور تو جواب دو۔\n23. میرے گناہوں اور گناہوں میں کتنے {ہیں}؟ مجھے میری غلطی اور میرے گناہ کا احساس دلائیں۔\n24۔ تم اپنا چہرہ کیوں چھپاتے ہو، اور مجھے اپنا دشمن سمجھتے ہو؟\n25. کیا تم ایک پتہ توڑو گے جو ادھر ادھر چلا جائے؟ اور کیا تم خشک داڑھی کا پیچھا کرو گے؟\n26۔ کیونکہ تم میرے خلاف تلخ باتیں لکھتے ہو، اور مجھے میری جوانی کی گناہوں کا مالک بناتے ہو۔\n27۔ تو میرے پاؤں بھی موڑوں میں رکھو، اور میرے تمام راستوں کو باریک بینی سے دیکھو؛ تم نے میرے قدموں کے ایڑیوں پر ایک نشان لگایا۔ {نظر آنے والے...: عبرانی۔ observest} {ہیلز: عبرانی۔ جڑیں}\n28۔ اور وہ، ایک سڑی ہوئی چیز کی طرح، ایک ایسے لباس کی طرح کھاتا ہے جو پتنگا کھایا جاتا ہے۔","1۔ مرد {یعنی} عورت سے پیدا ہونے والا {چند دنوں کا} اور پریشانیوں سے بھرا ہوا ہے۔ {چند...: عبرانی کم دنوں میں}\n2۔ وہ پھول کی طرح نکلتا ہے، اور کاٹ دیا جاتا ہے: وہ بھی سایے کی طرح بھاگتا ہے، اور آگے نہیں بڑھتا۔\n3۔ اور کیا تم اپنی آنکھیں ایسے شخص پر کھولتے ہو، اور مجھے اپنے ساتھ عدالت میں لے آتے ہو؟\n4. کون ناپاک سے صاف {چیز} نکال سکتا ہے؟ ایک بھی نہیں۔ {can...: عبرانی دے دوں گا}\n5۔ جب اس کے دن طے ہو چکے ہیں، اس کے مہینوں کی تعداد آپ کے ساتھ ہے، تو اس کی حدود مقرر کر دی ہیں جو وہ عبور نہیں کر سکتا؛\n6۔ اس سے دور ہو تاکہ وہ آرام کر سکے، جب تک کہ وہ ایک مزدور کی طرح اپنا دن مکمل نہ کر لے۔ {آرام: عبرانی بند کرو}\n7۔ کیونکہ درخت کی امید ہے کہ اگر اسے کاٹ دیا جائے تو وہ دوبارہ اگ آئے گا، اور اس کی نرم شاخ رکنے کا نام نہیں لے گی۔\n8۔ اگرچہ اس کی جڑ زمین میں پرانا موم ہو، اور اس کا ذخیرہ زمین میں مر جائے؛\n9۔ {پھر بھی} پانی کی خوشبو سے یہ پھل پھول دے گا، اور پودے کی طرح شاخیں نکلے گا۔\n10. لیکن انسان مرتا ہے، اور ضائع ہو جاتا ہے: ہاں، انسان بھوت چھوڑ دیتا ہے، اور وہ کہاں ہے؟ {wasteth...: عبرانی۔ کمزور ہو جاتا ہے، یا کٹ جاتا ہے}\n11۔ {جب پانی سمندر سے بہہ جاتا ہے، اور سیلاب گل سڑ کر خشک ہو جاتا ہے:\n12۔ یوں انسان لیٹتا ہے، اور اٹھتا نہیں: جب تک آسمان نہ رہے، وہ جاگ نہیں پائیں گے، نہ نیند سے اٹھیں گے۔\n13. کاش تم مجھے قبر میں چھپا دیتے، کہ تم مجھے راز میں رکھتے، جب تک تمہارا غصہ ختم نہ ہو جائے، کہ تم مجھے ایک مقررہ وقت مقرر کرتے، اور مجھے یاد رکھتے!\n14. اگر کوئی انسان مر جائے تو کیا وہ دوبارہ زندہ رہے گا؟ اپنے مقررہ وقت کے سارے دن میں انتظار کروں گا، جب تک میری تبدیلی نہ آ جائے۔\n15۔ تم پکارو گے، اور میں تمہیں جواب دوں گا: تمہیں اپنے ہاتھوں کے کام کی خواہش ہوگی۔\n16۔ کیونکہ اب تم میرے قدم گنتی کرتے ہو: کیا تم میرے گناہ کی حفاظت نہیں کرتے؟\n17. میری گناہ تھیلے میں بند ہے، اور تم میری گناہ کو چھپا دیتے ہو۔\n18۔ اور یقینا گرنے والا پہاڑ ختم ہو جاتا ہے، اور پتھر اپنی جگہ سے ہٹا دیا جاتا ہے۔ {آتا ہے...: عبرانی۔ fadeth}\n19۔ پانی پتھروں کو گھس دیتا ہے: تو زمین کی مٹی سے جو چیزیں ابھرتی ہیں دھو دیتی ہو؛ اور تم انسان کی امید کو تباہ کر دیتے ہو۔ {washest...: عبرانی overflowest}\n20۔ تم ہمیشہ کے لیے اس پر غالب آتے ہو، اور وہ گزر جاتا ہے: تم اس کا چہرہ بدل دیتے ہو، اور اسے بھیج دیتے ہو۔\n21۔ اس کے بیٹے عزت کے لیے آتے ہیں، اور وہ نہیں جانتا؛ اور وہ نیچا دکھائے جاتے ہیں، لیکن وہ ان کا ادراک نہیں کرتا۔\n22۔ لیکن اس کے جسم پر درد ہوگا، اور اس کی روح اس کے اندر ماتم کرے گی۔","1۔ پھر الیفاز تیمانی نے جواب دیا اور کہا،\n2. کیا ایک دانا فضول علم بولے اور مشرقی ہوا سے پیٹ بھر دے؟ {vanin...: عبرانی ہوا کا علم}\n3. کیا اسے غیر فائدہ مند باتوں سے دلیل دینی چاہیے؟ یا ایسی تقریروں کے ساتھ جن سے وہ کوئی فائدہ نہیں دے سکتا؟\n4۔ ہاں، تو خوف کو دور کرتا ہے اور خدا کے سامنے دعا کو روک دیتا ہے۔ {کاسٹسٹ...: عببرانی۔ کسٹ وید} {دعا: یا، تقریر}\n5۔ کیونکہ تمہارا منہ تمہاری گناہی بیان کرتا ہے، اور تم چالباز کی زبان چنتے ہو۔ {بولنا: عبرانی۔ ٹیچتھ}\n6۔ تمہارا اپنا منہ تمہیں سزا دیتا ہے، اور میں نہیں: ہاں، تمہارے اپنے ہونٹ تمہارے خلاف گواہی دیتے ہیں۔\n7. کیا تم پہلا انسان ہو جو پیدا ہوا؟ یا کیا تم پہاڑوں سے پہلے بنائے گئے ہو؟\n8۔ کیا تم نے خدا کا راز سنا ہے؟ اور کیا تم حکمت کو اپنے آپ سے روکتے ہو؟\n9۔ تم کیا جانتے ہو جو ہم نہیں جانتے؟ {کیا} سمجھتے ہو، جو {ہے} ہمارے اندر نہیں؟\n10۔ ہمارے ساتھ وہ سفید بالوں والے اور بہت بوڑھے مرد ہیں، جو تمہارے والد سے کہیں بڑے ہیں۔\n11. کیا خدا کی تسلیاں تمہارے لیے چھوٹی ہیں؟ کیا تمہارے ساتھ کوئی خفیہ بات ہے؟\n12. تمہارا دل تمہیں کیوں لے جاتا ہے؟ اور تمہاری آنکھیں کس چیز پر آنکھ مارتی ہیں،\n13۔ کہ تم اپنی روح کو خدا کے خلاف موڑو، اور ایسے الفاظ اپنے منہ سے نکلنے دو؟\n14. انسان کیا ہے کہ وہ صاف ہو؟ اور {جو} عورت سے پیدا ہوا ہے، کہ وہ نیک ہو؟\n15۔ دیکھو، وہ اپنے مقدسین پر بھروسہ نہیں کرتا؛ ہاں، آسمان اس کی نظر میں صاف نہیں ہے۔\n16. انسان کتنا زیادہ گھٹیا اور گندا ہے، جو گناہ کو پانی کی طرح پیتا ہے؟\n17۔ میں تمہیں دکھاؤں گا، میری سنو؛ اور جو {جو} میں نے دیکھا ہے، میں اعلان کروں گا؛\n18۔ جو عقلمندوں نے اپنے باپ دادا سے بتایا ہے اور چھپایا نہیں:\n19۔ جس کے لیے زمین دی گئی، اور کوئی اجنبی ان کے درمیان نہیں گزرا۔\n20۔ بدکار آدمی اپنے تمام دنوں درد میں مبتلا رہتا ہے، اور سالوں کی تعداد ظالم سے چھپی رہتی ہے۔\n21۔ اس کے کانوں میں ایک خوفناک آواز ہے: خوشحالی میں تباہ کرنے والا اس پر آئے گا۔ {ایک خوفناک...: عبرانی۔ خوف کی آواز}\n22۔ وہ یہ نہیں مانتا کہ وہ اندھیرے سے واپس آئے گا، اور اس کا تلوار کا انتظار کیا جاتا ہے۔\n23۔ وہ روٹی کے لیے باہر نکلتا ہے، {کہتا ہے}، کہاں ہے {یہ}؟ وہ جانتا ہے کہ اندھیرے کا دن اس کے ہاتھ میں تیار ہے۔\n24۔ مصیبت اور اذیت اسے خوفزدہ کر دیں گی؛ وہ اس پر غالب آئیں گے، ایک بادشاہ کی طرح جو جنگ کے لیے تیار ہے۔\n25۔ کیونکہ وہ خدا کے خلاف اپنا ہاتھ بڑھاتا ہے، اور قادر مطلق کے خلاف خود کو مضبوط کرتا ہے۔\n26۔ وہ اس پر دوڑتا ہے، {حتیٰ کہ} اس کی گردن پر، اپنے بکلرز کے موٹے حصوں پر:\n27۔ کیونکہ وہ اپنے چہرے کو اپنی موٹی پن سے ڈھانپ لیتا ہے، اور اپنے پہلوؤں پر چربی کے ٹکڑے بناتا ہے۔\n28۔ اور وہ ویران شہروں میں رہتا ہے، {اور} ایسے گھروں میں جہاں کوئی انسان نہیں رہتا، جو ڈھیر بننے کے لیے تیار ہیں۔\n29۔ وہ امیر نہیں ہوگا، نہ اس کی دولت قائم رہے گی، نہ ہی وہ زمین پر اس کی تکمیل کو طول دے گا۔\n30۔ وہ اندھیرے سے باہر نہیں جائے گا؛ شعلہ اس کی شاخوں کو خشک کر دے گا، اور اس کے منہ کی سانس سے وہ چلا جائے گا۔\n31۔ جو دھوکہ کھا گیا ہے وہ باطل پر بھروسہ نہ کرے: کیونکہ باطل اس کا بدلہ ہوگا۔\n32۔ یہ اس کے وقت سے پہلے مکمل ہو جائے گا، اور اس کی شاخ سبز نہیں ہوگی۔ {کامیاب: یا، کٹ آف}\n33۔ وہ اپنے کچا انگور کو بیل کی طرح جھاڑے گا، اور اپنا پھول زیتون کی طرح پھینکے گا۔\n34. کیونکہ منافقوں کی جماعت ویران ہو جائے گی، اور آگ رشوت کے خیموں کو جلا دے گی۔\n35۔ وہ شرارت کرتے ہیں، بکواس پیدا کرتے ہیں، اور ان کا پیٹ دھوکہ دہی کو تیار کرتا ہے۔ {غرور: یا، بدکاری}","1۔ پھر ایوب نے جواب دیا اور کہا،\n2. میں نے ایسی بہت سی باتیں سنی ہیں: بدقسمت تسلی دینے والے سب لوگ۔ {اداس: یا، پریشان}\n3. کیا فضول باتوں کا انجام ہوگا؟ یا کیا چیز تمہیں حوصلہ دیتی ہے کہ تم جواب دیتے ہو؟ {vanin...: عبرانی ہوا کے الفاظ\n4. میں بھی آپ کی طرح بول سکتا ہوں: اگر آپ کی روح میری جگہ ہوتی، تو میں آپ کے خلاف الفاظ جمع کر سکتا تھا، اور آپ پر سر ہلا سکتا تھا۔\n5. {لیکن} میں تمہیں اپنے منہ سے مضبوط کرنا چاہوں گا، اور میرے ہونٹوں کی حرکت تمہارے غم کو بڑھا دے گی۔\n6۔ اگرچہ میں بولتا ہوں، میرا غم بے وفا نہیں: اور {اگر} میں برداشت کرتا ہوں، مجھے کیا سکون ملتا ہے؟ {کیا...: عبرانی۔ مجھ سے کیا نکلتا ہے؟}\n7۔ لیکن اب اس نے مجھے تھکا دیا ہے: تم نے میری تمام صحبت کو ویران کر دیا ہے۔\n8۔ اور تو نے مجھے جھریوں سے بھر دیا ہے، {جو} میرے خلاف گواہ ہے: اور میری کمزوری جو میرے اندر اٹھتی ہے میرے چہرے کی گواہی دیتی ہے۔\n9۔ وہ اپنے غصے میں مجھے پھاڑتا ہے، جو مجھ سے نفرت کرتا ہے: وہ اپنے دانتوں سے مجھے چباتا ہے؛ میرا دشمن اپنی نظریں مجھ پر تیز کرتا ہے۔\n10۔ انہوں نے اپنے منہ سے مجھ پر حیرت سے دیکھا؛ انہوں نے میرے گال پر ملامت آمیز انداز میں مارا ہے؛ انہوں نے خود کو میرے خلاف جمع کر لیا ہے۔\n11۔ خدا نے مجھے بدکاروں کے حوالے کیا ہے، اور مجھے بدکاروں کے ہاتھوں میں دے دیا ہے۔ {hath...: عبرانی۔ مجھے خاموش کر دیا ہے}\n12۔ میں پرسکون تھا، لیکن اس نے مجھے چیر پھاڑ دیا: اس نے مجھے بھی میری گردن سے پکڑ لیا، ٹکڑے ٹکڑے کر دیا، اور اپنے شکار کے لیے تیار کر دیا۔\n13۔ اس کے تیر انداز مجھے گھیر لیتے ہیں، وہ میری لگام کو چیر دیتا ہے، اور کبھی نہیں چھوڑتا؛ وہ میرا گال زمین پر انڈیل دیتا ہے۔\n14۔ وہ مجھے بار بار توڑتا ہے، وہ میرے اوپر دیو کی طرح دوڑتا ہے۔\n15۔ میں نے اپنی جلد پر بوری کا کپڑا سی دیا ہے، اور اپنے سینگ کو مٹی میں آلودہ کیا ہے۔\n16۔ میرا چہرہ رونے سے آلودہ ہے، اور میری پلکوں پر موت کا سایہ ہے؛\n17. میرے ہاتھوں میں {کسی ناانصافی} کے لیے نہیں: اور میری دعا {پاک} ہے۔\n18. اے زمین، میرا خون نہ چھپاؤ، اور میری فریاد کو بے جگہ نہ رکھو۔\n19۔ اور اب، دیکھو، میرا گواہ {ہے} آسمان میں، اور میرا ریکارڈ {بلند} ہے۔ {اونچی آواز میں: عبوری۔ اونچی جگہوں میں}\n20۔ میرے دوست مجھے حقارت کرتے ہیں: {لیکن} میری آنکھ خدا کی طرف آنسو بہاتی ہے۔ {مذاق اڑاؤ: عبرانی۔ میرے مذاق کرنے والے ہیں}\n21. اے کاش کوئی خدا کے ساتھ کسی آدمی کے لیے دعا کر سکے، جیسے وہ اپنے پڑوسی کے لیے {التجاد} کرے! {پڑوسی: یا، دوست}\n22۔ جب چند سال آئیں گے، تب میں اس راستے پر جاؤں گا {جہاں سے} میں واپس نہیں آؤں گا۔ {کچھ...: عبرانی۔ تعداد کے سال}","1. میری سانس خراب ہو گئی ہے، میرے دن ختم ہو چکے ہیں، قبریں میرے لیے تیار ہیں۔ {سانس...: یا، روح ختم ہو چکی ہے}\n2. {کیا} میرے ساتھ مذاق اڑانے والے نہیں ہیں؟ اور کیا میری آنکھ ان کی اشتعال انگیزی میں جاری نہیں رہتی؟ {جاری رکھیں: عبرانی۔ لاج}\n3۔ اب لیٹ جاؤ، مجھے اپنے ساتھ ضمانت میں رکھو؛ وہ کون ہے جو مجھ سے ہاتھ مارے گا؟\n4۔ کیونکہ تم نے ان کے دل کو سمجھ سے چھپایا ہے: اس لیے تم ان کی تعریف نہ کرو۔\n5۔ جو اپنے دوستوں کی خوشامد کرتا ہے، اس کے بچوں کی آنکھیں بھی ختم ہو جائیں گی۔\n6۔ اس نے مجھے بھی لوگوں کا نعرہ بنا دیا ہے؛ اور اس سے پہلے میں ٹیبریٹ تھا۔ {پہلے وقت: یا، ان سے پہلے}\n7۔ میری آنکھ بھی غم کی وجہ سے مدھم ہے، اور میرے تمام ارکان سایہ کی طرح ہیں۔ {میرے اراکین: یا، میرے خیالات}\n8۔ سیدھے لوگ اس پر حیران ہوں گے، اور معصوم منافق کے خلاف خود کو اٹھائیں گے۔\n9۔ نیک بھی اپنے راستے پر قائم رہیں گے، اور جس کے ہاتھ صاف ہوں گے وہ مضبوط اور مضبوط ہوگا۔ {be...: عبرانی۔ طاقت بڑھاؤ}\n10۔ لیکن تم سب واپس آؤ اور ابھی آؤ: کیونکہ میں تم میں سے کوئی بھی دانا نہیں پا سکتا۔\n11. میرے دن گزر چکے ہیں، میرے مقاصد ٹوٹ چکے ہیں، {حتیٰ کہ} میرے دل کے خیالات بھی۔ {خیالات: عبرانی۔ ملکیتیں}\n12. وہ رات کو دن میں بدل دیتے ہیں: روشنی اندھیرے کی وجہ سے مختصر ہو جاتی ہے۔ {مختصر: عبرانی۔ قریب}\n13. اگر میں انتظار کروں تو قبر {ہے} میرا گھر: میں نے اندھیرے میں اپنا بستر بنا لیا ہے۔\n14. میں نے کرپشن سے کہا ہے، تو میرے باپ ہو: کیڑے سے، تو میری ماں اور بہن ہو۔ {کہا: عبری۔ پکارا، یا، پکارا}\n15۔ اور اب میری امید کہاں ہے؟ جہاں تک میری امید کا تعلق ہے، کون اسے دیکھے گا؟\n16۔ وہ گڑھے کی سلاخوں تک جائیں گے، جب {ہماری} ایک ساتھ {مٹی میں} آرام کریں گے۔","1۔ پھر بلداد الشحیت نے جواب دیا اور کہا،\n2. کتنے عرصے میں تم الفاظ ختم کرو گے؟ مارک، اور بعد میں ہم بات کریں گے۔\n3. ہمیں آپ کی نظر میں درندے کیوں شمار کیا جاتا ہے، {اور} آپ کی نظر میں گھٹیا کیوں سمجھے جاتے ہیں؟\n4۔ وہ اپنے غصے میں خود کو پھاڑتا ہے: کیا زمین تمہارے لیے چھوڑ دی جائے گی؟ اور کیا پتھر کو اس کی جگہ سے ہٹا دیا جائے گا؟ {خود: عبرانی۔ اس کی روح}\n5. ہاں، بدکار کی روشنی بجھ جائے گی، اور اس کی آگ کی چنگاری نہیں چمکے گی۔\n6۔ اس کے خیمے میں روشنی تاریک ہو جائے گی، اور اس کی موم بتی اس کے ساتھ بجھ جائے گی۔ {موم بتی: یا، چراغ}\n7۔ اس کی طاقت کے قدم تیز کیے جائیں گے، اور اس کی اپنی نصیحت اسے گرا دے گی۔\n8۔ کیونکہ وہ اپنے ہی قدموں سے جال میں پھینک دیا جاتا ہے، اور وہ جال پر چلتا ہے۔\n9۔ جن {اسے} کو ایڑی سے پکڑے گا، {اور} ڈاکو اس پر غالب آئے گا۔\n10۔ جال {ہے} اس کے لیے زمین میں بچھایا گیا ہے، اور اس کے راستے میں جال ہے۔ {لیڈ: عببرانی۔ چھپا ہوا}\n11۔ خوف اسے ہر طرف سے خوفزدہ کر دیں گے، اور اسے کھڑا کر دیں گے۔ {ڈرائیو: عبوری۔ بکھراؤ}\n12۔ اس کی طاقت بھوک سے کاٹ لی جائے گی، اور تباہی اس کے ساتھ تیار ہوگی۔\n13. یہ اس کی جلد کی طاقت کو نگل جائے گا: {حتیٰ کہ} موت کا پہلا بچہ بھی اس کی طاقت نگل جائے گا۔ {طاقت: عبرانی۔ بارز}\n14۔ اس کا اعتماد اس کے خیمے سے نکال دیا جائے گا، اور وہ اسے دہشت کے بادشاہ کے پاس لے جائے گا۔\n15۔ یہ اس کے خیمے میں رہے گا، کیونکہ {یہ اس کا کوئی نہیں}: اس کی رہائش گاہ پر گندھک بکھر جائے گا۔\n16۔ اس کی جڑیں نیچے خشک ہو جائیں گی، اور اوپر اس کی شاخ کاٹ دی جائے گی۔\n17. اس کی یاد زمین سے مٹ جائے گی، اور اس کا نام سڑک پر نہیں ہوگا۔\n18. اسے روشنی سے تاریکی میں نکالا جائے گا، اور دنیا سے نکالا جائے گا۔ {وہ...: عبرانی۔ وہ اسے بھگا دیں گے}\n19۔ اس کے لوگوں میں نہ بیٹا ہوگا اور نہ بھتیجا، اور نہ ہی اس کے گھر میں کوئی باقی ہوگا۔\n20۔ جو لوگ {اس کے بعد} آئیں گے، وہ اس کے دن پر حیران ہوں گے، جیسے اس سے پہلے جانے والے خوفزدہ تھے۔ {گیا...: یا، اس کے ساتھ رہا} {تھے...: عبرانی ہارر پر قبضہ کر لیا}\n21. یقینا یہ بدکاروں کے گھر ہیں، اور یہ وہ جگہ ہے {جو خدا کو نہیں جانتا}۔","1۔ پھر ایوب نے جواب دیا اور کہا،\n2. کب تک تم میری روح کو تنگ کرو گے، اور مجھے الفاظ سے ٹکڑے ٹکڑے کرو گے؟\n3۔ تم نے مجھے دس بار ملامت کی ہے: تم شرمندہ نہیں ہو کہ تم خود کو میرے لیے اجنبی بنا رہے ہو۔ {بناؤ...: یا، میرے خلاف سخت ہو جاؤ}\n4۔ اور چاہے میں غلطی کر چکا ہوں، میری غلطی میرے ساتھ ہی باقی ہے۔\n5۔ اگر واقعی تم میرے خلاف خود کو بڑھا چڑھاؤ گے، اور میرے خلاف ملامت کا دعویٰ کرو گے:\n6۔ اب جان لو کہ خدا نے مجھے گرا دیا ہے، اور اپنے جال سے مجھے گھیر لیا ہے۔\n7۔ دیکھو، میں غلط سے پکار رہا ہوں، لیکن میری آواز نہیں سنائی دیتی: میں بلند آواز میں پکار رہا ہوں، لیکن {کوئی فیصلہ نہیں}۔ {غلط: یا، تشدد}\n8۔ اس نے میرے راستے کو باڑ لگا دیا ہے جس سے میں گزر نہیں سکتا، اور اس نے میرے راستوں میں تاریکی ڈال دی ہے۔\n9۔ اس نے میری شان چھین لی، اور تاج میرے سر سے لے لیا۔\n10۔ اس نے مجھے ہر طرف سے تباہ کر دیا ہے، اور میں چلا گیا ہوں: اور میری امید اس نے درخت کی طرح ختم کر دی ہے۔\n11۔ اس نے بھی میرے خلاف اپنا غصہ بھڑکا دیا ہے، اور وہ مجھے اپنے دشمنوں میں شمار کرتا ہے۔\n12۔ اس کی فوج اکٹھی ہو کر میرے خلاف اٹھ کھڑی ہوئی، اور میرے خیمے کے ارد گرد خیمہ زن ہو گئی۔\n13۔ اس نے میرے بھائیوں کو مجھ سے دور کر دیا ہے، اور میرے جاننے والے واقعی مجھ سے دور ہیں۔\n14. میرے رشتہ دار ناکام ہو گئے ہیں، اور میرے مانوس دوست مجھے بھول گئے ہیں۔\n15۔ جو لوگ میرے گھر میں رہتے ہیں اور میری خادمہ ہیں، وہ مجھے اجنبی سمجھتے ہیں: میں ان کی نظر میں اجنبی ہوں۔\n16۔ میں نے اپنے خادم کو بلایا، اور اس نے مجھے کوئی جواب نہیں دیا؛ میں نے اپنے منہ سے اس سے درخواست کی۔\n17۔ میری سانس میری بیوی کے لیے عجیب ہے، حالانکہ میں نے بچوں کے لیے اپنے جسم کی بھلائی کی تھی۔ {میرا...: عبرانی۔ میرا پیٹ}\n18۔ ہاں، چھوٹے بچے مجھے حقیر سمجھتے تھے؛ میں اٹھا، اور وہ میرے خلاف بولے۔ {نوجوان...: یا، بدکار}\n19۔ میرے تمام اندرونی دوست مجھ سے نفرت کرتے تھے: اور جن سے میں محبت کرتا تھا وہ میرے خلاف ہو گئے۔ {میرا...: عبوری۔ میرے راز کے مرد}\n20. میری ہڈی میری جلد اور گوشت سے چپک جاتی ہے، اور میں اپنے دانتوں کی کھال سے بچ نکلتا ہوں۔ {اور to: or, as to}\n21. مجھ پر رحم کرو، مجھ پر رحم کرو، اے میرے دوستو؛ کیونکہ خدا کا ہاتھ مجھے چھو گیا ہے۔\n22. تم مجھے خدا کی طرح کیوں ستاتے ہو، اور میرے جسم سے مطمئن کیوں نہیں ہو؟\n23۔ کاش میرے الفاظ اب لکھے جاتے! کاش وہ کتاب میں چھپے ہوتے! {اوہ...: عبرانی۔ کون دے گا، وغیرہ}\n24۔ کہ انہیں ہمیشہ کے لیے لوہے کے قلم اور پتھر میں سیسہ سے کندہ کیا گیا!\n25۔ کیونکہ میں جانتا ہوں {کہ} میرا نجات دہندہ زندہ ہے، اور {کہ} وہ آخری {دن} زمین پر کھڑا ہوگا:\n26. اور {اگرچہ} جب میری کھال {کیڑے} اس {جسم} کو تباہ کر دیں، تب بھی میں اپنے جسم میں خدا کو دیکھوں گا: {اور...: یا، جب میں جاگ جاؤں گا، چاہے یہ جسم تباہ ہو جائے، پھر بھی میرے جسم سے باہر ہے}\n27۔ جسے میں خود دیکھوں گا، اور میری آنکھیں دیکھیں گی، اور کسی اور کو نہیں؛ {اگرچہ} میری لگام میرے اندر ہی اندر ہو جاتی ہے۔ {ایک اور: عبرانی۔ ایک اجنبی} {اگرچہ...: یا، میرے اندر کی لگام اس دن کے لیے سچی خواہش میں گھل گئی ہے} {اندر...: عبرانی میرے سینے میں}\n28۔ لیکن تمہیں کہنا چاہیے، ہم اسے کیوں ستاتے ہیں، جب کہ مسئلے کی جڑ مجھ میں ہے؟ {دیکھنا...: یا، اور میرے اندر مادے کی کون سی جڑ ملتی ہے؟}\n29۔ تلوار سے ڈرو: کیونکہ غضب تلوار کی سزا لاتی ہے، تاکہ تم جان سکو کہ کوئی فیصلہ ہے۔","1۔ پھر زوفار نامتی نے جواب دیا اور کہا،\n2. لہٰذا میرے خیالات مجھے جواب دینے پر مجبور کرتے ہیں، اور {یہ} کے لیے میں جلدی کرتا ہوں۔ {میں بناتا ہوں...: عبرانی۔ میری جلدی میرے اندر ہے}\n3۔ میں نے اپنی ملامت کی جانچ سنی ہے، اور میری سمجھ کی روح مجھے جواب دینے پر مجبور کرتی ہے۔\n4۔ کیا تم یہ سب قدیم نہیں جانتے، جب سے انسان زمین پر رکھا گیا تھا،\n5. کہ بدکاروں کی فتح مختصر ہے، اور منافق کی خوشی {لیکن} لمحے کے لیے؟ {مختصر: عبرانی۔ قریب سے}\n6۔ اگرچہ ان کی عظمت آسمان کی طرف چڑھ جائیں، اور ان کا سر بادلوں تک پہنچے؛ {بادل: عبوری۔ بادل}\n7۔ {پھر بھی} وہ ہمیشہ کے لیے اپنی گوبر کی طرح مر جائے گا: جو اسے دیکھ چکے ہیں وہ کہیں گے، وہ کہاں ہے؟\n8۔ وہ خواب کی طرح اڑ جائے گا، اور نہیں ملے گا: ہاں، اسے رات کے خواب کی طرح بھگا دیا جائے گا۔\n9۔ وہ آنکھ بھی {جس نے اسے دیکھا} وہ اب {اسے نہیں دیکھے گی}؛ نہ ہی اس کی جگہ اب اسے دیکھے گی۔\n10۔ اس کے بچے غریبوں کو خوش کرنے کی کوشش کریں گے، اور اس کے ہاتھ ان کے مال واپس کریں گے۔ {اس کے بچے...: یا، غریب اپنے بچوں پر ظلم کرے گا}\n11۔ اس کی ہڈیاں اس کی جوانی کے گناہ سے بھری ہوئی ہیں، جو اس کے ساتھ مٹی میں پڑے گی۔\n12۔ اگرچہ برائی اس کے منہ میں میٹھی ہو، {اگرچہ} وہ اسے اپنی زبان کے نیچے چھپا دیتا ہے؛\n13۔ {اگرچہ} وہ اسے چھوڑتا ہے، اور اسے ترک نہیں کرتا؛ لیکن اسے اپنے منہ میں ہی رکھیں: {اندر...: عبرانی۔ اپنے ذائقے کے بیچ میں}\n14۔ {پھر بھی} اس کے آنتوں میں گوشت پلٹ چکا ہے، {یہ} اس کے اندر موجود ایسپس کی جرات ہے۔\n15۔ اس نے دولت نگل لی ہے، اور وہ اسے دوبارہ قے کرے گا: خدا انہیں اپنے پیٹ سے نکال دے گا۔\n16۔ وہ سانپ کا زہر چوسے گا: سانپ کی زبان اسے مار ڈالے گی۔\n17۔ وہ دریا، سیلاب، شہد اور مکھن کی ندیوں کو نہیں دیکھے گا۔ {دی فلڈز...: یا، بہتے ہوئے ندی نالے}\n18۔ جس چیز کے لیے اس نے محنت کی وہ بحال کرے گا، اور نگل نہیں جائے گا: اس کی ذات کے مطابق تلافی ہو گی، اور وہ اس پر خوش نہیں ہوگا۔ {اس کا...: عبرانی اس کے تبادلے کا مواد}\n19۔ کیونکہ اس نے غریبوں کو ظلم کیا ہے اور چھوڑ دیا ہے؛ {کیونکہ} اس نے زبردستی ایک گھر لے لیا ہے جو اس نے تعمیر نہیں کیا؛ {دبائے ہوئے: عبرانی۔ کچل دیا گیا}\n20. یقینا وہ اپنے پیٹ میں سکون محسوس نہیں کرے گا، وہ اپنی خواہش سے نجات نہیں پا سکے گا۔ {محسوس کرنا: عببرانی۔ جانیں}\n21۔ اس کا گوشت باقی نہیں رہے گا؛ لہٰذا کوئی شخص اپنی چیزوں کی تلاش نہیں کرے گا۔ {کوئی نہیں...: یا، اس کے گوشت کے لیے کوئی باقی نہ رہے}\n22۔ اپنی کفالت کی تکمیل میں وہ مشکلات میں ہوگا: بدکاروں کا ہر ہاتھ اس پر آ جائے گا۔ {شرارتی: یا، پریشان}\n23۔ {جب} وہ اپنا پیٹ بھرنے والا ہو، {خدا} اس پر اپنے غضب کا طوفان ڈالے گا، اور جب وہ کھا رہا ہوگا اس پر بارش کرے گا۔\n24۔ وہ لوہے کے ہتھیار سے بھاگے گا، {اور} فولاد کا کمان اسے مارے گا۔\n25۔ یہ نکالا جاتا ہے، اور جسم سے باہر آتا ہے؛ ہاں، چمکتی ہوئی تلوار اس کی بے باکی سے نکلتی ہے: اس پر خوف چھا گیا ہے۔\n26. تمام تاریکی {اس کے خفیہ مقامات میں} چھپی ہوگی: ایک نہ جلنے والی آگ اسے جلا دے گی؛ جو اس کے خیمے میں بچا ہے اس کے ساتھ برا ہو جائے گا۔\n27۔ آسمان اس کی بدکاری ظاہر کرے گا؛ اور زمین اس کے خلاف اٹھے گی۔\n28۔ اس کے گھر کی بڑھوتری ختم ہو جائے گی، {اور اس کی مال} اس کے غصے کے دن بہہ جائے گی۔\n29۔ یہ خدا کی طرف سے ایک بدکار شخص کا حصہ ہے، اور خدا کی طرف سے اسے دی گئی میراث ہے۔ {مقرر...: عبرانی۔ اس کے خدا کے حکم کا}","1۔ لیکن ایوب نے جواب دیا اور کہا،\n2. میری تقریر غور سے سنو، اور یہ تمہاری تسلی ہو۔\n3. مجھے اجازت دو تاکہ میں بول سکوں؛ اور اس کے بعد میں نے مذاق میں بات کی۔\n4. جہاں تک میرا تعلق ہے، کیا یہ میری شکایت ہے؟ اور اگر ایسا ہے، تو میری روح کیوں پریشان نہ ہو؟ {پریشان: عبوری۔ مختصر کر دیا گیا؟}\n5۔ مجھے دیکھو، اور حیران ہو جاؤ، اور اپنا ہاتھ اپنے منہ پر رکھو۔ {مارک...: عبرانی۔ میری طرف دیکھو}\n6. جب مجھے یاد آتا ہے تو میں ڈرتا ہوں، اور کانپنا میرے جسم کو جکڑ لیتا ہے۔\n7. بدکار کیوں زندہ رہتے ہیں، بوڑھے کیوں ہوتے ہیں، ہاں، طاقتور ہوتے ہیں؟\n8۔ ان کی نسل ان کی نظر میں ان کے ساتھ قائم ہوتی ہے، اور ان کی اولاد ان کی آنکھوں کے سامنے ہوتی ہے۔\n9۔ ان کے گھر خوف سے محفوظ ہیں، نہ ہی خدا کی چھڑی ان پر ہے۔ {محفوظ...: عبرانی۔ پیس فرام}\n10۔ ان کا بیل جنس دار ہے، اور ناکام نہیں ہوتا؛ ان کی گائے بچھڑی ہوئی ہے، اور اپنا بچھڑا نہیں چھوڑتی۔\n11۔ وہ اپنے چھوٹے بچوں کو ریوڑ کی طرح بھیجتے ہیں، اور ان کے بچے رقص کرتے ہیں۔\n12۔ وہ ٹمبرل اور ہارپ لیتے ہیں، اور آرگن کی آواز پر خوش ہوتے ہیں۔\n13۔ وہ اپنے دن دولت میں گزارتے ہیں، اور ایک لمحے میں قبر میں چلے جاتے ہیں۔ {دولت میں: یا، خوشی میں}\n14۔ اسی لیے وہ خدا سے کہتے ہیں، ہم سے دور ہو جا؛ کیونکہ ہم تیرے راستوں کا علم نہیں چاہتے۔\n15. قادر مطلق کیا ہے کہ ہم اس کی خدمت کریں؟ اور اگر ہم اس سے دعا کریں تو ہمیں کیا فائدہ ہوگا؟\n16۔ دیکھو، ان کی بھلائی ان کے ہاتھ میں نہیں: بدکاروں کی نصیحت میرے لیے بہت دور ہے۔\n17. بدکاروں کی موم بتی کتنی بار بجھائی جاتی ہے! اور {کتنی بار} ان پر ان کی تباہی آتی ہے! {خدا} اپنے غصے میں غم تقسیم کرتا ہے۔ {موم بتی: یا، چراغ}\n18۔ وہ ہوا کے سامنے داڑھی کی طرح ہیں، اور ایسے بھوسے کی طرح ہیں جنہیں طوفان لے جاتا ہے۔ {کیریئتھ: عبرانی۔ چوری کرنا}\n19۔ خدا اپنے بچوں کے لیے اپنی بدکاری کرتا ہے: وہ اسے اجر دیتا ہے، اور وہ اسے جان لے گا۔ {اس کی بدکاری: یعنی، اس کی بدکاری کی سزا}\n20۔ اس کی آنکھیں اس کی تباہی دیکھیں گی، اور وہ قادر مطلق کے غضب سے پیے گا۔\n21۔ کس خوشی کے لیے وہ اپنے گھر میں ہے، جب اس کے مہینوں کی تعداد درمیان میں کٹ گئی ہو؟\n22. کیا {کوئی} خدا کو علم سکھائے؟ دیکھتے ہوئے کہ وہ بلند لوگوں کا فیصلہ کرتا ہے۔\n23۔ انسان اپنی پوری طاقت میں مرتا ہے، مکمل طور پر پرسکون اور خاموش رہتا ہے۔ {اس کا...: عبرانی اس کی بہت، یا، اس کی کمالیت کی طاقت}\n24۔ اس کے سینے دودھ سے بھرے ہوئے ہیں، اور اس کی ہڈیاں گودے سے گیلی ہیں۔ {چھاتی: یا، دودھ کے بالٹے}\n25۔ اور دوسرا اپنی روح کی تلخی میں مرتا ہے، اور کبھی خوشی سے نہیں کھاتا۔\n26۔ وہ مٹی میں ایک جیسے لیٹیں گے، اور کیڑے انہیں ڈھانپ لیں گے۔\n27۔ دیکھو، میں تمہارے خیالات جانتا ہوں، اور وہ طریقے جو تم غلط طور پر میرے خلاف تصور کرتے ہو۔\n28۔ کیونکہ تم کہتے ہو، شہزادے کا گھر کہاں ہے؟ اور بدکاروں کے رہائش گاہیں کہاں ہیں؟ {رہائش...: عبرانی۔ خیمہ خیم}\n29۔ کیا تم نے ان لوگوں سے نہیں پوچھا جو گزرتے ہیں؟ اور کیا تم ان کے نشانات نہیں جانتے،\n30۔ کہ بدکار صرف تباہی کے دن تک محدود رہے؟ انہیں غصے کے دن پر لایا جائے گا۔ {غصہ: عبرانی۔ غصہ}\n31. کون اس کے سامنے اپنا راستہ ظاہر کرے گا؟ اور کون اس کا بدلہ دے گا جو اس نے کیا ہے؟\n32۔ پھر بھی اسے قبر میں لایا جائے گا، اور وہ قبر میں رہے گا۔ {قبر: عبرانی graves} {remain...: Hebrew. دیکھو ڈھیر میں}\n33۔ وادی کے ڈھیر اس کے لیے میٹھے ہوں گے، اور ہر آدمی اس کے پیچھے جائے گا، جیسے اس کے سامنے بے شمار ہیں۔\n34. تو پھر تم مجھے کیسے بے سود تسلی دیتے ہو، جب دیکھتے ہو کہ تمہارے جوابات میں جھوٹ باقی ہے؟ {جھوٹ: عبرانی۔ خلاف ورزی؟}","1۔ پھر الیفاز تیمانی نے جواب دیا اور کہا،\n2. کیا انسان خدا کے لیے فائدہ مند ہو سکتا ہے، جیسے دانا خود اپنے لیے فائدہ مند ہو سکتا ہے؟ {جیسا کہ وہ...: یا، اگر وہ منافع بخش ہو سکتا ہے، تو کیا اس کی کامیابی اسی پر منحصر ہے؟}\n3. {کیا یہ خدا تعالیٰ کے لیے کوئی خوشی ہے کہ تم نیک ہو؟ یا {کیا یہ} اس کے لیے فائدہ مند ہے کہ تم اپنے راستے کو کامل بناتے ہو؟\n4. کیا وہ آپ کو آپ سے ڈرنے کی وجہ سے ڈانٹیں گے؟ کیا وہ تمہارے ساتھ عدالت میں داخل ہوگا؟\n5. کیا تیری برائی عظیم نہیں؟ اور تمہاری غلطیاں لامتناہی ہیں؟\n6۔ کیونکہ تم نے اپنے بھائی سے بے سود وعدہ لیا ہے، اور ننگے لوگوں کو ان کے کپڑے اتار دیے۔ {ننگا...: عبرانی۔ ننگے لوگوں کے کپڑے}\n7۔ تم نے تھکے ہوئے لوگوں کو پانی نہیں دیا کہ وہ پیئے، اور نہ ہی بھوکوں سے روٹی روکی۔\n8. لیکن {جہاں تک} عظیم آدمی کا تعلق ہے، اس کے پاس زمین تھی؛ اور معزز آدمی اس میں رہتا تھا۔ {mighty...: عبرانی مین آف آرم} {معزز...: عبرانی۔ ممتاز، یا، چہرے کے لیے قبول کیا گیا}\n9۔ تو نے بیواؤں کو خالی بھیج دیا، اور یتیم کے بازو ٹوٹ گئے۔\n10۔ اس لیے آپ کے ارد گرد جال ہیں، اور اچانک خوف آپ کو پریشان کرتا ہے؛\n11۔ یا اندھیرا، {جو} تم نہیں دیکھ سکتے؛ اور پانی کی فراوانی تمہیں ڈھانپ لیتی ہے۔\n12. {کیا} خدا آسمان کی بلندی پر نہیں ہے؟ اور دیکھو ستاروں کی بلندی، کتنی اونچی ہیں! {ستاروں کی بلندی: عبرانی۔ ہیڈ آف دی اسٹارز}\n13۔ اور تم کہتے ہو، خدا کیسے جانتا ہے؟ کیا وہ سیاہ بادل کے پار فیصلہ کر سکتا ہے؟ {کیسے: یا، کیا}\n14۔ موٹے بادل اس کے لیے ایک پردہ ہیں، جو وہ نہیں دیکھتا؛ اور وہ جنت کے چکر میں چلتا ہے۔\n15۔ کیا تم نے وہ پرانا راستہ نشان زد کیا ہے جس پر برے لوگ چلتے رہے ہیں؟\n16۔ جو وقت سے کاٹ دیے گئے، جن کی بنیاد سیلاب سے بھر گئی: {کس کی...: عبرانی۔ ان کی بنیاد پر سیلاب برسا}\n17۔ جس نے خدا سے کہا، ہم سے دور ہو جاؤ: اور قادر مطلق ان کے لیے کیا کر سکتا ہے؟ {for: or, to}\n18۔ پھر بھی اس نے ان کے گھروں کو اچھی چیزوں سے بھر دیا: لیکن بدکاروں کی نصیحت مجھ سے بہت دور ہے۔\n19۔ نیک لوگ اسے دیکھتے ہیں اور خوش ہوتے ہیں: اور معصوم ان پر ہنس کر طنز کرتے ہیں۔\n20۔ جہاں ہمارا مادہ نہیں کٹا جاتا، بلکہ ان کے باقیات کو آگ جلا دیتی ہے۔ {مادہ: یا، جائیداد} {باقیات...: یا، ان کی عظمت}\n21۔ اب اس سے واقفیت حاصل کرو، اور سکون میں رہو: اس سے تمہارے لیے بھلائی آئے گی۔ {وہ: یعنی، خدا}\n22۔ میں تم سے دعا کرتا ہوں کہ اس کے منہ سے قانون قبول کرو، اور اس کے الفاظ اپنے دل میں محفوظ کرو۔\n23۔ اگر تم قادر مطلق کی طرف لوٹے تو تمہیں تعمیر کیا جائے گا، تم ظلم کو اپنے خیموں سے دور دور کر دو گے۔\n24۔ پھر تم سونا مٹی کی طرح رکھو گے، اور اوفیر کا {سونا} ندیوں کے پتھروں کی طرح۔ {گرد کے طور پر: یا، گرد پر}\n25۔ جی ہاں، قادر مطلق تمہارا دفاع کرے گا، اور تمہارے پاس چاندی کی بہتات ہوگی۔ {دفاع: یا، سونا} {بہت زیادہ...: عبرانی۔ طاقت کا چاندی\n26۔ تب تمہیں قادر مطلق پر خوشی ملے گی، اور اپنا چہرہ خدا کی طرف اٹھا دو۔\n27۔ تم اس سے دعا کرو، وہ تمہاری بات سنے گا، اور تم اپنی قسمیں ادا کرو گے۔\n28۔ تم بھی کوئی حکم دو گے، اور وہ تمہارے لیے قائم ہو جائے گا، اور روشنی تمہارے راستوں پر چمکے گی۔\n29۔ جب {انسان} نیچے پھینکے جائیں، تو تم کہو گے، {اوپر اٹھ رہا ہے}؛ اور وہ عاجز شخص کو بچائے گا۔ {عاجز...: عبرانی۔ جس کی آنکھیں نیچی ہیں}\n30۔ وہ معصوموں کے جزیرے کو آزاد کرے گا: اور یہ تمہارے ہاتھوں کی پاکیزگی سے نجات پاتا ہے۔ {وہ کرے گا...: یا، معصوم جزیرے کو آزاد کرے گا}","1۔ پھر ایوب نے جواب دیا اور کہا،\n2. آج بھی میری شکایت تلخ ہے: میرا فالج میرے کراہنے سے زیادہ بھاری ہے۔ {اسٹروک: عبوری۔ ہاتھ}\n3. کاش مجھے معلوم ہوتا کہ وہ کہاں مل سکتا ہے! {وہ} شاید میں اس کی نشست پر آ جاؤں!\n4. میں اپنے مقصد کو ان کے سامنے حکم دوں گا، اور اپنے منہ کو دلائل سے بھر دوں گا۔\n5. میں جانتا ہوں کہ وہ کون سے الفاظ مجھے جواب دے گا، اور سمجھ سکتا ہوں کہ وہ مجھ سے کیا کہے گا۔\n6. کیا وہ اپنی عظیم طاقت کے ساتھ میرے خلاف درخواست کرے گا؟ نہیں؛ لیکن وہ مجھ میں {طاقت} ڈالے گا۔\n7۔ وہاں نیک لوگ اس سے بحث کر سکتے ہیں؛ تو کیا مجھے ہمیشہ کے لیے اپنے جج سے نجات ملنی چاہیے؟\n8۔ دیکھو، میں آگے بڑھتا ہوں، لیکن وہ {ہے} {وہاں} نہیں؛ اور پیچھے کی طرف، لیکن میں اسے محسوس نہیں کر سکتا:\n9۔ بائیں ہاتھ پر، جہاں وہ کام کر رہا ہے، لیکن میں اسے نہیں دیکھ سکتا: وہ دائیں ہاتھ پر چھپا ہوا ہے، کہ میں اسے نہیں دیکھ سکتا:\n10۔ لیکن وہ جانتا ہے کہ میں کس راستے پر چلتا ہوں: {جب} اس نے مجھے آزمایا، میں سونا بن کر سامنے آؤں گا۔ {وہ...: عببرانی۔ یہ میرے ساتھ ہے}\n11. میرا قدم اس کے قدم تھامے رہا، اس کے راستے پر میں نے چلا، اور انکار نہیں کیا۔\n12. نہ ہی میں اس کے ہونٹوں کے حکم سے پیچھے ہٹا ہوں؛ میں نے اس کے الفاظ کو اپنی ضروری {کھانے} سے زیادہ اہمیت دی ہے۔ {محترم: عبوری۔ چھپا ہوا، یا، لیٹ اپ} {میرا...: یا، میرا مقررہ حصہ}\n13. لیکن وہ {ہے} ایک {ذہن} میں، اور کون اسے بدل سکتا ہے؟ اور {کیا}اس کی روح چاہتی ہے، یہاں تک کہ {یہ} وہ چاہتا ہے۔\n14۔ کیونکہ وہ میرے لیے مقرر کردہ کام انجام دیتا ہے: اور ایسی بہت سی چیزیں اس کے ساتھ ہیں۔\n15۔ اسی لیے میں اس کی موجودگی سے پریشان ہوں: جب میں سوچتا ہوں تو اس سے ڈرتا ہوں۔\n16۔ کیونکہ خدا میرا دل نرم کرتا ہے، اور قادر مطلق مجھے پریشان کرتا ہے:\n17. کیونکہ میں اندھیرے سے پہلے نہیں کاٹا گیا، {اور نہیں} نے میرے چہرے سے تاریکی چھپائی۔","1۔ کیوں دیکھتے وقت خدا تعالیٰ سے پوشیدہ نہیں ہیں، کیا جو اسے جانتے ہیں وہ اس کے دن نہیں دیکھتے؟\n2. {کچھ} نشانیاں ہٹا دیتے ہیں؛ وہ زبردستی ریوڑ لے جاتے ہیں اور ان میں سے کھانا کھاتے ہیں۔ {کھلاؤ...: یا، انہیں کھلاؤ}\n3۔ وہ یتیم کے گدھے کو بھگا دیتے ہیں، بیوہ کے بیل کو گروی کے طور پر لیتے ہیں۔\n4. وہ محتاجوں کو راستے سے ہٹا دیتے ہیں: زمین کے غریب لوگ اکٹھے چھپ جاتے ہیں۔\n5۔ دیکھو، جیسے صحرا میں جنگلی گدھے، وہ اپنے کام پر نکلتے ہیں؛ شکار کے لیے پہلے سے اٹھنا شروع ہوتا ہے: بیابان ان کے لیے خوراک فراہم کرتا ہے اور ان کے بچوں کے لیے۔\n6۔ وہ کھیت میں اس کا اناج کاٹتے ہیں: اور بدکاروں کی شکار جمع کرتے ہیں۔ {کارن: عبوری۔ مخلوط مکئی، یا، ڈریج} {وہ جمع کرتے ہیں...: عبرانی۔ بدکار شراب جمع کرتے ہیں}\n7۔ وہ ننگے لوگوں کو بغیر کپڑوں کے رہنے پر مجبور کرتے ہیں، تاکہ سردی میں کوئی پردہ نہ ہو۔\n8. وہ پہاڑوں کی بارش سے بھیگ جاتے ہیں، اور پناہ کی کمی کی وجہ سے چٹان کو گلے لگاتے ہیں۔\n9۔ وہ یتیم کو سینے سے نکالتے ہیں، اور غریبوں کا عہد کرتے ہیں۔\n10۔ وہ {اسے} کو بغیر کپڑوں کے ننگا کر دیتے ہیں، اور بھوکوں سے گٹھا چھین لیتے ہیں؛\n11۔ {جو} اپنی دیواروں کے اندر تیل بناتے ہیں، {اور} اپنے شراب کے مشینوں پر چلتے ہیں، اور پیاس اٹھاتے ہیں۔\n12۔ لوگ شہر سے کراہتے ہیں، اور زخمیوں کی روح پکارتی ہے: پھر بھی خدا ان پر حماقت نہیں ڈالتا۔\n13۔ وہ ان میں سے ہیں جو روشنی کے خلاف بغاوت کرتے ہیں؛ وہ ان کے راستوں کو نہیں جانتے، نہ ہی ان کے راستوں پر رہتے ہیں۔\n14. روشنی کے ساتھ اٹھنے والا قاتل غریبوں اور محتاجوں کو مار دیتا ہے، اور رات کو چور کی طرح ہوتا ہے۔\n15۔ کی آنکھ بھی شام کا انتظار کرتی ہے، کہتی ہے، کوئی آنکھ مجھے نہیں دیکھے گی: اور اس کا چہرہ چھپا لیتی ہے۔ {بھیس بدلنے...: عبرانی اس کا چہرہ چھپ کر چھپا لیتا ہے}\n16۔ اندھیرے میں وہ گھروں میں کھودتے ہیں، {جو} انہوں نے دن میں خود نشان زد کیے تھے: وہ روشنی کو نہیں جانتے۔\n17. کیونکہ صبح {ہے} ان کے لیے موت کے سایہ کی طرح: اگر {کو} ان کو جانتا ہے تو وہ موت کے سائے کے خوف میں ہے۔\n18۔ وہ پانی کی طرح تیز ہے؛ ان کا حصہ زمین پر لعنت زدہ ہے: وہ انگور کے باغات کے راستے کو نہیں دیکھتا۔\n19۔ خشک سالی اور گرمی برف کے پانیوں کو کھا جاتی ہے: {اسی طرح} قبر {جنہوں نے} گناہ کیا ہے۔ {استعمال کریں: عببرانی۔ وائل لی ٹیک}\n20. رحم اسے بھول جائے گا؛ کیڑا اس پر میٹھا کھا جائے گا؛ اسے اب یاد نہیں رکھا جائے گا؛ اور برائی درخت کی طرح ٹوٹ جائے گی۔\n21. وہ برا اس بانجھ سے منت کرتا ہے جو برداشت نہیں کرتا: اور بیوہ کے ساتھ بھلائی نہیں کرتا۔\n22۔ وہ طاقتوروں کو بھی اپنی طاقت سے اپنی طرف کھینچتا ہے: وہ اٹھتا ہے، اور کوئی {انسان} زندگی کے بارے میں یقین نہیں رکھتا۔ {نہیں...: یا، وہ اپنی جان پر بھروسہ نہیں کرتا}\n23۔ {اگرچہ} اسے {محفوظ رہنے کے لیے} دیا جائے، جہاں وہ آرام کرتا ہے؛ پھر بھی اس کی نظریں ان کے طریقوں پر ہیں۔\n24۔ وہ کچھ دیر کے لیے بلند ہوتے ہیں، لیکن چلے جاتے ہیں اور نیچے گر جاتے ہیں؛ انہیں تمام {دوسرے} کی طرح راستے سے ہٹا دیا جاتا ہے، اور مکئی کے کانوں کے اوپر کے طور پر کاٹ دیا جاتا ہے۔ {چلے گئے: عببری۔ نہیں ہیں} {taken...: Hebrew. بند ہو گیا}\n25۔ اور اگر {ایسا نہیں} تو کون مجھے جھوٹا بنائے گا، اور میری بات کو بے وقعت بنا دے گا؟","1۔ پھر بلداد الشحیت نے جواب دیا اور کہا،\n2۔ حکمرانی اور خوف اس کے ساتھ ہیں، وہ اپنے اعلیٰ عہدوں پر امن قائم کرتا ہے۔\n3۔ کیا اس کی فوجوں کی کوئی تعداد موجود ہے؟ اور اس کی روشنی کس پر نہیں اٹھتی؟\n4. تو پھر انسان کو خدا کے سامنے کیسے راستباز بنایا جا سکتا ہے؟ یا وہ کیسے صاف ہو سکتا ہے {یعنی} عورت سے پیدا ہوا؟\n5۔ چاند کو دیکھو، اور وہ چمکتا نہیں؛ ہاں، ستارے اس کی نظر میں صاف نہیں ہیں۔\n6. انسان، {یعنی} کیڑا کتنا کم؟ اور انسان کا بیٹا، {جو کہ} کیڑا ہے؟","1۔ لیکن ایوب نے جواب دیا اور کہا،\n2. تم نے بغیر طاقت والے کی کیسے مدد کی؟ {کیسے} وہ بازو {جس میں طاقت نہیں} بچاتی ہے؟\n3. تم نے اس کو کیسے نصیحت کی ہے جس کے پاس کوئی حکمت نہیں؟ اور تم نے کیسے اس چیز کو جیسا ہے ویسا ہی بیان کیا ہے؟\n4۔ تم نے کس سے الفاظ کہے؟ اور کس کی روح تم سے آئی؟\n5. مردہ چیزیں پانی کے نیچے سے بنتی ہیں، اور اس کے باشندے۔ {اور...: یا، رہائشیوں کے ساتھ}\n6. جہنم اس کے سامنے ننگا ہے، اور تباہی کا کوئی پردہ نہیں۔\n7۔ وہ شمال کی طرف خالی جگہ پر پھیلا ہوا ہے، {اور} زمین کو کسی چیز پر لٹکا دیتا ہے۔\n8۔ وہ اپنے گھنے بادلوں میں پانیوں کو باندھتا ہے؛ اور ان کے نیچے بادل نہیں پھٹتا۔\n9۔ وہ اپنے تخت کے چہرے کو تھام لیتا ہے، {اور} اس پر اپنا بادل پھیلاتا ہے۔\n10۔ اس نے پانیوں کو حد سے گھیر رکھا ہے، یہاں تک کہ دن اور رات ختم ہو جائیں۔ {جب تک...: عبرانی۔ اندھیرے کے ساتھ روشنی کے خاتمے تک}\n11۔ آسمان کے ستون کانپتے ہیں اور اس کی سرزنش پر حیران رہ جاتے ہیں۔\n12۔ وہ اپنی طاقت سے سمندر کو تقسیم کرتا ہے، اور اپنی سمجھ سے مغروروں کو شکست دیتا ہے۔ {دی پراوڈ: عبرانی۔ فخر}\n13۔ اپنی روح سے اس نے آسمانوں کو سجایا؛ اس کے ہاتھ نے ٹیڑھا سانپ بنا لیا ہے۔\n14۔ دیکھو، یہ اس کے طریقوں کے حصے ہیں: لیکن اس کے بارے میں کتنا کم سنا جاتا ہے؟ لیکن اس کی طاقت کی گرج، کون سمجھ سکتا ہے؟","1۔ مزید ایوب نے اپنی تمثیل جاری رکھی اور کہا، {جاری ہے: عبرانی۔ شامل کیا گیا ہے کہ شروع کیا جا سکے}\n2. {جیسا کہ} خدا زندہ ہے، {جس نے} میرا فیصلہ چھین لیا ہے؛ اور قادر مطلق، {جس نے} میری روح کو پریشان کیا ہے؛ {ناراض...: عبرانی میری روح کو کڑوا کر دیا}\n3۔ جب تک میری سانس {ہے} میرے اندر ہے، اور خدا کی روح {ہے} میری نتھنوں میں؛ {روح...: یعنی وہ سانس جو خدا نے اسے دی}\n4. میرے ہونٹ بد نیتی نہیں بولیں گے، نہ میری زبان دھوکہ دے گی۔\n5. خدا نہ کرے کہ میں تمہیں جواز دوں: جب تک میں مر جاؤں میں اپنی دیانت داری نہیں چھینوں گا۔\n6. میری راستبازی میں مضبوطی سے تھامے ہوئے ہوں، اور اسے نہیں چھوڑوں گا: میرا دل مجھے ملامت نہیں کرے گا جب تک میں زندہ ہوں۔ {خدا حافظ...: عبرانی۔ میرے دنوں سے}\n7۔ میرا دشمن بدکار ہو اور جو میرے خلاف اٹھے وہ بدکار ہو۔\n8۔ کیونکہ منافق کی امید کیا ہے، چاہے اس نے حاصل کی ہو، جب خدا اس کی جان لے لیتا ہے؟\n9. کیا خدا اس کی پکار سنے گا جب اس پر مصیبت آئے گی؟\n10. کیا وہ قادر مطلق سے خوش ہوگا؟ کیا وہ ہمیشہ خدا کو پکار رہے گا؟\n11. میں تمہیں خدا کے ہاتھ سے سکھاؤں گا: {وہ} جو {ہے} میں چھپاؤں گا نہیں۔ {یعنی...: یا، ہاتھ میں ہونا، وغیرہ}\n12۔ دیکھو، تم نے خود سب کچھ دیکھا ہے؛ تو پھر تم اتنے خود پسند کیوں ہو؟\n13. یہ {ہے} ایک بدکار انسان کا خدا کے ساتھ حصہ، اور ظالموں کی وراثت، {جو} انہیں قادر مطلق سے ملے گا۔\n14۔ اگر اس کے بچے بڑھ جائیں تو یہ تلوار کے لیے ہے: اور اس کی اولاد روٹی سے مطمئن نہیں ہوگی۔\n15۔ جو اس کے باقی بچے ہیں انہیں موت میں دفن کیا جائے گا: اور اس کی بیوائیں نہیں روئیں گی۔\n16۔ اگرچہ وہ چاندی کو مٹی کی طرح جمع کرتا ہے، اور لباس مٹی کی طرح تیار کرتا ہے؛\n17۔ وہ تیار کر سکتا ہے، لیکن نیک لوگ پہنیں گے، اور معصوم چاندی تقسیم کریں گے۔\n18۔ وہ اپنا گھر پتنگ کی طرح بناتا ہے، اور ایک بوتھ کے طور پر جو رکھوالا بناتا ہے۔\n19۔ امیر آدمی لیٹ جائے گا، لیکن اسے جمع نہیں کیا جائے گا: وہ اپنی آنکھیں کھولتا ہے، اور وہ نہیں ہوتا۔\n20۔ خوف اس پر قابو پاتا ہے جیسے پانی، ایک طوفان اسے رات کے اندھیرے میں لے جاتا ہے۔\n21۔ مشرقی ہوا اسے لے جاتی ہے، اور وہ چلا جاتا ہے: اور جیسے طوفان اسے اس کی جگہ سے پھینک دیتا ہے۔\n22۔ کیونکہ {خدا} اس پر پھینکے گا، اور معاف نہیں کرے گا: وہ اس کے ہاتھ سے بھاگنا چاہتا ہے۔ {وہ...: عبرانی۔ بھاگتے ہوئے وہ بھاگ جائے گا}\n23۔ {آدمی} اس پر ہاتھ ماریں گے، اور اسے اس کی جگہ سے ہٹا دیں گے۔","1. یقینا چاندی کے لیے ایک رگ ہے، اور سونے کے لیے جگہ {جہاں} وہ اسے صاف کرتے ہیں۔ {رگ: یا، میرا}\n2۔ لوہا زمین سے نکالا جاتا ہے، اور پیتل پتھر سے پگھلا ہوا ہوتا ہے۔ {زمین: یا، دھول}\n3۔ وہ تاریکی کا خاتمہ کرتا ہے، اور تمام کمال کی تلاش کرتا ہے: تاریکی کے پتھر اور موت کا سایہ۔\n4۔ سیلاب باشندے سے پھوٹتا ہے؛ {یہاں تک کہ پانی} بھی پاؤں کو بھول چکا ہے: وہ خشک ہو چکے ہیں، وہ انسانوں سے دور ہو چکے ہیں۔\n5۔ {جہاں تک} زمین کا تعلق ہے، اس سے روٹی نکلتی ہے: اور اس کے نیچے آگ کی طرح ابھری ہوئی ہے۔\n6۔ اس کے پتھر نیلم کی جگہ ہیں: اور اس میں سونے کی خاک ہے۔ {گرد...: یا، سونے کی کان}\n7. {ایک راستہ ہے} جسے کوئی پرندہ نہیں جانتا، اور جسے گدھ کی آنکھ نے نہیں دیکھا:\n8۔ شیر کے بچے اسے نہیں روندے، نہ ہی خوفناک شیر اس کے پاس سے گزرا۔\n9۔ وہ اپنا ہاتھ چٹان پر رکھتا ہے؛ وہ پہاڑوں کو جڑوں سے الٹ دیتا ہے۔ {راک: یا، فلنٹ}\n10۔ وہ چٹانوں کے درمیان دریا کاٹتا ہے؛ اور اس کی آنکھ ہر قیمتی چیز کو دیکھتی ہے۔\n11۔ وہ سیلاب کو بہنے سے باندھ دیتا ہے؛ اور {جو چیز ہے} وہ روشنی میں سامنے آتی ہے۔ {اوور فلو: ہیب۔ رونا}\n12. لیکن حکمت کہاں ملے گی؟ اور سمجھ بوجھ کی جگہ کہاں ہے؟\n13۔ انسان اس کی قیمت نہیں جانتا؛ نہ ہی یہ زندہ لوگوں کی دنیا میں پایا جاتا ہے۔\n14۔ گہرائی کہتی ہے، وہ میرے اندر نہیں ہے؛ اور سمندر کہتا ہے، {یہ میرے ساتھ نہیں ہے}۔\n15۔ یہ سونے کے لیے حاصل نہیں کیا جا سکتا، نہ ہی چاندی کو اس کی قیمت کے مطابق تولا جائے گا۔ {یہ...: عبرانی۔ اس کے بدلے عمدہ سونا نہیں دیا جائے گا}\n16. اسے اوفیر کے سونے، قیمتی اونکس، یا نیلم سے قیمت نہیں لگایا جا سکتا۔\n17۔ سونا اور کرسٹل اس کے برابر نہیں ہو سکتے: اور اس کا تبادلہ {نفیس سونے کے جواہرات} کے لیے نہیں ہوگا۔ {جواہرات...: یا، برتن کے}\n18۔ مرجان یا موتیوں کا ذکر نہیں کیا جائے گا: کیونکہ حکمت کی قیمت یاقوت سے زیادہ ہے۔ {مرجان: یا، راموتھ}\n19۔ ایتھوپیا کی ٹوپاز اس کے برابر نہیں ہوگی، نہ ہی خالص سونے سے اس کی قدر کی جائے گی۔\n20۔ پھر حکمت کہاں سے آتی ہے؟ اور سمجھ بوجھ کی جگہ کہاں ہے؟\n21۔ اسے دیکھنا تمام جانداروں کی آنکھوں سے چھپا ہوا ہے، اور ہوا کے پرندوں سے قریب رکھا جاتا ہے۔ {ہوا: یا، جنت}\n22۔ تباہی اور موت کہتے ہیں، ہم نے اس کی شہرت اپنے کانوں سے سنی ہے۔\n23۔ خدا اس کے راستے کو سمجھتا ہے، اور وہ اس کی جگہ جانتا ہے۔\n24۔ کیونکہ وہ زمین کے کناروں تک دیکھتا ہے، {اور} پورے آسمان کے نیچے دیکھتا ہے؛\n25۔ ہوا کے وزن کو پورا کرنا؛ اور وہ پانی کو ناپ تولتا ہے۔\n26۔ جب اس نے بارش کے لیے حکم اور بجلی کے لیے راستہ بنایا:\n27۔ پھر اس نے اسے دیکھا اور اعلان کیا؛ اس نے اسے تیار کیا، ہاں، اور تلاش کیا۔ {اعلان کرو...: یا، نمبر دو}\n28۔ اور اس نے انسان سے کہا، دیکھو، خداوند کا خوف جو حکمت ہے؛ اور برائی سے دور ہونا سمجھ بوجھ ہے۔","1۔ مزید ایوب نے اپنی تمثیل جاری رکھی اور کہا، {جاری ہے: عبرانی۔ شامل کیا گیا ہے کہ شروع کیا جا سکے}\n2. کاش میں {میں} مہینوں میں ہوتا، {میں} ان دنوں {جب} خدا نے مجھے محفوظ رکھا؛\n3۔ جب اس کی موم بتی میرے سر پر چمکی، {اور جب} اس کی روشنی سے میں اندھیرے میں چل پڑا؛ {موم بتی: یا، چراغ}\n4۔ جیسا کہ میں اپنی جوانی کے دنوں میں تھا، جب خدا کا راز میرے خیمے میں تھا؛\n5. جب قادر مطلق {ابھی میرے ساتھ تھا}، {جب} میرے بچے {تھے} میرے اردگرد تھے؛\n6۔ جب میں نے اپنے قدم مکھن سے دھوئے، اور پتھر نے مجھے تیل کی ندیاں بہا دیں؛ {میں: عبرانی۔ میرے ساتھ}\n7. جب میں شہر کے دروازے پر گیا، {جب} میں نے سڑک پر اپنی نشست تیار کی!\n8۔ نوجوانوں نے مجھے دیکھا اور چھپ گئے: اور بوڑھے اٹھے، {اور} کھڑے ہو گئے۔\n9۔ شہزادوں نے بات کرنے سے گریز کیا، اور اپنا ہاتھ اپنے منہ پر رکھا۔\n10۔ اشرافیہ خاموش رہے، اور ان کی زبان منہ کی چھت سے چپک گئی۔ {اشرافیہ...: عبرانی۔ اشرافیہ کی آواز چھپی ہوئی تھی}\n11۔ جب کان نے {مجھے} کو سنا، تو اس نے مجھے برکت دی؛ اور جب آنکھ نے مجھے دیکھا، تو اس نے مجھے گواہی دی:\n12۔ کیونکہ میں نے ان غریبوں کو نجات دی جو روتے تھے، اور یتیم کو، اور {جس کے پاس کوئی مدد نہیں تھی}۔\n13۔ جو مرنے کو تیار تھا اس کی برکت مجھ پر آئی: اور میں نے بیوہ کے دل کو خوشی سے گانے پر مجبور کیا۔\n14۔ میں نے راستبازی پہنی، اور اس نے مجھے لباس پہنا: میرا فیصلہ {تھا} ایک چادر اور تاج کی طرح۔\n15۔ میں اندھے پر نظر رکھتا تھا، اور پاؤں لنگڑوں کو۔\n16. میں غریبوں کا باپ تھا: اور وہ مقصد {جسے میں نہیں جانتا تھا} میں نے تلاش کیا۔\n17۔ اور میں نے بدکاروں کے جبڑے توڑ دیے، اور اس کے دانتوں سے مال نکال لیا۔ {دی جوز: ہیب۔ جبڑے کے دانت، یا، گرائنڈرز} {چھیلا: عبرانی۔ کاسٹ}\n18۔ پھر میں نے کہا، میں اپنے گھونسلے میں مر جاؤں گا، اور اپنے دن ریت کی طرح بڑھاؤں گا۔\n19۔ میری جڑ پانی کے پاس پھیلی ہوئی تھی، اور شبنم ساری رات میری شاخ پر پڑی رہی۔ {پھیلاؤ...: عببرانی۔ کھولا گیا}\n20۔ میری شان میرے اندر تازہ تھی، اور میرا کمان میرے ہاتھ میں تازہ ہو گیا۔ {تازہ: عبوری۔ نیا} {تجدید شدہ: عبرانی۔ بدل گیا}\n21۔ {مردوں} نے میری بات سنائی، انتظار کیا، اور میری نصیحت پر خاموش رہے۔\n22۔ میرے الفاظ کے بعد انہوں نے دوبارہ بات نہیں کی؛ اور میری تقریر ان پر گر پڑی۔\n23۔ اور وہ بارش کے لیے میرا انتظار کرتے رہے؛ اور انہوں نے آخری بارش کے لیے منہ کھول دیا۔\n24۔ {اگر} میں ان پر ہنستا تو وہ یقین نہیں کرتے؛ اور میرے چہرے کی روشنی کو وہ گرا نہیں دیتے۔\n25۔ میں نے ان کا راستہ چنا، سردار بن گیا، اور فوج میں بادشاہ کی طرح رہا، جیسا کہ سوگواروں کو تسلی دیتا ہے۔","1. لیکن اب {جو مجھ سے چھوٹے ہیں} وہ مجھے مذاق میں رکھتے ہیں، جن کے باپ میں اپنے ریوڑ کے کتوں کے ساتھ ملنا پسند نہیں کرتا۔ {چھوٹا...: عبرانی۔ مجھ سے بھی کم دنوں کے}\n2. ہاں، ان کے ہاتھوں کی طاقت مجھے کہاں فائدہ دے سکتی ہے، جس میں بوڑھاپا مر گیا؟\n3۔ کمی اور قحط کے لیے {وہ تنہا تھے}؛ پرانے وقت میں ویران اور ویران جنگل میں بھاگ رہا تھا۔ {تنہا: یا، رات کی طرح تاریک} {میں...: عبرانی گزشتہ رات}\n4۔ جنہوں نے جھاڑیوں سے مالو اور جونیپر کی جڑیں اپنے گوشت کے لیے کاٹیں۔\n5. انہیں {انسان} سے نکال دیا گیا، (وہ چور کی طرح ان کے پیچھے پکارے؛)\n6۔ وادیوں کے کناروں میں، زمین کی غاروں میں، اور چٹانوں میں بسنا۔ {کیوز: عبرانی۔ ہولز}\n7۔ جھاڑیوں کے درمیان وہ شور مچائے؛ بچھوے کے درختوں کے نیچے وہ سب اکٹھے تھے۔\n8. {وہ} احمقوں کے بچے تھے، ہاں، نچلے انسانوں کے بچے: وہ زمین سے بھی زیادہ گھٹیا تھے۔ {بنیاد...: عببرانی۔ بے نام آدمی}\n9. اور اب میں ان کا گانا ہوں، ہاں، میں ان کا نعرہ ہوں۔\n10۔ وہ مجھ سے نفرت کرتے ہیں، مجھ سے دور بھاگ جاتے ہیں، اور میرے منہ پر تھوکنے سے گریز کرتے ہیں۔ {اور...: عبرانی۔ اور تھوک نہ روکیں}\n11۔ کیونکہ اس نے میری رسی کو کھولا اور مجھے تکلیف دی، انہوں نے میرے سامنے لگام بھی چھوڑ دی۔\n12. میرے دائیں ہاتھوں پر نوجوان اٹھتے ہیں؛ وہ میرے پاؤں کو دھکیلتے ہیں، اور اپنی تباہی کے راستے میرے خلاف اٹھاتے ہیں۔\n13۔ وہ میرے راستے کو خراب کرتے ہیں، میری آفت کو آگے بڑھاتے ہیں، ان کا کوئی مددگار نہیں۔\n14۔ وہ {مجھ پر} ایک وسیع دراڑ کی طرح آئے {پانیوں کی}: ویرانی میں انہوں نے خود کو {مجھ پر} لپیٹ دیا۔\n15۔ میرے اوپر خوف مسلط ہو جاتا ہے: وہ میری روح کا پیچھا کرتے ہیں جیسے ہوا ہو: اور میری خیریت بادل کی طرح ختم ہو جاتی ہے۔ {میری روح: عبرانی۔ میرا پرنسپل والا}\n16۔ اور اب میری روح مجھ پر بہائی گئی ہے؛ مصیبت کے دن مجھ پر چھا گئے ہیں۔\n17۔ میری ہڈیاں رات کے موسم میں میرے اندر چھید دی جاتی ہیں: اور میرے ریشے آرام نہیں کرتے۔\n18۔ میری بیماری کی عظیم طاقت سے میرا لباس بدل گیا ہے: یہ مجھے میرے کوٹ کے کالر کی طرح باندھ دیتا ہے۔\n19۔ اس نے مجھے کیچڑ میں پھینک دیا ہے، اور میں خاک اور راکھ کی طرح بن گیا ہوں۔\n20۔ میں تم سے پکار رہا ہوں، اور تم مجھے نہیں سنتے: میں کھڑا ہوتا ہوں، اور تم مجھے دیکھتے ہو {نہیں}۔\n21. تم میرے ساتھ ظالم ہو گئے ہو: اپنے مضبوط ہاتھ سے تم میرے خلاف خود کو روک رہے ہو۔ {بن جاؤ...: عبرانی۔ ظالم بن گیا} {تمہارا...: عبرانی۔ تیرے ہاتھ کی طاقت}\n22۔ تو مجھے ہوا کے سامنے اٹھا لیتا ہے؛ تم مجھے اس پر سوار کرتے ہو، اور میرا مال ختم کر دیتے ہو۔ {مادہ: یا، حکمت}\n23. کیونکہ میں جانتا ہوں کہ تم مجھے موت تک لے آؤ گے، اور اس گھر کو جو سب جانداروں کے لیے مقرر کیا گیا ہے۔\n24. تاہم وہ قبر کی طرف ہاتھ نہیں بڑھائے گا، چاہے لوگ اس کی تباہی میں روتے ہوں۔ {قبر: عبرانی ہیپ}\n25۔ کیا میں اس کے لیے نہیں رویا جو مشکل میں تھا؟ کیا میری روح غریبوں کے لیے غمگین نہیں تھی؟ {مشکل میں: عبرانی۔ مشکل دن؟}\n26. جب میں نے نیکی تلاش کی، تو برائی {میرے پاس} آئی: اور جب میں روشنی کا انتظار کرتا تو اندھیرا آتا۔\n27۔ میری آنتیں ابل رہی تھیں، اور آرام نہیں کیا: مصیبت کے دن مجھے روک رہے تھے۔\n28۔ میں بغیر سورج کے سوگ منایا: میں کھڑا ہوا، {اور} میں جماعت میں رویا۔\n29۔ میں ڈریگنوں کا بھائی ہوں، اور الوؤں کا ساتھی ہوں۔ {الو: یا، شتر مرغ}\n30۔ میری جلد میرے اوپر سیاہ ہے، اور میری ہڈیاں حرارت سے جل رہی ہیں۔\n31. میرا ہارپ بھی سوگ میں بدل گیا ہے، اور میرا عضو ان رونے والوں کی آواز میں بدل گیا ہے۔","1۔ میں نے اپنی آنکھوں سے عہد کیا؛ تو پھر میں نوکرانی کے بارے میں کیوں سوچوں؟\n2. خدا کے کس حصے کے لیے اوپر سے ہے؟ اور اعلیٰ سے قادر مطلق کی کیا وراثت؟\n3. {کیا} بدکاروں کے لیے تباہی نہیں؟ اور بدکاری کے مزدوروں کے لیے ایک عجیب {سزا}؟\n4. کیا وہ میرے راستے نہیں دیکھتا، اور میرے سارے قدم نہیں گنتا؟\n5۔ اگر میں غرور کے ساتھ چل رہا ہوں، یا اگر میرا قدم دھوکہ دینے میں جلدی کر گیا ہے؛\n6. مجھے برابر توازن میں تولنے دو، تاکہ خدا میری دیانتداری جان سکے۔ {چلو...: عبرانی۔ وہ مجھے انصاف کے ترازو میں تولے}\n7۔ اگر میرا قدم ہٹ گیا ہو، اور میرا دل میری آنکھوں کے پیچھے چل رہا ہو، اور اگر میرے ہاتھوں میں کوئی داغ لگا ہو؛\n8. {پھر} مجھے بونے دو، اور کسی اور کو کھانے دو؛ ہاں، میرے بچوں کو جڑ سے نکالنے دو۔\n9۔ اگر میرا دل کسی عورت سے دھوکہ کھا گیا ہو، یا {اگر} میں نے اپنے پڑوسی کے دروازے پر انتظار کیا ہو؛\n10۔ {پھر} میری بیوی کو کسی اور کے لیے رگڑنے دو، اور دوسروں کو اس پر جھکنے دو۔\n11۔ کیونکہ یہ {ہے} ایک سنگین جرم ہے؛ جی ہاں، یہ {ایک ناانصاف} ہے {جسے ججوں کی طرف سے سزا دی جائے}۔\n12. کیونکہ یہ {ہے} ایک آگ {جو} تباہی کو جلا دیتی ہے، اور میری تمام آگ کو جڑ سے اکھاڑ دیتی ہے۔\n13۔ اگر میں اپنے خادم یا نوکرانی کے معاملے سے نفرت کرتا، جب وہ مجھ سے جھگڑتے؛\n14. پھر جب خدا اٹھے گا تو میں کیا کروں؟ اور جب وہ آئے گا، تو میں اسے کیا جواب دوں؟\n15. کیا وہ نہیں بناتا جس نے مجھے رحم میں بنایا؟ اور کیا کسی نے ہمیں رحم میں نہیں بنایا؟ {کیا کوئی نہیں...: یا، کیا اس نے ہمیں ایک ہی پیٹ میں نہیں بنایا؟}\n16۔ اگر میں نے غریبوں کو ان کی خواہش سے روکا ہو، یا بیوہ کی آنکھوں کو کمزور کر دیا ہو؛\n17۔ یا میں نے اپنا ٹکڑا اکیلا کھایا ہے، اور یتیم نے اسے نہیں کھایا؛\n18۔ (کیونکہ میری جوانی سے ہی وہ میرے ساتھ ایک باپ کی طرح پروان چڑھا، اور میں نے اسے اپنی ماں کے پیٹ سے رہنمائی کی؛) {وہ: یعنی، بیوہ}\n19۔ اگر میں نے کسی کو لباس کی کمی کی وجہ سے مرتے دیکھا ہو، یا کوئی بے بس بغیر پردے کے؛\n20۔ اگر اس کی کمر نے مجھے برکت نہ دی، اور {اگر} وہ میری بھیڑ کی اون سے گرم نہ ہوتا؛\n21۔ اگر میں نے یتیم کے خلاف ہاتھ اٹھایا ہو، جب میں نے دروازے پر اپنی مدد دیکھی:\n22۔ {پھر} میرا بازو کندھے کی ہڈی سے گر گیا، اور میرا بازو ہڈی سے ٹوٹ گیا۔ {بون: یا، چینل بون}\n23۔ خدا کی تباہی {سے} میرے لیے ایک خوف تھا، اور اس کی عظمت کی وجہ سے میں برداشت نہیں کر سکا۔\n24۔ اگر میں نے سونا اپنی امید بنا لی ہے، یا عمدہ سونے سے کہا ہے، {تو} میرا اعتماد ہے؛\n25۔ اگر میں خوش ہوتا کیونکہ میری دولت {عظیم} تھی، اور کیونکہ میرا ہاتھ بہت کچھ حاصل کر چکا تھا؛ {حاصل ہوا...: عبوری۔ بہت کچھ ملا}\n26۔ اگر میں سورج کو چمکتے ہوئے دیکھتا، یا چاند کو روشنی میں چلتا دیکھتا؛ {سورج: عبدی۔ روشنی} {میں...: عبرانی روشن}\n27۔ اور میرا دل چپکے سے بہکایا گیا ہے، یا میرے منہ نے میرے ہاتھ کو بوسہ دیا ہے: {میرا منہ...: عبرانی۔ میرا ہاتھ میرے منہ پر بوسہ دے چکا ہے}\n28۔ یہ بھی {تھا} ایک گناہ {جسے جج سزا دیتا ہے}: کیونکہ مجھے اوپر والے خدا {یعنی} کو انکار کرنا چاہیے تھا۔\n29۔ اگر میں اس کی تباہی پر خوش ہوا جو مجھ سے نفرت کرتا تھا، یا جب برائی نے اسے پایا تو خود کو اٹھایا:\n30۔ نہ ہی میں نے اپنے منہ کو اس کی روح پر لعنت کی خواہش کر کے گناہ کرنے دیا۔ {منہ: عبرانی۔ ذائقہ}\n31۔ اگر میرے خیمہ کے لوگ نہ کہیں، کاش ہمارے پاس اس کا گوشت ہوتا! ہم مطمئن نہیں ہو سکتے۔\n32۔ اجنبی نے سڑک پر قیام نہیں کیا: {لیکن} میں نے اپنے دروازے مسافر کے لیے کھول دیے۔ {مسافر: یا، وے}\n33۔ اگر میں نے آدم کی طرح اپنی گناہوں کو چھپایا ہوتا، اپنی گناہوں کو اپنے سینے میں چھپا کر: {آدم کی طرح: یا، انسانوں کے طریقے پر}\n34۔ کیا میں بڑی تعداد سے ڈرتا تھا، یا خاندانوں کی حقارت نے مجھے خوفزدہ کر دیا کہ میں خاموش رہا، {اور} دروازے سے باہر نہیں گیا؟\n35۔ اوہ، وہ مجھے سن لے گا! دیکھو، میری خواہش {یہ ہے} کہ خداوند مجھے جواب دے، اور {کہ} میرا مخالف ایک کتاب لکھ چکا ہے۔ {میرا...: یا، میرا نشان ہے کہ قادر مطلق کرے گا}\n36۔ یقینا میں اسے اپنے کندھے پر اٹھا کر {اور} اسے اپنے لیے تاج کی طرح باندھ دوں گا۔\n37۔ میں اسے اپنے قدموں کی تعداد بتاؤں گا؛ ایک شہزادے کی حیثیت سے میں اس کے قریب جاؤں گا۔\n38۔ اگر میری زمین میرے خلاف پکار رہی ہو، یا اس کی شکنیں بھی شکایت کریں؛ {شکایت: عبرانی۔ رونا}\n39۔ اگر میں نے اس کے پھل بغیر پیسے کے کھائے ہوں، یا اس کے مالکان کی جان گنوا دی ہو: {پھل: عبرانی۔ طاقت} {مالکان...: عبرانی۔ ان کے مالکان کی روح مر جائے، یا، سانس چھوڑ دے}\n40۔ گندم کی جگہ تھسلز اگنے دیں، اور جو کی جگہ کاکل۔ ایوب کے الفاظ ختم ہو جاتے ہیں۔ {کاکل: یا، شور مچانے والی گھاسیاں}","1۔ تو یہ تینوں آدمی ایوب کو جواب دینا بند کر گئے، کیونکہ وہ اپنی نظر میں راستباز تھا۔ {تو...: عبرانی جواب دینے سے}\n2۔ پھر الیہو، باراکل بوزیت کے بیٹے اور رام کے رشتہ داروں کا غصہ بھڑکا: ایوب کے خلاف اس کا غصہ بھڑکا، کیونکہ اس نے خدا کی بجائے خود کو جائز قرار دیا۔ {خود: عبرانی۔ اس کی روح}\n3۔ اس کے تین دوستوں کے خلاف بھی اس کا غصہ بھڑکا، کیونکہ انہیں کوئی جواب نہیں ملا، اور {ابھی} انہوں نے ایوب کی مذمت کی تھی۔\n4۔ اب ایلیہو نے ایوب کے بولنے کا انتظار کیا، کیونکہ وہ اس سے بڑے تھے۔ {انتظار کیا...: عبرانی۔ متوقع جاب الفاظ میں} {بزرگ: عبرانی۔ کئی دنوں کے لیے بزرگ}\n5۔ جب ایلیہو نے دیکھا کہ {ان} تین آدمیوں کے منہ میں کوئی جواب نہیں ہے، تو اس کا غصہ بھڑک اٹھا۔\n6۔ اور الیہو بیٹا باراخیل بوزیت نے جواب دیا اور کہا، میں جوان ہوں، اور تم بہت بوڑھے ہو؛ اسی لیے میں ڈر گیا، اور اپنی رائے دینے کی ہمت نہ کی۔ {نوجوان: عبوری۔ چند دن} {ہمت ہے...: عبرانی۔ خوفزدہ}\n7. میں نے کہا، دن بولیں گے، اور کثرت سال حکمت سکھائیں گے۔\n8۔ لیکن انسان میں ایک روح ہے: اور قادر مطلق کی الہام انہیں سمجھ دیتی ہے۔\n9۔ عظیم لوگ {ہمیشہ} دانا نہیں ہوتے: نہ ہی بزرگ فیصلے کو سمجھتے ہیں۔\n10۔ اسی لیے میں نے کہا، میری بات سنو؛ میں اپنی رائے بھی دوں گا۔\n11۔ دیکھو، میں تمہارے الفاظ کا انتظار کر رہا تھا؛ میں نے تمہاری وجوہات سنیں، جب تم نے کیا کہنا ہے تلاش کیا۔ {وجوہات: عبرانی۔ سمجھیں} {کیا...: عبرانی الفاظ}\n12۔ جی ہاں، میں نے تمہاری خدمت کی، اور دیکھو، {تم میں سے} میں سے کوئی ایسا نہیں تھا جس نے ایوب کو قائل کیا، {یا} اس کے الفاظ کا جواب دیا:\n13۔ تاکہ تم یہ نہ کہو کہ ہم نے حکمت حاصل کر لی ہے: خدا اسے نیچے گراتا ہے، انسان نہیں۔\n14۔ اب اس نے میرے خلاف الفاظ نہیں کیے، اور نہ ہی میں تمہاری باتوں سے جواب دوں گا۔ {ہدایت شدہ: یا، ترتیب دیا گیا}\n15۔ وہ حیران رہ گئے، انہوں نے مزید جواب نہیں دیا: انہوں نے بولنا چھوڑ دیا۔ {بائیں...: عبرانی۔ اپنے آپ سے تقاریر ہٹا دیتی ہیں}\n16۔ جب میں نے انتظار کیا، (کیونکہ انہوں نے کچھ نہیں کہا، لیکن خاموش رہے، {اور} مزید جواب نہیں دیا؛)\n17. {میں نے کہا}، میں اپنی رائے بھی دوں گا، میں اپنی رائے بھی دوں گا۔\n18۔ کیونکہ میں مادے سے بھرا ہوا ہوں، میرے اندر کی روح مجھے مجبور کرتی ہے۔ {معاملہ: عبرانی۔ الفاظ} {روح...: عبرانی۔ میرے پیٹ کی روح}\n19۔ دیکھو، میرا پیٹ {ہے} شراب کی طرح {جس میں کوئی سوراخ نہیں}؛ یہ نئی بوتلوں کی طرح پھٹنے کو تیار ہے۔ {hath...: عبرانی۔ نہیں کھولا گیا}\n20۔ میں بولوں گا، تاکہ میں تازہ دم ہو سکوں: میں اپنے ہونٹ کھولوں گا اور جواب دوں گا۔ {be...: عبرانی۔ سانس لو}\n21. میں آپ سے دعا کرتا ہوں کہ میں کسی مرد کی ذات کو قبول نہ کروں، نہ ہی میں انسان کو تعریف کرنے والے القابات دوں۔\n22۔ کیونکہ میں جانتا ہوں کہ تعریفی القابات نہیں دینی چاہیے؛ {ایسا کر کے} میرا خالق جلد ہی مجھے لے جائے گا۔","1۔ اسی لیے، ایوب، میں دعا کرتا ہوں کہ میری باتیں سنو اور میری تمام باتوں کو سنو۔\n2۔ دیکھو، اب میں نے اپنا منہ کھولا ہے، میری زبان نے میرے منہ میں بول دیا۔ {میرے منہ میں: عبوری۔ میرے ذائقے میں}\n3۔ میرے الفاظ میرے دل کی سیدھی داری کے ہوں گے: اور میرے ہونٹ علم کو صاف ظاہر کریں گے۔\n4۔ خدا کی روح نے مجھے بنایا ہے، اور قادر مطلق کی سانس نے مجھے زندگی دی ہے۔\n5۔ اگر تم مجھے جواب دے سکتے ہو تو {اپنے الفاظ} کو میرے سامنے ترتیب دو، کھڑے ہو جاؤ۔\n6۔ دیکھو، میں خدا کی جگہ تیری خواہش کے مطابق ہوں: میں بھی مٹی سے بنی ہوں۔ {خواہش: عبرانی۔ منہ} {تشکیل شدہ: عبرانی۔ کٹ}\n7۔ دیکھو، میرا خوف تمہیں خوفزدہ نہیں کرے گا، نہ ہی میرا ہاتھ تم پر بھاری ہوگا۔\n8۔ یقینا تم نے میری سماعت میں بات کی ہے، اور میں نے {تمہارے} الفاظ کی آواز سنی ہے، {کہا}، {سنا: عبرانی۔ کان}\n9۔ میں بغیر کسی گناہ کے پاک ہوں، میں {معصوم} ہوں؛ نہ ہی مجھ میں کوئی بدکاری ہے۔\n10۔ دیکھو، جب وہ میرے خلاف مواقع تلاش کرتا ہے، تو وہ مجھے اپنا دشمن سمجھتا ہے،\n11۔ وہ میرے پاؤں اسٹاکس میں ڈالتا ہے، میرے تمام راستے مارکیٹ کرتا ہے۔\n12۔ دیکھو، {اس میں} تم عادل نہیں ہو: میں تمہیں جواب دوں گا کہ خدا انسان سے بڑا ہے۔\n13۔ تم اس کے خلاف کیوں لڑ رہے ہو؟ کیونکہ وہ اپنے کسی معاملے کا حساب نہیں دیتا۔ {وہ دیتا ہے...: عبرانی۔ وہ جواب نہیں دیتا}\n14۔ کیونکہ خدا ایک بار بولتا ہے، ہاں دو بار، {لیکن انسان} اسے محسوس نہیں کرتا۔\n15۔ ایک خواب میں، رات کے خواب میں، جب گہری نیند انسانوں پر چھا جاتی ہے، بستر پر نیند میں؛\n16۔ پھر وہ انسانوں کے کان کھولتا ہے، اور ان کی تعلیم کو مہر لگاتا ہے، {وہ...: عبرانی۔ وہ ظاہر کرتا ہے، یا، بے نقاب کرتا ہے}\n17. تاکہ وہ انسان کو اس کے مقصد سے ہٹا سکے، اور انسان سے غرور چھپا سکے۔ {مقصد: عبرانی۔ کام}\n18۔ وہ اپنی روح کو گڑھے سے بچاتا ہے، اور اپنی جان کو تلوار سے فنا ہونے سے بچاتا ہے۔ {فرائنگ سے: عبرانی پاسنگ سے}\n19۔ وہ اپنے بستر پر درد کے ساتھ بھی سزا پاتا ہے، اور اس کی ہڈیوں کی کثرت شدید {درد} سے بھی:\n20. تاکہ اس کی زندگی روٹی سے نفرت کرے، اور اس کی روح نازک گوشت ہو۔ {نرمی سے...: عببرانی۔ خواہش کا گوشت}\n21۔ اس کا گوشت کھا لیا جاتا ہے، تاکہ وہ نظر نہ آئے؛ اور اس کی ہڈیاں {جو نظر نہیں آئیں} باہر نکلی ہوئی تھیں۔\n22. ہاں، اس کی روح قبر کے قریب آتی ہے، اور اس کی زندگی تباہ کرنے والوں کے لیے۔\n23۔ اگر اس کے ساتھ کوئی پیغامبر، مترجم، ہزاروں میں سے ایک ہو، جو انسان کو اپنی راستبازی دکھائے:\n24۔ پھر وہ اس پر مہربان ہے، اور کہتا ہے، اسے گڑھے میں جانے سے بچا لو: میں نے فدیہ پایا ہے۔ {تاوان: یا، کفارہ}\n25۔ اس کا جسم بچے کے جسم سے بھی زیادہ تازہ ہوگا: وہ اپنی جوانی کے دنوں میں واپس جائے گا: {ایک بچے کا: عبرانی۔ بچپن}\n26۔ وہ خدا سے دعا کرے گا، اور اس کے ساتھ مہربان ہوگا، اور اس کا چہرہ خوشی سے دیکھے گا: کیونکہ وہ اپنی راستبازی انسان کو دے گا۔\n27۔ وہ انسانوں کو دیکھتا ہے، اور {اگر کوئی ہے} کہتا ہے، میں نے گناہ کیا ہے، اور جو صحیح تھا اسے بگاڑ دیا ہے، اور اس سے مجھے کوئی فائدہ نہیں ہوا؛ {وہ...: یا، وہ انسانوں کو دیکھے گا، اور کہے گا}\n28۔ وہ اپنی روح کو گڑھے میں جانے سے نجات دے گا، اور اس کی زندگی روشنی دیکھے گی۔ {وہ...: یا، اس نے میری جان اور میری زندگی کو نجات دی ہے}\n29۔ دیکھو، یہ سب {چیزیں} خدا کے ساتھ اکثر انسان کے ساتھ کام کرتی ہیں، {اکثر: عبرانی۔ دو بار اور تین بار}\n30۔ اپنی روح کو گڑھے سے واپس لانا، زندہ کی روشنی سے روشن ہونا۔\n31۔ اے ایوب، اچھی طرح یاد رکھو، میری بات سنو: خاموش رہو، اور میں بولوں گا۔\n32۔ اگر تمہارے پاس کہنے کو کچھ ہے تو مجھے جواب دو: بولو، کیونکہ میں تمہیں راستباز ثابت کرنا چاہتا ہوں۔\n33۔ اگر نہیں، تو میری بات سنو: خاموش رہو، اور میں تمہیں حکمت سکھاؤں گا۔","1۔ مزید ایلیہو نے جواب دیا اور کہا،\n2. اے دانا حضرات، میری باتیں سنو؛ اور میری بات سنو، اے علم رکھنے والے۔\n3۔ کیونکہ کان الفاظ آزماتا ہے، جیسے منہ گوشت کا ذائقہ چکھتا ہے۔ {منہ: عبرانی۔ ذائقہ}\n4. آئیے اپنے لیے فیصلہ منتخب کریں: آپس میں جان لیں کہ کیا {اچھا} ہے۔\n5۔ کیونکہ ایوب نے کہا ہے، میں راستباز ہوں: اور خدا نے میرا فیصلہ چھین لیا ہے۔\n6. کیا مجھے اپنے دائیں بازو کے خلاف جھوٹ بولنا چاہیے؟ میرا زخم بغیر کسی جرم کے لاعلاج ہے۔ {میرا زخم: عبرانی۔ مائن ایرو}\n7. کون سا آدمی ایوب کی طرح ہے، جو پانی کی طرح حقارت سے پیتا ہے؟\n8۔ جو بدکار مزدوروں کے ساتھ جاتا ہے، اور بدکاروں کے ساتھ چلتا ہے۔\n9۔ کیونکہ اس نے کہا ہے، انسان کو خدا سے خوش ہونا کوئی فائدہ نہیں۔\n10۔ لہٰذا، اے سمجھدار لوگو، میری بات سنو: خدا سے دور ہو کہ وہ بدکاری کرے؛ اور {قادر مطلق} سے، {کہ وہ گناہ کرے۔ {مرد...: عبرانی۔ مین آف ہارٹ}\n11۔ کیونکہ انسان کا کام اس کے سپرد کرے گا، اور ہر انسان کو اس کے طریقے کے مطابق تلاش کرے گا۔\n12. ہاں، یقینا خدا برا نہیں کرے گا، نہ ہی قادر مطلق بگاڑ والا فیصلہ۔\n13۔ کس نے اسے زمین پر ذمہ داری دی ہے؟ یا کس نے پوری دنیا کو برباد کر دیا ہے؟ {مجموعا: عبرانی۔ سب کچھ؟}\n14۔ اگر وہ اپنا دل انسان پر مرکوز کرے، {اگر} وہ اپنی روح اور سانس کو اپنے اندر جمع کرے؛ {آدمی: عبرانی۔ وہ}\n15۔ تمام جسم مل کر فنا ہو جائیں گے، اور انسان دوبارہ خاک میں بدل جائے گا۔\n16۔ اگر اب {تمہیں سمجھ ہے} تو یہ سنو: میرے الفاظ کی آواز سنو۔\n17۔ کیا جو حق سے نفرت کرتا ہے وہ بھی حکومت کرے گا؟ اور کیا تم سب سے زیادہ منصف کو سزا دو گے؟ {گورنمنٹ: عبرانی۔ باند؟}\n18. {کیا یہ مناسب ہے} کہ بادشاہ سے کہا جائے، {تو ظالم ہو؟' {اور} شہزادوں کے لیے، {تم ناخدا ہو؟'\n19. {اس کے لیے کتنا کم} جو شہزادوں کی شخصیات کو قبول نہیں کرتا، اور نہ ہی امیروں کو غریبوں سے زیادہ اہمیت دیتا ہے؟ کیونکہ یہ سب اس کے ہاتھوں کا کام ہیں۔\n20۔ ایک لمحے میں وہ مر جائیں گے، اور لوگ آدھی رات کو پریشان ہوں گے، اور چلے جائیں گے: اور طاقتور بغیر ہاتھ کے لے جائیں گے۔ {عظیم...: عبرانی۔ وہ طاقتور کو لے جائیں گے}\n21۔ کیونکہ اس کی آنکھیں انسان کے راستوں پر ہیں، اور وہ اپنی تمام حرکات کو غصہ دلاتا ہے۔\n22۔ {کوئی تاریکی} نہیں، نہ موت کا سایہ، جہاں بدکاری کرنے والے خود کو چھپا سکیں۔\n23۔ کیونکہ وہ انسان پر حق سے زیادہ نہیں ڈالے گا؛ کہ وہ خدا کے ساتھ فیصلے میں داخل ہو جائے۔ {داخل کریں: عبرانی۔ چلو}\n24۔ وہ بے شمار طاقتور مردوں کو ٹکڑوں میں توڑے گا، اور دوسروں کو ان کی جگہ دے گا۔ {نمبر: عبرانی۔ تلاش کر رہا ہوں}\n25۔ اس لیے وہ ان کے اعمال جانتا ہے، اور رات کو انہیں الٹ دیتا ہے تاکہ وہ تباہ ہو جائیں۔ {تباہ شدہ: عبرانی۔ کچل دیا گیا}\n26۔ وہ انہیں دوسروں کے سامنے برے آدمی سمجھتا ہے؛ {کھولو...: عبرانی۔ دیکھنے والوں کی جگہ}\n27۔ کیونکہ وہ اس سے منہ موڑ گئے، اور اس کے کسی بھی راستے پر غور نہیں کیا: {وہ: عبرانی۔ اس کے پیچھے}\n28۔ تاکہ وہ غریبوں کی پکار اس کے پاس لے آئے، اور وہ مظلوموں کی پکار سنے۔\n29۔ جب وہ خاموشی دیتا ہے، تو پھر کون مسئلہ پیدا کر سکتا ہے؟ اور جب وہ اپنا چہرہ چھپاتا ہے، تو پھر کون اسے دیکھ سکتا ہے؟ چاہے {یہ کیا جائے} کسی قوم کے خلاف، یا صرف کسی انسان کے خلاف:\n30۔ کہ منافق حکومت نہ کرے، ورنہ لوگ پھنس جائیں گے۔\n31. یقینا خدا سے یہ کہنا مناسب ہے کہ میں نے {سزا} برداشت کی ہے، میں {مزید زیادہ} ناراض نہیں کروں گا:\n32. {جو میں دیکھتا ہوں} تو مجھے نہیں سکھاتا: اگر میں نے بدکاری کی ہے تو میں مزید کچھ نہیں کروں گا۔\n33. {کیا یہ تمہارے ذہن کے مطابق ہونا چاہیے؟' وہ اس کا بدلہ دے گا، چاہے تم انکار کرو یا تم چاہو؛ اور میں نہیں: اس لیے جو تم جانتے ہو وہ کہو۔ {مطابق...: عبرانی تمہارے ساتھ سے؟}\n34۔ سمجھدار لوگ مجھے بتائیں، اور ایک دانا آدمی میری بات سنائے۔ {of...: عبرانی۔ دل کی}\n35۔ ایوب نے بغیر علم کے بات کی، اور اس کے الفاظ بغیر حکمت کے تھے۔\n36۔ میری خواہش یہ ہے کہ ایوب کو آخر تک آزمائش دی جائے کیونکہ اس نے برے لوگوں کے لیے جوابات دیے ہیں۔ {میرا...: یا، میرے والد، ایوب کو آزمایا جائے}\n37۔ کیونکہ وہ اپنے گناہ میں بغاوت بھی شامل کرتا ہے، ہمارے درمیان تالیاں بجاتا ہے، اور خدا کے خلاف اپنے الفاظ کو بڑھا دیتا ہے۔","1۔ ایلیہو نے مزید کہا اور کہا،\n2. کیا تم سمجھتے ہو کہ یہ درست ہے، {کہ} کہ تم نے کہا، میری راستبازی خدا سے زیادہ ہے؟\n3۔ کیونکہ تم نے کہا، اس سے تمہارے کیا فائدے ہوں گے؟ {اور}، مجھے کیا فائدہ ہوگا، {اگر میں اپنے گناہ سے پاک ہو جاؤں}؟ {اگر...: یا، اس سے میرے گناہ سے زیادہ}\n4۔ میں تمہیں اور تمہارے ساتھیوں کا جواب دوں گا۔ {جواب...: عبرانی۔ اپنے الفاظ واپس لوٹیں}\n5. آسمان کی طرف دیکھو، اور دیکھو؛ اور دیکھو وہ بادل {جو} تم سے اونچے ہیں۔\n6۔ اگر تم گناہ کرتے ہو، تو اس کے خلاف کیا کرتے ہو؟ یا اگر آپ کی گناہوں میں اضافہ ہو جائے، تو آپ اس کے ساتھ کیا کرتے ہیں؟\n7۔ اگر تم نیک ہو، تو تم اسے کیا دیتے ہو؟ یا وہ تمہارے ہاتھ سے کیا حاصل کرتا ہے؟\n8. تیری برائی {ہو سکتی ہے} انسان کو تکلیف دے جیسا کہ تم ہو؛ اور تیری راستبازی انسان کے بیٹے کو فائدہ دے سکتی ہے۔\n9۔ ظلم و ستم کی کثرت کی وجہ سے وہ {مظلوموں} کو رونے پر مجبور کرتے ہیں: وہ طاقتور کے بازو کی وجہ سے پکار رہے ہیں۔\n10۔ لیکن کوئی نہیں کہتا، کہاں خدا میرا خالق ہے، جو رات کو گانے دیتا ہے؛\n11۔ ہمیں زمین کے جانوروں سے زیادہ کون سکھاتا ہے، اور ہمیں آسمان کے پرندوں سے زیادہ دانا بناتا ہے؟\n12۔ وہاں وہ روتے ہیں، لیکن کوئی جواب نہیں دیتا، برے لوگوں کے غرور کی وجہ سے۔\n13. یقینا خدا بے وقوفی کو نہیں سنے گا، نہ ہی قادر مطلق اسے سمجھے گا۔\n14۔ اگرچہ تم کہتے ہو کہ تم اسے نہیں دیکھو گے، {لیکن} فیصلہ {ہے} اس کے سامنے ہے؛ لہٰذا اس پر بھروسہ کرو۔\n15. لیکن اب، چونکہ {یہ ہے} نہیں کہ {تو}، وہ اپنے غصے میں آ گیا ہے؛ پھر بھی وہ اسے زیادہ شدت سے نہیں جانتا: {اس کے پاس ہے: یعنی خدا کے پاس ہے} {وہ جانتا ہے: یعنی، ایوب جانتا ہے}\n16۔ اسی لیے ایوب نے بے سود منہ کھولا؛ وہ بغیر علم کے الفاظ کو بڑھاتا ہے۔","1۔ ایلیہو نے بھی آگے بڑھتے ہوئے کہا،\n2. مجھے تھوڑا معاف کرو، اور میں تمہیں دکھاؤں گا کہ میں نے ابھی تک خدا کی طرف سے بات نہیں کی۔ {میرے پاس ہے...: عبرانی۔ ابھی بھی خدا کے لیے الفاظ موجود ہیں}\n3۔ میں اپنی معلومات دور سے حاصل کروں گا، اور راستبازی کو اپنے خالق کے نام دوں گا۔\n4۔ کیونکہ واقعی میرے الفاظ جھوٹے نہیں ہوں گے: جو علم میں کامل ہے وہ تمہارے ساتھ ہے۔\n5۔ دیکھو، خدا {ہے} طاقتور ہے، اور {کسی سے} کو حقیر نہیں کرتا: وہ طاقت اور حکمت میں طاقتور ہے۔ {حکمت: عبرانی۔ دل}\n6۔ وہ بدکاروں کی زندگی کا تحفظ نہیں کرتا، بلکہ غریبوں کو حق دیتا ہے۔ {غریب: یا، متاثر}\n7۔ وہ اپنی نظریں راستبازوں سے نہیں ہٹاتا، بلکہ بادشاہوں کے تخت پر ہیں؛ ہاں، وہ انہیں ہمیشہ کے لیے قائم کرتا ہے، اور وہ بلند ہیں۔\n8۔ اور اگر {وہ} زنجیروں میں بندھے جائیں، {اور} مصیبت کی رسیوں میں بندھے جائیں؛\n9۔ پھر وہ انہیں ان کے کام اور ان گناہوں کو دکھاتا ہے جو انہوں نے عبور کی ہیں۔\n10۔ وہ ان کے کان کو نظم و ضبط کے لیے بھی کھولتا ہے، اور انہیں گناہوں سے واپس آنے کا حکم دیتا ہے۔\n11۔ اگر وہ اس کی اطاعت کریں اور اس کی خدمت کریں، تو وہ اپنی زندگی خوشحالی میں گزاریں گے اور اپنی زندگی عشوتوں میں۔\n12. لیکن اگر وہ اطاعت نہ کریں تو تلوار سے ہلاک ہو جائیں گے، اور بے خبری مر جائیں گے۔ {perish: عبرانی۔ انتقال کر دیں}\n13۔ لیکن دل کے منافق غصے کو ڈھیر کرتے ہیں: جب وہ انہیں باندھتا ہے تو وہ نہیں روتے۔\n14۔ وہ جوانی میں مر جاتے ہیں، اور ان کی زندگی ناپاک میں شامل ہے۔ {وہ...: عبرانی ان کی روح کی مرت} {ناپاک: یا، ہم جنس پرست}\n15۔ وہ اپنے مصیبت میں غریبوں کو نجات دیتا ہے، اور ان کے کان ظلم میں کھولتا ہے۔ {غریب: یا، متاثر}\n16۔ اسی طرح وہ تمہیں اس تنگی سے نکال کر ایک چوڑے مقام میں لے جاتا، جہاں {تنگی نہیں}؛ اور جو چیز تمہاری میز پر رکھی جانی چاہیے وہ موٹاپے سے بھرپور ہو۔ {وہ...: عببرانی۔ تمہاری میز کے باقی لوگ}\n17. لیکن تو نے بدکاروں کا فیصلہ پورا کر دیا ہے: فیصلہ اور انصاف تم پر قابض ہو جاتے ہیں۔ {لے لو...: یا، تمہیں سنبھالنا چاہیے}\n18۔ کیونکہ {غصہ} ہے، {خبردار} کہ وہ تمہیں {اپنی} وار سے لے جائے گا: تب بھی کوئی بڑا تاوان تمہیں بچا نہیں سکتا۔ {ڈیلیور...: ہیب۔ اپنی طرف مڑ جاؤ}\n19۔ کیا وہ تمہاری دولت کی قدر کرے گا؟ {نہیں}، نہ سونا، نہ طاقت کی تمام قوتیں۔\n20۔ رات کی خواہش نہ کرو، جب لوگ اپنی جگہ سے کٹ جاتے ہیں۔\n21۔ خبردار رہو، بدکاری کو مت سمجھو: کیونکہ یہ تم نے مصیبت کے بجائے چنا ہے۔\n22. دیکھو، خدا اپنی طاقت سے بلند کرتا ہے: کون اس کی طرح تعلیم دیتا ہے؟\n23۔ کس نے اسے اس کے راستے پر حکم دیا؟ یا کون کہہ سکتا ہے، تو نے بدکاری کی ہے؟\n24۔ یاد رکھو کہ تم اس کے کام کو بڑھا چڑھا کر بڑھاتے ہو، جسے لوگ دیکھتے ہیں۔\n25۔ ہر انسان اسے دیکھ سکتا ہے؛ انسان اسے دور سے دیکھ سکتا ہے۔\n26۔ دیکھو، خدا {عظیم} ہے، اور ہم {اسے} کو نہیں جانتے، نہ ہی اس کے سالوں کی تعداد تلاش کی جا سکتی ہے۔\n27۔ کیونکہ وہ پانی کے قطرے چھوٹے کرتا ہے: وہ اس کے بخارات کے مطابق بارش برستی ہیں:\n28۔ جو بادل گرتے ہیں {اور} انسان پر فراوانی سے پھیلتے ہیں۔\n29. کیا {کوئی} بادلوں کے پھیلاؤ کو سمجھ سکتا ہے، {یا} اپنے خیمے کی آواز کو؟\n30۔ دیکھو، وہ اپنی روشنی اس پر پھیلاتا ہے، اور سمندر کی تہہ کو ڈھانپ لیتا ہے۔ {نیچے: عبرانی۔ جڑیں}\n31۔ کیونکہ وہ لوگوں کا فیصلہ انہی سے کرتا ہے؛ وہ گوشت کو وافر مقدار میں دیتا ہے۔\n32۔ وہ روشنی کو بادلوں سے ڈھانپتا ہے؛ اور حکم دیتا ہے کہ {اس بادل} کے ذریعے نہ چمکے، جو درمیان میں آتا ہے۔\n33۔ اس کی آواز اس کے بارے میں ظاہر کرتی ہے، اور مویشی بھی بخارات کے بارے میں ظاہر کرتے ہیں۔ {بخارات: عبرانی۔ جو اوپر جاتا ہے}","1۔ اس پر میرا دل بھی کانپ اٹھتا ہے، اور وہ اپنی جگہ سے ہٹا دیا جاتا ہے۔\n2. اس کی آواز کی آواز کو غور سے سنیں، اور وہ آواز جو اس کے منہ سے نکلتی ہے۔ {سنیں...: عبوری۔ سماعت میں سنیں}\n3۔ وہ اسے پورے آسمان کے نیچے اور اپنی بجلی کو زمین کے کناروں تک بھیجتا ہے۔ {بجلی: عبرانی۔ روشنی} {اختتام: عبرانی۔ ونگز}\n4۔ اس کے بعد ایک آواز گرجتی ہے: وہ اپنی عظمت کی آواز سے گرجتا ہے؛ اور جب اس کی آواز سنی جائے تو وہ انہیں روک نہیں پائے گا۔\n5۔ خدا اپنی آواز سے شاندار گرجتا ہے؛ وہ عظیم کام کرتا ہے، جنہیں ہم سمجھ نہیں سکتے۔\n6۔ کیونکہ وہ برف سے کہتا ہے، زمین پر ہو جاؤ؛ اسی طرح چھوٹی بارش اور اس کی طاقت کی بڑی بارش بھی۔ {اسی طرح...: عبرانی۔ اور بارش کی بارش کو، اور اس کی طاقت کی بارش کے لیے}\n7۔ وہ ہر انسان کے ہاتھ کو مہر بند کر دیتا ہے؛ تاکہ تمام لوگ اس کے کام کو جان سکیں۔\n8۔ پھر جانور ٹھکانوں میں جاتے ہیں اور اپنی جگہوں پر رہتے ہیں۔\n9۔ جنوب سے طوفان آتا ہے: اور شمال سے سردی۔ {جنوب: عبوری۔ چیمبر} {شمال: عبرانی۔ بکھرتی ہوئی ہوائیں\n10۔ خدا کی سانس سے برف جم جاتی ہے: اور پانی کی چوڑائی محدود ہو جاتی ہے۔\n11۔ پانی دے کر وہ گھنے بادل کو بھی تھکا دیتا ہے: وہ اپنا روشن بادل بکھیر دیتا ہے: {اس کا...: عبرانی۔ اس کی روشنی کا بادل}\n12۔ اور اس کی نصیحتوں سے یہ الٹ جاتا ہے: تاکہ وہ زمین پر جو کچھ بھی وہ حکم دے، وہ کر سکیں۔\n13۔ وہ اسے لانے دیتا ہے، چاہے اصلاح کے لیے، اپنی زمین کے لیے، یا رحم کے لیے۔ {تصحیح: عبرانی ایک چھڑی}\n14. اے ایوب، یہ سنو: رک جاؤ، اور خدا کے حیرت انگیز کاموں پر غور کرو۔\n15۔ کیا تم جانتے ہو کہ خدا نے کب انہیں ختم کیا اور اپنے بادل کی روشنی کو روشن کیا؟\n16۔ کیا تم بادلوں کے توازن اور اس کے حیرت انگیز کاموں کو جانتے ہو جو علم میں کامل ہے؟\n17. تمہارے کپڑے کیسے گرم ہیں، جب وہ جنوب کی طرف زمین کو خاموش کرتا ہے {ہوا}؟\n18۔ کیا تم نے اس کے ساتھ آسمان پھیلایا ہے، جو مضبوط ہے، {اور} پگھلے ہوئے آئینے کی طرح؟\n19۔ ہمیں سکھاؤ کہ ہم اس سے کیا کہیں؛ {کیونکہ} ہم اپنی گفتگو کو تاریکی کی وجہ سے ترتیب نہیں دے سکتے۔\n20. کیا اسے بتایا جائے کہ میں بولتا ہوں؟ اگر کوئی شخص بولے گا، تو یقینا نگل جائے گا۔\n21. اور اب {انسان} وہ روشن روشنی نہیں دیکھتے جو بادلوں میں ہے: بلکہ ہوا گزرتی ہے اور انہیں صاف کرتی ہے۔\n22۔ شمال سے خوشگوار موسم آتا ہے: خدا کے ساتھ خوفناک عظمت ہے۔ {منصف...: عبرانی گولڈ}\n23۔ {قادر مطلق کو چھوتے ہوئے، ہم اسے نہیں ڈھونڈ سکتے: {وہ} طاقتور، فیصلے اور انصاف میں ماہر ہے: وہ تکلیف نہیں دے گا۔\n24۔ اس لیے لوگ اس سے ڈرتے ہیں: وہ کسی بھی عقلمند کی عزت نہیں کرتا۔","1۔ پھر خداوند نے طوفان سے ایوب کو جواب دیا اور کہا،\n2. یہ کون ہے جو بغیر علم کے الفاظ سے مشورے کو تاریک کرتا ہے؟\n3. اب اپنی کمر کو مرد کی طرح باندھو؛ کیونکہ میں تم سے مطالبہ کروں گا، اور تمہیں جواب دوں گا۔ {جواب...: عبرانی۔ مجھے بتاؤ}\n4. جب میں نے زمین کی بنیادیں رکھی تھیں تو کہاں تھے؟ اگر تم سمجھتے ہو تو اعلان کرو۔ {ہسٹ...: عببرانی۔ سب سے زیادہ سمجھ بوجھ ہے}\n5۔ اگر تم جانتے ہو تو اس کے پیمائش کس نے رکھی ہے؟ یا کس نے اس پر لائن کھینچی ہے؟\n6۔ اس کی بنیادیں کس بنیاد پر مضبوط ہیں؟ یا اس کی بنیاد کس نے رکھی؛ {بنیادیں: عبرانی۔ ساکٹس} {بند: عبرانی۔ ڈوبنے کے لیے بنایا گیا؟}\n7۔ جب صبح کے ستارے ایک ساتھ گاتے، اور خدا کے تمام بیٹے خوشی سے پکارتے؟\n8. یا {کون} سمندر کو دروازوں سے بند کر دے، جب وہ ٹوٹ جائے، {گویا} وہ رحم سے نکلا ہو؟\n9۔ جب میں نے بادل کو اس کا لباس بنایا، اور گہری تاریکی کو اس کے لیے لپیٹنے والی پٹی بنایا،\n10۔ اور اس کے لیے میری مقرر کردہ {جگہ} کو توڑ دو، اور سلاخیں اور دروازے لگا دو، {بریک...: یا، میرا حکم اس پر قائم کرو}\n11۔ اور کہا، تم یہاں تک آؤ گے، لیکن آگے نہیں: اور یہاں تمہاری فخر کی لہریں رکی جائیں گی؟ {تمہاری...: عببری۔ تیری لہروں کا غرور}\n12۔ کیا تم نے اپنے دنوں سے صبح کا حکم دیا ہے؛ {اور} نے ڈے اسپرنگ کو اپنی جگہ بتا دی؛\n13۔ تاکہ یہ زمین کے کناروں پر قبضہ کر لے، تاکہ بدکاروں کو اس سے نکالا جائے؟ {اختتام: عبرانی۔ ونگز}\n14۔ اسے مٹی کی طرح موڑ دیا جاتا ہے {مہر تک}؛ اور وہ ایک لباس کی طرح کھڑے ہیں۔\n15۔ اور بدکاروں سے ان کی روشنی چھین لی جاتی ہے، اور اونچی بازو ٹوٹ جاتی ہے۔\n16۔ کیا تم سمندر کے چشموں میں داخل ہوئے ہو؟ یا تم نے گہرائی کی تلاش میں چلنا شروع کیا؟\n17۔ کیا موت کے دروازے تمہارے لیے کھل گئے ہیں؟ یا کیا تم نے موت کے سائے کے دروازے دیکھے ہیں؟\n18۔ کیا تم نے زمین کی وسعت دیکھی؟ اگر تم سب کچھ جانتے ہو تو اعلان کرو۔\n19. کہاں {ہے} وہ راستہ {کہ} روشنی رہتا ہے؟ اور {جہاں تک} تاریکی کا تعلق ہے، جہاں {ہے} اس کی جگہ،\n20۔ کہ تم اسے اس کی حد تک لے جاؤ، اور اس کے گھر تک جانے کے راستے جانو؟ {حد تک: یا، ایٹ، وغیرہ}\n21۔ کیا تم جانتی ہو {اسے}، کیونکہ تم اس وقت پیدا ہوئی؟ یا {کیونکہ} تمہارے دنوں کی تعداد {ہے} عظیم؟\n22۔ کیا تم برف کے خزانے میں داخل ہوئے ہو؟ یا تم نے اولے کے خزانے دیکھے ہیں،\n23. جو میں نے مصیبت کے وقت، جنگ اور جنگ کے دن کے لیے محفوظ رکھا ہے؟\n24۔ روشنی کس طرح تقسیم ہوتی ہے، {جو} مشرقی ہوا کو زمین پر بکھیر دیتی ہے؟\n25۔ جس نے پانی کے بہنے کے لیے پانی کا راستہ تقسیم کیا، یا بجلی گرج کے لیے راستہ بنایا؛\n26۔ زمین پر بارش برسا، {جہاں} کوئی انسان {ہے} اس صحرا میں، جہاں {کوئی انسان} نہیں ہے؛\n27۔ ویران اور برباد {زمین} کو مطمئن کرنا؛ اور اس نرم جڑی بوٹی کی کلی کو اگانا؟\n28۔ کیا بارش کا باپ ہے؟ یا کس نے شبنم کے قطرے پیدا کیے ہیں؟\n29۔ کس کے رحم سے برف نکلی؟ اور جنت کی پرانا سردی، جس نے اسے جنس قرار دیا؟\n30۔ پانی ایک پتھر کی طرح چھپا دیا جاتا ہے، اور گہرے پانی کا چہرہ منجمد ہو جاتا ہے۔ {ہے...: عبرانی۔ لیا گیا ہے}\n31۔ کیا تم پلیئڈیز کے میٹھی اثرات کو باندھ سکتے ہو، یا اوریون کی پٹیاں کھو سکتے ہو؟ {پلیئڈیز: یا، سات ستارے: عبرانی۔ سیماہ} {اورین: عبرانی۔ سیسل؟}\n32۔ کیا تم مزاروت کو اس کے موسم میں لا سکتے ہو؟ یا کیا تم آرکٹورس کو اس کے بیٹوں کے ساتھ رہنمائی کر سکتے ہو؟ {مازاروت: یا، بارہ نشانات} {گائیڈ: عبرانی۔ رہنمائی کریں}\n33۔ کیا تم آسمان کے احکامات جانتے ہو؟ کیا تم زمین پر اس کی حکمرانی قائم کر سکتے ہو؟\n34۔ کیا تم اپنی آواز بادلوں کی طرف بلند کر سکتے ہو، تاکہ پانی کی فراوانی تمہیں ڈھانپ لے؟\n35۔ کیا تم بجلی بھیج سکتے ہو، تاکہ وہ جا سکیں، اور تم سے کہہ سکیں، ہم یہاں ہیں؟ {یہاں...: عبرانی۔ ہمیں دیکھو؟}\n36۔ کس نے اندرونی حصوں میں حکمت ڈالی ہے؟ یا کس نے دل کو سمجھ دی ہے؟\n37۔ حکمت میں بادلوں کو کون گن سکتا ہے؟ یا جو جنت کی بوتلیں روک سکتا ہے، {رکیے: عبرانی۔ لیٹنے کی وجہ\n38۔ جب مٹی سخت ہو جائے اور گچھے تیزی سے ایک دوسرے سے جڑ جائیں؟ {بڑھتا ہے...: یا، کیچڑ میں بدل جاتا ہے: عبرانی۔ ڈالا جاتا ہے}\n39۔ کیا تم شیر کے لیے شکار کرو گے؟ یا نوجوان شیروں کی بھوک کو پورا کریں، {بھوک: عبرانی۔ زندگی}\n40. جب وہ اپنے ٹھکانوں میں بیٹھتے ہیں، {اور} خفیہ جگہ میں انتظار میں رہتے ہیں؟\n41۔ کون کوا کے لیے اس کا کھانا فراہم کرتا ہے؟ جب اس کے بچے خدا سے پکارتے ہیں، تو گوشت کی کمی کی وجہ سے بھٹک جاتے ہیں۔","1۔ کیا تم جانتے ہو وہ وقت جب چٹان کے جنگلی بکریاں جنم لاتی ہیں؟ {یا} کیا تم دیکھ سکتے ہو جب مچھلیاں بچھڑی ہوتی ہیں؟\n2. کیا آپ ان مہینوں کی گنتی کر سکتے ہیں جو وہ پورا کرتے ہیں؟ یا تم جانتے ہو کہ وہ کب پیدا ہوتے ہیں؟\n3۔ وہ خود کو جھکاتے ہیں، اپنے بچوں کو جنم دیتے ہیں، اپنے غم کو باہر نکالتے ہیں۔\n4۔ ان کے بچے پسند کیے جاتے ہیں، وہ مکئی کے ساتھ بڑے ہوتے ہیں؛ وہ آگے بڑھتے ہیں، اور ان کے پاس واپس نہیں جاتے۔\n5. کس نے اس وحشی کو آزاد بھیجا ہے؟ یا کس نے جنگلی گدھے کی پٹیاں کھول دی ہیں؟\n6۔ جس کے گھر کو میں نے بیابان بنایا ہے، اور بنجر زمین اس کے گھر ہیں۔ {بنجر ...: عبرانی نمک کی جگہیں}\n7۔ وہ شہر کی ہجوم کو حقیر سمجھتا ہے، نہ ہی ڈرائیور کی پکار کو سنتا ہے۔ {ڈرائیور کے بارے میں: عبرانی۔ ایگزیکٹر}\n8. پہاڑوں کی پہاڑی اس کی چراگاہ ہے، اور وہ ہر سبز چیز کی تلاش میں ہے۔\n9. کیا یونیکورن تمہاری خدمت کرنے کو تیار ہوگا، یا تمہارے پالنے کے پاس رہے گا؟\n10. کیا تم یونیکورن کو اس کی پٹی کے ساتھ کھال میں باندھ سکتے ہو؟ یا وہ تمہارے پیچھے وادیوں میں تباہی مچائے گا؟\n11. کیا تم اس پر بھروسہ کرو گے، کیونکہ اس کی طاقت {عظیم} ہے؟ یا تم اپنی محنت اس کے سپرد کرو گے؟\n12. کیا تم اس پر یقین کرو گے کہ وہ تمہاری نسل کو گھر لے آئے گا، اور اسے تمہارے کھیت میں جمع کرے گا؟\n13۔ موروں کو اچھے پر دیے؟ یا شترمرغ کے لیے پر اور پر؟ {پر اور...: یا، اسٹورک اور شتر مرغ کے پر}\n14۔ جو اپنے انڈے زمین میں چھوڑ دیتی ہے، اور انہیں مٹی میں گرم کرتی ہے،\n15۔ اور بھول جاتا ہے کہ پاؤں انہیں کچل دے، یا جنگلی جانور انہیں توڑ دے۔\n16. وہ اپنے بچوں کے خلاف سخت ہو جاتی ہے، جیسے {وہ} اس کے نہیں ہیں: اس کی محنت بے خوف اور بے کار جاتی ہے؛\n17. کیونکہ خدا نے اسے حکمت سے محروم کیا ہے، اس نے اسے سمجھ نہیں دی۔\n18۔ جب وہ خود کو بلند کرتی ہے، تو گھوڑے اور اس کے سوار کو حقارت سے دیکھتی ہے۔\n19۔ کیا تم نے گھوڑے کو طاقت دی؟ کیا تم نے اس کی گردن کو گرج سے ڈھانپ دیا ہے؟\n20۔ کیا تم اسے ٹڈی کی طرح ڈرا سکتے ہو؟ اس کی نتھنوں کی شان {خوفناک} ہے۔ {خوفناک: عبوری۔ دہشت}\n21۔ وہ وادی میں چلتا ہے، اور اپنی طاقت پر خوش ہوتا ہے: وہ مسلح مردوں سے ملنے جاتا ہے۔ {وہ ہاتھ بڑھاتا ہے: یا، اس کے پاؤں گڑھتے ہیں} {آرمیڈ...: عبرانی۔ زرہ}\n22۔ وہ خوف کا مذاق اڑاتا ہے، اور خوفزدہ نہیں ہوتا؛ نہ ہی وہ تلوار سے پیچھے ہٹتا ہے۔\n23۔ ترکش اس کے خلاف بجتا ہے، چمکتا ہوا نیزہ اور ڈھال۔\n24۔ وہ زمین کو شدت اور غصے سے نگلتا ہے: نہ وہ یقین کرتا ہے کہ یہ بگل کی آواز ہے۔\n25۔ وہ بگل کے درمیان کہتا ہے، ہا، ہا؛ اور وہ دور سے لڑائی، کپتانوں کی گرج، اور چیخ و پکار کی خوشبو سونگھتا ہے۔\n26. کیا باز تیری حکمت سے اڑتا ہے، {اور} اپنے پر جنوب کی طرف پھیلاتا ہے؟\n27۔ کیا عقاب تمہارے حکم پر سوار ہوتا ہے اور اونچے پر اپنا گھونسلہ بناتا ہے؟ {پر...: عبرانی۔ تمہارے منہ سے}\n28۔ وہ چٹان پر، چٹان کی چٹان پر، اور مضبوط جگہ پر رہتی ہے۔\n29۔ وہاں سے وہ شکار تلاش کرتی ہے، {اور} اس کی آنکھیں دور تک دیکھتی ہیں۔\n30۔ اس کے بچے بھی خون چوستے ہیں: اور جہاں مارے گئے ہیں، وہاں وہ ہے۔","1۔ مزید یہ کہ خداوند نے ایوب کو جواب دیا اور کہا،\n2. کیا جو قادر مطلق سے بحث کرتا ہے وہ اسے ہدایت دے؟ جو خدا کو ملامت کرتا ہے، وہ اس کا جواب دے۔\n3۔ پھر ایوب نے خداوند کا جواب دیا اور کہا،\n4. دیکھو، میں گھٹیا ہوں؛ میں تمہیں کیا جواب دوں؟ میں اپنا ہاتھ اپنے منہ پر رکھوں گا۔\n5. ایک بار میں نے بات کی؛ لیکن میں جواب نہیں دوں گا: ہاں، دو بار؛ لیکن میں آگے نہیں بڑھوں گا۔\n6۔ پھر اس نے طوفان سے ایوب کو جواب دیا اور کہا،\n7۔ اب اپنی کمر کو ایک مرد کی طرح باندھو: میں تم سے مطالبہ کروں گا، اور تمہیں اپنے سامنے اعلان کروں گا۔\n8۔ کیا تم بھی میرا فیصلہ منسوخ کرو گے؟ کیا تم مجھے سزا دو گے، تاکہ تم نیک بن سکو؟\n9۔ کیا تمہارے پاس خدا جیسا بازو ہے؟ یا تم اس جیسی آواز کے ساتھ گرج سکتے ہو؟\n10. اب خود کو {عظمت} اور عظمت سے سجا دو؛ اور اپنے آپ کو شان و شوکت اور خوبصورتی سے سنوار دو۔\n11۔ اپنے غصے کا غصہ باہر نکالو: اور ہر اس شخص کو دیکھو جو مغرور ہے، اور اسے ذلیل کر دو۔\n12۔ ہر ایک کو دیکھو، {اور} اسے نیچا دکھاو؛ اور ان کی جگہ بدکاروں کو روند ڈالیں۔\n13. انہیں ایک ساتھ دھول میں چھپا دیں؛ {اور} ان کے چہرے خفیہ طور پر باندھتے ہیں۔\n14۔ پھر میں بھی تمہیں اعتراف کروں گا کہ تمہارا اپنا دایاں ہاتھ تمہیں بچا سکتا ہے۔\n15۔ اب دیکھو، وہ دیو ہیکل جو میں نے تمہارے ساتھ بنایا؛ وہ بیل کی طرح گھاس کھاتا ہے۔ {بیہیموتھ: شاید کسی قسم کا معدوم جانور}\n16. اب دیکھو، اس کی طاقت {ہے} اس کی کمر میں، اور اس کی طاقت {ہے} اس کے پیٹ کے ناف میں۔\n17۔ وہ اپنی دم کو دیودار کی طرح حرکت دیتا ہے: اس کے پتھروں کی رگیں آپس میں لپٹی ہوئی ہیں۔ {وہ...: یا، وہ بیٹھ جاتا ہے}\n18۔ اس کی ہڈیاں پیتل کے مضبوط ٹکڑوں کی طرح ہیں؛ اس کی ہڈیاں لوہے کی سلاخوں کی طرح ہیں۔\n19۔ وہ خدا کے راستوں کا سربراہ ہے: جس نے اسے بنایا ہے، وہ اپنی تلوار اس کے قریب لے جا سکتا ہے۔\n20. یقینا پہاڑ اسے کھانا دیتے ہیں، جہاں میدان کے تمام جانور کھیلتے ہیں۔\n21۔ وہ سایہ دار درختوں کے نیچے، سرکنڈے اور فین کے چھپے حصے میں لیٹا ہے۔\n22۔ سایہ دار درخت اسے اپنے سائے سے ڈھانپ لیتے ہیں؛ ندی کے بید کے درخت اسے گھیرے ہوئے ہیں۔\n23۔ دیکھو، وہ دریا میں پانی پیتا ہے، {اور} جلدی نہیں کرتا: وہ یقین رکھتا ہے کہ وہ اردن کو اپنے منہ میں کھینچ سکتا ہے۔ {وہ پیتا ہے: عبرانی۔ وہ ظلم کرتا ہے}\n24۔ وہ اسے اپنی آنکھوں سے لیتا ہے: {اس کی} ناک جالوں کو چیر دیتی ہے۔ {وہ...: یا، کیا کوئی اسے اپنی نظر میں لے گا، یا جن سے اس کی ناک چھائے گا؟}","1. کیا تم ہک سے لیویاتھن نکال سکتے ہو؟ یا اس کی زبان جس میں رسی {جسے تم نیچے چھوڑتے ہو}؟ {لیویاتھن: شاید کسی قسم کا معدوم جانور} {جو کہ...: عبرانی تم کون سا سب سے زیادہ پیتے ہو؟}\n2. کیا تم اس کی ناک میں ہک لگا سکتے ہو؟ یا اپنے جبڑے کو کانٹے سے نکال دے؟\n3. کیا وہ تم سے بہت سی دعائیں کرے گا؟ کیا وہ تم سے نرم الفاظ کہے گا؟\n4. کیا وہ آپ سے عہد کرے گا؟ کیا تم اسے ہمیشہ کے لیے نوکر سمجھو گے؟\n5. کیا تم اس کے ساتھ پرندے کی طرح کھیلو گے؟ یا تم اسے اپنی لڑکیوں کے لیے باندھنا چاہتے ہو؟\n6. کیا صحابہ اس کا جشن منائیں گے؟ کیا وہ اسے تاجروں میں تقسیم کر دیں؟\n7۔ کیا تم اس کی جلد کو کانٹے دار لوہے سے بھر سکتے ہو؟ یا اس کے سر پر مچھلی کے نیزے؟\n8۔ اپنا ہاتھ اس پر رکھو، جنگ کو یاد رکھو، اور کچھ نہ کرو۔\n9۔ دیکھو، اس کی امید رائیگاں جاتی ہے: کیا {ایک} اسے دیکھ کر بھی مایوس نہیں ہوگا؟\n10۔ کوئی بھی اتنا شدید نہیں کہ اسے بھڑکانے کی جرات کرے: پھر کون میرے سامنے کھڑا ہو سکتا ہے؟\n11۔ کس نے مجھے روکا کہ میں {اس کا بدلہ چکاوں؟ جو کچھ بھی ہے} پورے آسمان کے نیچے میرا ہے۔\n12۔ میں اس کے اعضا، طاقت یا خوبصورت تناسب کو نہیں چھپاؤں گا۔\n13۔ کون اس کے لباس کا چہرہ دریافت کر سکتا ہے؟ {یا}کون اس کے پاس آ سکتا ہے، اس کے ڈبل بریڈل کے ساتھ؟ {ساتھ: یا، اندر}\n14۔ کون اس کے چہرے کے دروازے کھول سکتا ہے؟ اس کے دانت بہت خراب ہیں۔\n15۔ {اس کی} ترازو {اس کی} غرور ہیں، ایک ساتھ چپ رہو {جیسے کہ ایک بند مہر کے ساتھ}۔ {اسکیلز: ہیب۔ مضبوط ڈھالوں کے ٹکڑے}\n16۔ ایک دوسرے کے اتنے قریب ہے کہ ان کے درمیان کوئی ہوا نہیں آ سکتی۔\n17۔ وہ ایک دوسرے سے جڑے ہوتے ہیں، ایک دوسرے سے جڑے ہوتے ہیں، تاکہ انہیں جدا نہ کیا جا سکے۔\n18۔ اس کی نیسز سے روشنی چمکتی ہے، اور اس کی آنکھیں صبح کی پلکوں کی طرح ہیں۔\n19۔ اس کے منہ سے جلتے ہوئے چراغ نکلتے ہیں، {اور} آگ کی چنگاریاں نکلتی ہیں۔\n20۔ اس کی ناک سے دھواں نکلتا ہے، جیسے ابلتے ہوئے برتن یا دیگ کا۔\n21۔ اس کی سانس کوئلے جلا دیتی ہے، اور اس کے منہ سے شعلہ نکلتا ہے۔\n22۔ اس کی گردن میں طاقت باقی ہے، اور غم اس کے سامنے خوشی میں بدل جاتا ہے۔ {خوشی میں بدل جاتا ہے: عبرانی۔ خوش رہو}\n23۔ اس کے گوشت کے ذرات آپس میں جڑے ہوئے ہیں: وہ خود میں مضبوط ہیں؛ انہیں منتقل نہیں کیا جا سکتا۔ {فلیکس: عبوری۔ فلنگز}\n24۔ اس کا دل پتھر کی طرح مضبوط ہے؛ ہاں، اتنی سخت جتنی کہ نیدر کا کوئی ٹکڑا {مل اسٹون}۔\n25۔ جب وہ خود کو اٹھاتا ہے تو طاقتور ڈرتے ہیں: ٹوٹنے کی وجہ سے وہ خود کو پاک کر لیتے ہیں۔\n26۔ جس کے پاس اس کی تلوار ہے، وہ نیزہ، تیر یا ہیبرجون کو نہیں پکڑ سکتی۔ {ہیبرجون: یا، بریسٹ پلیٹ}\n27۔ وہ لوہے کو بھوسہ سمجھتا ہے، {اور} پیتل کو سڑی ہوئی لکڑی کی طرح۔\n28۔ تیر اسے بھاگنے نہیں دے سکتا: سلنگ اسٹونز اس کے ساتھ داڑھی میں بدل جاتے ہیں۔\n29۔ ڈارٹس کو داڑھی شمار کیا جاتا ہے: وہ نیزے کے ہلنے پر ہنستا ہے۔\n30۔ تیز پتھر اس کے نیچے ہیں: وہ کیچڑ پر نوکیلے اور نوکیلے حصے پھیلاتا ہے۔ {تیز پتھر: عبرانی۔ نوکیلے مٹی کے ٹکڑے}\n31۔ وہ گہرائی کو دیگ کی طرح ابالتا ہے: وہ سمندر کو مرہم کے برتن کی طرح بناتا ہے۔\n32۔ وہ اپنے پیچھے چمکنے کا راستہ بناتا ہے؛ {ایک} گہرا {ہونے والا} کو بوڑھا سمجھتا ہے۔\n33۔ زمین پر اس جیسا کوئی نہیں، جو بے خوف بنایا گیا ہو۔ {خوف کے بغیر بنایا گیا ہے: یا، بغیر خوف کے برتاؤ کریں}\n34۔ وہ تمام اعلیٰ چیزوں کو دیکھتا ہے: وہ تمام مغرور بچوں پر بادشاہ ہے۔","1۔ پھر ایوب نے خداوند کو جواب دیا اور کہا،\n2۔ میں جانتا ہوں کہ تم ہر {کام} کر سکتے ہو، اور {کہ} تم سے کوئی سوچ نہیں چھپی جا سکتی۔ {کوئی خیال نہیں ہو سکتا...: یا، تمہارے بارے میں کوئی خیال روکا نہیں جا سکتا}\n3۔ وہ کون ہے جو بغیر علم کے مشورہ چھپاتا ہے؟ اسی لیے میں نے کہا کہ میں سمجھ نہیں سکا؛ ایسی چیزیں جو میرے لیے بہت شاندار تھیں، جو میں نہیں جانتا تھا۔\n4۔ سنو، میں تم سے التجا کرتا ہوں، اور میں بولوں گا: میں تم سے مطالبہ کروں گا، اور تمہیں اپنے سامنے اعلان کروں گا۔\n5۔ میں نے تمہارے بارے میں کان کی سماعت سے سنا ہے، لیکن اب میری آنکھ تمہیں دیکھ رہی ہے۔\n6. اسی لیے میں خود سے نفرت کرتا ہوں، اور مٹی اور راکھ میں توبہ کرتا ہوں۔\n7۔ اور ایسا ہی ہوا کہ جب خداوند نے یہ الفاظ ایوب سے کہے، تو خداوند نے الیفاز تیمانی سے کہا، میرا غضب تم پر اور تمہارے دو دوستوں پر بھڑک اٹھا ہے: کیونکہ تم نے میرے بارے میں وہ بات نہیں کی جو صحیح ہے، جیسا کہ میرے خادم ایوب نے کیا ہے۔\n8۔ تو اب سات بیل اور سات مینڈھے لے آؤ، اور میرے خادم ایوب کے پاس جاؤ، اور اپنے لیے ایک جلانے والی قربانی پیش کرو؛ اور میرا خادم ایوب تمہارے لیے دعا کرے گا: اس کے لیے میں اسے قبول کروں گا: کہیں میں تمہارے ساتھ تمہاری حماقت کے بعد معاملہ نہ کروں، کیونکہ تم نے میرے بارے میں وہ بات نہیں کی جو صحیح ہے، جیسے میرا خادم ایوب ہے۔ {وہ: عبرانی۔ اس کا چہرہ، یا، شخص}\n9۔ تو الیفاز تیمانی اور بلداد شوہیتی {اور} زوفار نامتی گئے، اور خداوند کے حکم کے مطابق عمل کیا: خداوند نے بھی ایوب کو قبول کیا۔ {ایوب: عبرانی۔ ایوب کا چہرہ}\n10۔ اور خداوند نے ایوب کی قید کو بدل دیا، جب اس نے اپنے دوستوں کے لیے دعا کی: اور خداوند نے ایوب کو پہلے سے دوگنا دیا۔ {دیا گیا...: عببرانی۔ ایوب کے لیے جو کچھ بھی تھا اس میں شامل کیا}\n11۔ پھر اس کے تمام بھائی، اس کی تمام بہنیں، اور جو اس سے پہلے اس سے واقف تھے، اس کے گھر میں اس کے ساتھ روٹی کھانے لگے، اور انہوں نے اس پر افسوس کیا، اور خداوند کی لائی ہوئی تمام برائیوں پر اسے تسلی دی: ہر آدمی نے اسے ایک پیسہ بھی دیا،  اور ہر ایک سونے کی بالی۔\n12۔ تو خداوند نے ایوب کے آخری حصے کو اس کی ابتدا سے زیادہ برکت دی: کیونکہ اس کے پاس چودہ ہزار بھیڑیں، چھ ہزار اونٹ، ایک ہزار بیل کا یوق، اور ایک ہزار گدھے تھے۔\n13۔ ان کے سات بیٹے اور تین بیٹیاں بھی تھیں۔\n14۔ اور اس نے پہلی کا نام جمائما پکارا؛ اور دوسرے کا نام، کیزیا؛ اور تیسرے کا نام، کیرن ہاپوچ۔\n15۔ اور پورے ملک میں کوئی عورت اتنی خوبصورت نہیں تھی جتنی ایوب کی بیٹیاں تھیں: اور ان کے والد نے انہیں ان کے بھائیوں میں وراثت دی۔\n16۔ اس کے بعد ایوب ایک سو چالیس سال زندہ رہا، اور اس نے اپنے بیٹوں اور بیٹوں کے بیٹوں کو چار نسلوں تک دیکھا۔\n17۔ یوں ایوب مر گیا، {بوڑھا} اور دنوں سے بھرا ہوا۔"];
